#!/usr/bin/env bash
# dpistack-install.sh: the dpistack installer in one file.
# Generated by scripts/bundle.sh from install.sh, lib/, templates/, bin/ and
# tests/data/; edit those and run scripts/bundle.sh, not this file.
#
# It unpacks the files into a temporary directory and runs install.sh from
# there with the same arguments. A ready panel binary (dpistack-panel-linux-
# amd64 or -arm64) or the panel/ directory is looked for next to this file.
set -uo pipefail

if [[ -f "${BASH_SOURCE[0]:-}" ]]; then
	DPISTACK_ORIGIN_DIR="$(cd -- "$(dirname -- "$(readlink -f -- "${BASH_SOURCE[0]}")")" &>/dev/null && pwd)"
else
	DPISTACK_ORIGIN_DIR="$PWD"
fi
export DPISTACK_ORIGIN_DIR

bundle_dir="$(mktemp -d)" || exit 1
trap 'rm -rf "$bundle_dir"' EXIT

# put <path> <mode>: the file's content comes on stdin
put() {
	mkdir -p "$(dirname "$bundle_dir/$1")"
	cat >"$bundle_dir/$1"
	chmod "$2" "$bundle_dir/$1"
}

# put_b64 <path> <mode>: the same for a binary file, in base64
put_b64() {
	mkdir -p "$(dirname "$bundle_dir/$1")"
	base64 -d >"$bundle_dir/$1"
	chmod "$2" "$bundle_dir/$1"
}

put install.sh 755 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Entry point for both the pre-install invocation (install.sh) and,
# once selfinstall has run, the persistent `dpistack` command
# (tech.md 4.4, 5.1, 5.2). Slice 1 wires the CLI, config layering and
# an all-stub step pipeline; components fill in their steps later.
set -uo pipefail

# readlink -f: `dpistack` is a symlink to the installed install.sh.
SCRIPT_DIR=$(cd -- "$(dirname -- "$(readlink -f -- "${BASH_SOURCE[0]}")")" &>/dev/null && pwd)
LIB_DIR="$SCRIPT_DIR/lib"
# Where things that do not travel inside the installer lie: the panel
# source or a prebuilt binary. Next to install.sh unless dpistack-install.sh
# (one file, unpacked elsewhere) says otherwise.
# shellcheck disable=SC2034 # read by lib/step_panel.sh and step_preflight.sh
ORIGIN_DIR="${DPISTACK_ORIGIN_DIR:-$SCRIPT_DIR}"

# shellcheck source=lib/paths.sh
source "$LIB_DIR/paths.sh"
# shellcheck source=lib/common.sh
source "$LIB_DIR/common.sh"
# shellcheck source=lib/os.sh
source "$LIB_DIR/os.sh"
# shellcheck source=lib/state.sh
source "$LIB_DIR/state.sh"
# shellcheck source=lib/schema.sh
source "$LIB_DIR/schema.sh"
# shellcheck source=lib/config.sh
source "$LIB_DIR/config.sh"
# shellcheck source=lib/render.sh
source "$LIB_DIR/render.sh"
# shellcheck source=lib/menu.sh
source "$LIB_DIR/menu.sh"
# shellcheck source=lib/runtime_docker.sh
source "$LIB_DIR/runtime_docker.sh"
# shellcheck source=lib/ips.sh
source "$LIB_DIR/ips.sh"

STEPS_ORDER=(preflight selfinstall ndpi suricata rules redis ntopng evebox metrics nodeexp grafana access panel watch verify)
for _step in "${STEPS_ORDER[@]}"; do
	# shellcheck disable=SC1090
	source "$LIB_DIR/step_${_step}.sh"
done
unset _step

# step_call <check|apply|plan> <step> [args] - runs a step function; the
# steps of a switched-off component report "no changes" and do nothing.
step_call() {
	local fn="$1" name="$2"
	shift 2
	if ! step_component_enabled "$name"; then
		[[ "$fn" == "plan" ]] && echo "${name}: switched off by its *_ENABLE key, skipped"
		return 0
	fi
	"step_${name}_${fn}" "$@"
}
# shellcheck source=lib/ctl.sh
source "$LIB_DIR/ctl.sh"

BIN_NAME="$(basename -- "$0")"
# Test hook: every argument is a verb. Not inherited by the installer that
# `reconfigure` starts.
VERBS_ONLY="${DPISTACK_VERBS_ONLY:-0}"
unset DPISTACK_VERBS_ONLY

NON_INTERACTIVE=0
ADVANCED=0
FAST=0
DRY_RUN=0
CONFIG_FILE=""
SET_ARGS=()
ONLY_STEPS=""
SKIP_STEPS=""
FORCE=0
PURGE=0
CLI_NO_COLOR=0
COMMAND=""

usage() {
	echo "dpistack v${DPISTACK_VERSION}"
	cat <<'EOF'
Usage: install.sh [command] [options]
       install.sh             (no command, on a terminal) opens the install menu
       install.sh --fast      the short questions first (interfaces, Suricata source, access, metrics, panel)

setup:      install | reconfigure | upgrade | uninstall | diag
control:    status [--json] | start|stop|restart <id> | reload suricata | logs <id> | test | health |
            settings | config-read|config-write|config-revert | rules-* | iface | mode | fw |
            panel-passwd | version   (full list: dpistack help)
dpistack without a command opens the menu: install if there is no config, control otherwise.
Runs as root only (sudo dpistack ...).
options:
  --config FILE          path to dpistack.conf (default /etc/dpistack/dpistack.conf)
  --set KEY=VALUE        override a key, may be repeated
  --non-interactive, -y  no questions; missing values take their defaults
  --fast                 install: the short questionnaire instead of the guided setup that asks every setting
  --advanced             ask every key, not only the basic level
  --dry-run              show the plan, change nothing
  --only STEP[,STEP]     run only the given steps
  --skip STEP[,STEP]     skip steps
  --force                overwrite hand-edited files (with a backup)
  --purge                for uninstall: also remove data and configs
  --no-color             no ANSI colors in the menu and output

diag collects a report for troubleshooting (platform, versions, repositories, config without secrets,
services, logs) to stdout and to the DIAG_OUT file (by default a new temporary file, its path is printed).
EOF
}

# require_value <option> <argument count left> - an option that takes a value
# and got none: `shift 2` would not move and the loop would spin forever.
require_value() {
	if (($2 < 2)); then
		echo "option $1 needs a value" >&2
		usage
		exit 2
	fi
}

parse_args() {
	if [[ $# -eq 0 ]]; then
		usage
		exit 2
	fi
	COMMAND="$1"
	shift
	while [[ $# -gt 0 ]]; do
		case "$1" in
		--config)
			require_value "$1" "$#"
			CONFIG_FILE="${2:-}"
			shift 2
			;;
		--set)
			require_value "$1" "$#"
			SET_ARGS+=("${2:-}")
			shift 2
			;;
		--non-interactive | -y)
			NON_INTERACTIVE=1
			shift
			;;
		--advanced)
			ADVANCED=1
			shift
			;;
		--fast)
			FAST=1
			shift
			;;
		--dry-run)
			DRY_RUN=1
			shift
			;;
		--only)
			require_value "$1" "$#"
			ONLY_STEPS="${2:-}"
			shift 2
			;;
		--skip)
			require_value "$1" "$#"
			SKIP_STEPS="${2:-}"
			shift 2
			;;
		--force)
			FORCE=1
			shift
			;;
		--purge)
			# shellcheck disable=SC2034 # consumed by uninstall's slice
			PURGE=1
			shift
			;;
		--no-color)
			CLI_NO_COLOR=1
			shift
			;;
		-h | --help)
			usage
			exit 0
			;;
		*)
			echo "unknown option: $1" >&2
			usage
			exit 2
			;;
		esac
	done
}

step_selected() {
	# step_selected <name> -> 0 if it should run given --only/--skip
	local name="$1"
	if [[ -n "$ONLY_STEPS" ]]; then
		[[ ",$ONLY_STEPS," == *",$name,"* ]] && return 0
		return 1
	fi
	if [[ -n "$SKIP_STEPS" ]]; then
		[[ ",$SKIP_STEPS," == *",$name,"* ]] && return 1
	fi
	return 0
}

validate_step_names() {
	local list="$1" label="$2"
	[[ -z "$list" ]] && return 0
	local name
	local IFS=','
	for name in $list; do
		local known=0
		local s
		for s in "${STEPS_ORDER[@]}"; do
			[[ "$s" == "$name" ]] && known=1
		done
		if [[ "$known" -ne 1 ]]; then
			die 2 "$label: unknown step $name"
		fi
	done
}

# have_input_source - the menu has somewhere to read from: DPISTACK_INPUT, a
# terminal on stdin, or (a run fed through a pipe: stdin is the script) the terminal device
# itself. DPISTACK_TTY_DEV replaces /dev/tty, the tests use it.
have_input_source() {
	[[ -n "${DPISTACK_INPUT:-}" ]] && return 0
	[[ -t 0 ]] && return 0
	{ : <"${DPISTACK_TTY_DEV:-/dev/tty}"; } 2>/dev/null
}

layer_config_common() {
	config_reset
	config_load_defaults
	config_load_kv_file "$(path_conf)"
	config_load_kv_file "$(path_secrets)"
	config_apply_env_secrets
	[[ -n "$CONFIG_FILE" ]] && config_load_kv_file "$CONFIG_FILE"
	local kv
	for kv in "${SET_ARGS[@]}"; do
		config_apply_set "$kv" || die 2 "$(config_apply_set "$kv")"
	done
}

maybe_run_install_menu() {
	if [[ "$NON_INTERACTIVE" == "1" ]]; then
		return 0
	fi
	if ! have_input_source; then
		die 2 "no terminal for the menu, use -y or DPISTACK_INPUT"
	fi
	MENU_SHOW_ADVANCED=$([[ "$ADVANCED" == "1" ]] && echo 1 || echo 0)
	MENU_FAST="$FAST"
	menu_run_install
}

maybe_run_reconfigure_menu() {
	if [[ "$NON_INTERACTIVE" == "1" ]]; then
		return 0
	fi
	if ! have_input_source; then
		die 2 "no terminal for the menu, use -y or DPISTACK_INPUT"
	fi
	MENU_SHOW_ADVANCED=$([[ "$ADVANCED" == "1" ]] && echo 1 || echo 0)
	menu_run_reconfigure
	# "Back" from the management menu: nothing to apply.
	[[ $? -eq 20 ]] && exit 0
}

validate_or_die() {
	local out rc
	out=$(config_validate)
	rc=$?
	if [[ "$rc" -ne 0 ]]; then
		echo "The config failed validation:" >&2
		echo "$out" >&2
		exit 2
	fi
}

run_plan() {
	local total=${#STEPS_ORDER[@]}
	local i=0
	local any_pending=0
	for name in "${STEPS_ORDER[@]}"; do
		i=$((i + 1))
		step_selected "$name" || continue
		if step_call check "$name"; then
			echo "[$i/$total] $name ... no changes"
		else
			any_pending=1
			echo "[$i/$total] $name ... needs applying"
			step_call plan "$name" | sed 's/^/    /'
		fi
	done
	return "$any_pending"
}

# autodetect_iface - IFACES still holds the schema default enp2s0 and that
# interface does not exist here (eth0, ens3, a renamed NIC...): take the
# interface of the default route instead of failing the preflight. A
# value anyone typed is never replaced.
autodetect_iface() {
	[[ "${CONF[IFACES]:-}" == "enp2s0" ]] && ! net_iface_exists enp2s0 || return 0
	local found
	found=$(net_default_iface)
	[[ -n "$found" ]] || return 0
	echo "IFACES: interface enp2s0 does not exist, took $found (the default-route interface)" >&2
	CONF[IFACES]="$found"
}

# ensure_preflight_tools - the preflight itself calls ss and curl, and a
# minimal image has neither: install them first, but only when missing
# and only for a real run.
ensure_preflight_tools() {
	[[ "$DRY_RUN" == "1" || "${EUID:-$(id -u)}" -ne 0 ]] && return 0
	command -v ss >/dev/null 2>&1 && command -v curl >/dev/null 2>&1 && return 0
	pkg_update_once || die 1 "updating the package index failed"
	case "$OS_FAMILY" in
	apt) pkg_install iproute2 curl ca-certificates || die 1 "could not install iproute2 and curl" ;;
	esac
}

# install_command_early - the selfinstall step does not depend on any
# component, so it runs before the preflight and a failed preflight no
# longer leaves a host without the `dpistack` command. A failure here is a
# warning: the install itself can still go on from the clone.
install_command_early() {
	[[ "$DRY_RUN" == "1" || "${EUID:-$(id -u)}" -ne 0 ]] && return 0
	step_selected selfinstall || return 0
	step_selfinstall_check && return 0
	if step_selfinstall_apply; then
		echo "the command dpistack is installed in $(path_sbin_dir)" >&2
	else
		echo "warning: could not install the dpistack command, the install goes on from this directory" >&2
	fi
}

# prepare_packages - the package index and the base tools come first, so
# every later step finds its packages. A component whose package does not
# exist here falls back to a source build, and the changed source is saved
# to dpistack.conf and checked against the preflight again (a build needs
# more disk than a package).
prepare_packages() {
	pkg_update_once || die 1 "updating the package index failed"
	pkg_install_base || die 1 "could not install the base packages"
	pkg_enable_extra_repos || die 1 "could not enable the extra repositories (EPEL, CRB)"
	local fallback=0
	suricata_resolve_source && fallback=1
	ndpi_resolve_source && fallback=1
	if [[ "$fallback" == "1" ]]; then
		if [[ "$DRY_RUN" != "1" ]]; then
			config_write_conf "$(path_conf)"
			config_snapshot_applied
		fi
		step_preflight_check || exit 3
	fi
}

run_apply() {
	local total=${#STEPS_ORDER[@]}
	local i=0
	for name in "${STEPS_ORDER[@]}"; do
		i=$((i + 1))
		step_selected "$name" || continue
		if step_call check "$name"; then
			continue
		fi
		if ! step_call apply "$name"; then
			die 1 "step $name failed, to continue: install.sh install --only $name"
		fi
		if step_call check "$name"; then
			state_set_step_done "$name"
			echo "[$i/$total] $name ... done"
		else
			# A step can legitimately still report drift after a clean
			# apply (5.4: a manually edited file is left alone with a
			# notice, not overwritten) - that isn't a failed apply.
			echo "[$i/$total] $name ... partly applied, see the notes above"
		fi
	done
}

cmd_install() {
	validate_step_names "$ONLY_STEPS" "--only"
	validate_step_names "$SKIP_STEPS" "--skip"
	lock_acquire
	os_detect

	layer_config_common
	maybe_run_install_menu
	panel_password_apply
	config_generate_metrics_token_if_needed
	validate_or_die
	autodetect_iface

	echo "Final config:"
	config_print_summary
	if [[ "$PANEL_PASSWORD_JUST_GENERATED" == "1" ]]; then
		echo "Panel password created (save it: it is shown nowhere else, only a hash stays on disk): $PANEL_PASSWORD_GENERATED_VALUE"
	fi

	if [[ "$DRY_RUN" != "1" ]]; then
		config_write_conf "$(path_conf)"
		config_snapshot_applied
		config_write_secrets "$(path_secrets)"
	fi

	ensure_preflight_tools

	# The persistent command comes first: when the preflight below stops the
	# install, `sudo dpistack` still exists and the saved answers are still
	# there, so the next run is `sudo dpistack install` after the fix.
	install_command_early

	if ! step_preflight_check; then
		echo "preflight failed, nothing was installed. Your answers are saved in $(path_conf)." >&2
		echo "Fix the problems above (or change the setting named in the message), then run: sudo dpistack install" >&2
		exit 3
	fi

	prepare_packages

	run_plan
	local pending=$?

	if [[ "$DRY_RUN" == "1" ]]; then
		echo "dry-run: the plan is shown, the config is not written"
		return 0
	fi

	if [[ "$pending" -ne 0 ]]; then
		run_apply
		selinux_relabel_installed
	fi
	verify_final_report
	panel_report_metrics
	state_write_value install.finished yes
	echo "installation finished"
	return 0
}

cmd_reconfigure() {
	validate_step_names "$ONLY_STEPS" "--only"
	validate_step_names "$SKIP_STEPS" "--skip"
	lock_acquire
	os_detect

	if [[ ! -f "$(path_conf)" ]]; then
		die 2 "config not found, run first: install.sh install"
	fi

	layer_config_common
	maybe_run_reconfigure_menu
	config_generate_metrics_token_if_needed
	validate_or_die

	config_diff_and_steps "$(path_conf)"

	if [[ "$CONFIG_CHANGE_WEIGHT" == "none" ]]; then
		echo "no changes"
		return 0
	fi

	if [[ "$DRY_RUN" == "1" ]]; then
		return 0
	fi

	# The interactive menu (lib/menu.sh) already ran this exact
	# confirmation and suricata -T check from inside its own input loop
	# before returning - redoing it here would both duplicate the
	# prompt and reread DPISTACK_INPUT from byte 0 (the menu's fd 8 is
	# already closed by now), landing on the wrong line.
	if [[ "$MENU_ALREADY_CONFIRMED" != "1" ]]; then
		if [[ "$CONFIG_CHANGE_WEIGHT" == "heavy" ]]; then
			if [[ "$NON_INTERACTIVE" == "1" ]]; then
				if [[ "$FORCE" != "1" ]]; then
					die 3 "heavy changes in non-interactive mode need --force"
				fi
			else
				die 3 "heavy changes need confirmation, there is no terminal to ask"
			fi
		fi

		# criterion 4 (slice 8): validate the new suricata.yaml with a
		# real `suricata -T` before touching anything on disk, so a
		# failed check leaves the old suricata.yaml and dpistack.conf
		# alone. (Non-interactive -y path only now; see above.)
		local step
		for step in "${CONFIG_AFFECTED_STEPS[@]}"; do
			if [[ "$step" == "suricata" ]]; then
				if ! suricata_validate_render "$(suricata_render_yaml)"; then
					die 1 "suricata -T failed on the new suricata.yaml, changes not applied (see the output above)"
				fi
			fi
		done
	fi

	panel_password_apply
	config_write_conf "$(path_conf)"
	config_snapshot_applied
	config_write_secrets "$(path_secrets)"

	# A changed key can make a step install a package (nginx, a new version).
	if [[ "${#CONFIG_AFFECTED_STEPS[@]}" -gt 0 ]]; then
		pkg_update_once || die 1 "updating the package index failed"
	fi
	for step in "${CONFIG_AFFECTED_STEPS[@]}"; do
		step_selected "$step" || continue
		if ! step_call apply "$step"; then
			die 1 "step $step failed during reconfigure"
		fi
	done
	selinux_relabel_installed

	panel_report_metrics
	echo "config applied"
	return 0
}

cmd_upgrade() {
	lock_acquire
	os_detect
	if [[ ! -f "$(path_conf)" ]]; then
		die 2 "config not found, run first: install.sh install"
	fi
	layer_config_common

	local -a packages=()
	case "${CONF[SURICATA_SOURCE]:-}" in
	distro | oisf) packages+=("$SURICATA_PACKAGE") ;;
	esac
	command -v redis-server >/dev/null 2>&1 && packages+=("$REDIS_PACKAGE")
	command -v ntopng >/dev/null 2>&1 && packages+=("$NTOPNG_PACKAGE")
	command -v evebox >/dev/null 2>&1 && packages+=("$EVEBOX_PACKAGE")

	if [[ "${#packages[@]}" -eq 0 ]]; then
		echo "nothing to upgrade"
		return 0
	fi

	if [[ "${CONF[PIN_VERSIONS]:-no}" == "yes" ]]; then
		echo "upgrade: PIN_VERSIONS=yes - the package manager will skip pinned packages (apt-mark hold, dnf versionlock): ${packages[*]}"
	fi
	# Without a fresh index an upgrade never sees a newer version.
	pkg_update_once || die 1 "updating the package index failed"
	pkg_upgrade "${packages[@]}" || die 1 "upgrading packages failed"
	return 0
}

# uninstall removes only what dpistack itself created (its own units,
# its own rendered nginx snippet, its own conf/state). It never stops,
# disables, or removes the underlying Suricata/Redis/ntopng/EveBox
# packages or services - "keeps data and configs" (5.7) reads most
# safely as "leave the working stack alone", not as "tear down a
# production IDS because its manager was uninstalled". --purge extends
# this to those components' own rendered configs/data, but still never
# touches packages (5.7's exemption for pre-existing packages is hard
# to honour precisely without real install-provenance tracking, so the
# conservative reading - never remove packages at all - was chosen).
# uninstall_rm_tree <path> - rm -rf of one directory dpistack made. Refuses
# an empty path or "/" so that a wrong variable can never reach the host.
uninstall_rm_tree() {
	local d="$1"
	[[ -n "$d" && "$d" != "/" && "$d" != "${DPISTACK_ROOT}/" ]] || return 0
	rm -rf -- "$d"
}

# uninstall_docker_stack <purge> - the containers of the docker runtime are
# dpistack's own: the compose project is taken down (containers of other
# projects are not in it), the compose file goes, and the panel images
# dpistack built go. With purge the pulled images go too, but `docker image
# rm` refuses an image that another container still uses, so those stay.
uninstall_docker_stack() {
	local purge="$1" svc img
	command -v docker >/dev/null 2>&1 || return 0
	if [[ -f "$(path_compose_yaml)" ]]; then
		docker_compose_argv
		run "${DOCKER_COMPOSE_ARGV[@]}" down --remove-orphans || echo "warning: docker compose down failed, the containers may need a manual removal" >&2
	fi
	while read -r img; do
		if [[ -n "$img" ]]; then run docker image rm "$img" >/dev/null 2>&1 || true; fi
	done < <(docker image ls --format '{{.Repository}}:{{.Tag}}' 2>/dev/null | grep '^dpistack-panel:' || true)
	if [[ "$purge" == "1" ]]; then
		for svc in suricata evebox ntopng redis victoriametrics prometheus node_exporter grafana; do
			img=$(docker_image "$svc" 2>/dev/null) || continue
			if [[ -n "$img" ]]; then run docker image rm "$img" >/dev/null 2>&1 || true; fi
		done
	fi
	rm -f "$(path_compose_yaml)"
	rmdir "$(dirname "$(path_compose_yaml)")" 2>/dev/null || true
}

# uninstall_built_from_source - Suricata and nDPI built by dpistack leave
# files in /usr/local; the build tree knows exactly which ones, so the build
# system's own uninstall target removes them and nothing else.
uninstall_built_from_source() {
	local d
	for d in "$(path_suricata_src_dir)" "$(path_ndpi_src_dir)"; do
		if [[ -f "$d/Makefile" ]]; then run make -C "$d" uninstall >/dev/null 2>&1 || true; fi
		uninstall_rm_tree "$d"
	done
	rm -f "$(path_suricata_ndpi_plugin)"
}

cmd_uninstall() {
	lock_acquire
	os_detect

	if [[ ! -f "$(path_conf)" ]]; then
		echo "nothing to remove"
		return 0
	fi

	layer_config_common

	if [[ "$DRY_RUN" == "1" ]]; then
		# Everything below removes files with plain rm: a dry run only lists.
		echo "dry-run: uninstall would stop and remove the dpistack timers and services, the DPISTACK chain, the mode drop-in (Suricata running in NFQ is restarted), the ufw/firewalld rules dpistack added, the configs ($(path_conf), $(path_secrets)), the state ($(path_state_dir)) and the program copies; nothing changed"
		[[ "$PURGE" == "1" ]] && echo "dry-run: with --purge also the configs and component data (suricata.yaml, rules, ntopng, EveBox, TLS, metrics data, users)"
		return 0
	fi

	run systemctl disable --now "$RULES_TIMER" 2>/dev/null || true
	rm -f "$(path_rules_timer_unit)" "$(path_rules_service_unit)"
	run systemctl daemon-reload

	# The DPISTACK chain and the boot unit that restores it are dpistack's
	# own; foreign chains and rules are not touched (lib/ips.sh).
	if [[ "$DRY_RUN" == "1" ]]; then
		echo "dry-run: iptables: remove the jumps to DPISTACK and the chain itself, delete $(path_fw_unit)"
	else
		ips_fw_remove
	fi
	run systemctl disable dpistack-fw.service 2>/dev/null || true
	# Suricata started by the IPS drop-in sits on the queue (-q 0). With the
	# drop-in gone it must be started again, or it keeps listening to a queue
	# that nothing feeds any more instead of capturing like a plain install.
	local was_ips=0
	[[ -e "$(path_suricata_mode_dropin)" ]] && was_ips=1
	rm -f "$(path_fw_unit)" "$(path_suricata_mode_dropin)"
	run systemctl daemon-reload
	if [[ "$was_ips" == 1 && "${CONF[SURICATA_SOURCE]:-}" != "source" ]]; then
		run systemctl restart "$SURICATA_UNIT" 2>/dev/null || true
	fi

	# ufw and firewalld rules that dpistack added (and only those).
	access_firewall_forget || true

	# The metrics backend is dpistack's own addition (unlike the packages of
	# the stack): stopped, its unit and binaries removed; the series stay
	# unless --purge.
	if [[ -n "$(metrics_installed)" ]]; then
		metrics_stop_installed || true
		rm -f "$(path_vm_unit)" "$(path_prometheus_unit)" "$(path_vm_bin)" "$(path_prometheus_bin)"
		run systemctl daemon-reload
	fi

	# node_exporter and Grafana are dpistack's own additions too.
	if [[ -n "$(nodeexp_installed)" ]]; then
		nodeexp_stop_installed || true
		rm -f "$(path_nodeexp_unit)" "$(path_nodeexp_bin)"
	fi
	if [[ -n "$(grafana_installed)" ]]; then
		grafana_stop_installed || true
		rm -rf "$(path_grafana_unit)" "$(path_grafana_home)"
	fi
	run systemctl daemon-reload

	if [[ "${CONF[SURICATA_SOURCE]:-}" == "source" ]]; then
		run systemctl disable --now "$SURICATA_UNIT" 2>/dev/null || true
		rm -f "$(path_suricata_service_unit)"
		run systemctl daemon-reload
	fi

	if [[ "${CONF[ACCESS_MODE]:-}" == "nginx" && "${CONF[NGINX_MANAGE]:-}" == "yes" ]]; then
		rm -f "$(path_nginx_confd)"
		run systemctl reload "$NGINX_UNIT" 2>/dev/null || true
	fi
	rm -f "$(path_nginx_snippet)"

	if [[ "$PURGE" == "1" ]]; then
		rm -f "$(path_suricata_yaml)" "$(path_suricata_logrotate)" \
			"$(path_suricata_enable_conf)" "$(path_suricata_disable_conf)" \
			"$(path_suricata_modify_conf)" "$(path_suricata_drop_conf)"
		rm -rf "$(dirname "$(path_suricata_ruleset)")"
		rm -f "$(path_ntopng_conf)" "$(path_evebox_yaml)"
		rm -rf "$(access_tls_dir)" 2>/dev/null || true
		rm -rf "$(path_metrics_data_dir)"
		if id "$METRICS_USER" >/dev/null 2>&1; then
			run userdel "$METRICS_USER" || true
		fi
		if id "$PANEL_USER" >/dev/null 2>&1; then
			run userdel "$PANEL_USER" || true
		fi
		# dpistack's own data and additions of the stack (never the packages)
		uninstall_rm_tree "$(path_evebox_data_dir)"
		uninstall_rm_tree "$(path_grafana_data_dir)"
		rm -f "$(path_evebox_apt_list)" "$(path_evebox_keyring)" "$(path_ntop_repo_file)"
		uninstall_built_from_source
		echo "uninstall --purge: configs and component data removed (packages, Docker itself and anything dpistack did not create are untouched)"
	fi

	# dpistack's own small files, with or without --purge
	rm -f "$(path_metrics_token)" "$(path_grafana_ini)"
	uninstall_rm_tree "$(path_grafana_prov_dir)"

	run systemctl disable --now "$WATCH_TIMER" 2>/dev/null || true
	rm -f "$(path_watch_timer_unit)" "$(path_watch_service_unit)" "$(path_sudoers)"
	run systemctl disable --now "$PANEL_SERVICE" 2>/dev/null || true
	# every container of the docker runtime, not only the panel
	uninstall_docker_stack "$PURGE"
	rm -f "$(path_panel_service_unit)" "$(path_panel_bin)"
	run systemctl daemon-reload

	rm -f "$(path_conf)" "$(path_conf_draft)" "$(path_secrets)" "$(path_panel_auth)"
	rmdir "$(dirname "$(path_conf)")" 2>/dev/null || true
	rmdir "${DPISTACK_ROOT}/opt/dpistack" "$(path_log_dir)" 2>/dev/null || true
	rm -rf "$(path_state_dir)"

	# Last, because `dpistack uninstall` runs from the copy it removes.
	rm -f "$(path_dpistack_bin)" "$(path_retired_ctl)" "$(path_watch_bin)"
	rm -rf "$(path_installer_copy_dir)"

	# The install log goes last: every step above still writes to it.
	[[ "$PURGE" == "1" ]] && uninstall_rm_tree "$(path_log_dir)"

	echo "done"
	return 0
}

cmd_status() {
	os_detect
	layer_config_common
	local name
	for name in "${STEPS_ORDER[@]}"; do
		if step_call check "$name"; then
			echo "$name: ok"
		else
			echo "$name: mismatch"
		fi
	done
}

# cmd_diag - one text report for a bug report: system, versions,
# repositories, configuration without secrets, service state and the tail
# of the logs. Read-only. The report also goes to a file (DIAG_OUT, else a
# new private mktemp file); tokens, passwords and credentials in URLs are
# replaced before anything is printed.
diag_section() {
	printf '\n===== %s =====\n' "$1"
	shift
	"$@" 2>&1 || echo "(rc=$?)"
}

diag_tool_versions() {
	local tool
	for tool in suricata evebox ntopng nginx redis-server rustc gcc git curl; do
		if command -v "$tool" >/dev/null 2>&1; then
			printf '%s: ' "$tool"
			"$tool" --version 2>&1 | head -n 1
		else
			echo "$tool: missing"
		fi
	done
}

diag_packages() {
	case "$OS_FAMILY" in
	apt) dpkg -l 2>/dev/null | grep -E ' (suricata|libndpi|ntopng|evebox|redis|nginx|ufw|iproute2)' ;;
	dnf) rpm -qa 2>/dev/null | grep -Ei '^(suricata|ndpi|ntopng|evebox|redis|valkey|nginx|firewalld)' ;;
	esac
}

diag_repos() {
	case "$OS_FAMILY" in
	apt)
		grep -hvE '^[[:space:]]*(#|$)' "$(path_apt_dir)/sources.list" "$(path_apt_dir)"/sources.list.d/*.list "$(path_apt_dir)"/sources.list.d/*.sources 2>/dev/null
		;;
	dnf)
		dnf -q repolist 2>&1
		;;
	esac
}

diag_units() {
	local unit
	for unit in "$SURICATA_UNIT" "$REDIS_UNIT" "$EVEBOX_UNIT" "$NTOPNG_UNIT" "$NGINX_UNIT" "$WATCH_TIMER"; do
		printf '%-28s active=%s enabled=%s\n' "$unit" \
			"$(systemctl is-active "$unit" 2>&1)" "$(systemctl is-enabled "$unit" 2>&1)"
	done
	systemctl --failed --no-pager 2>&1 | head -n 15
}

diag_report() {
	echo "dpistack v${DPISTACK_VERSION}, $(date -u +%Y-%m-%dT%H:%M:%SZ)"
	diag_section "platform" bash -c "echo \"$OS_ID $OS_VERSION_ID family=$OS_FAMILY level=\$1\"; cat \"$(path_os_release)\"; uname -a; nproc; free -m | sed -n 1,2p; df -h / | tail -n 1" _ "$(os_support_level)"
	diag_section "versions" diag_tool_versions
	if command -v suricata >/dev/null 2>&1; then
		diag_section "suricata --build-info" bash -c 'suricata --build-info 2>&1 | grep -E "^This is|Rust|nDPI|AF_PACKET|Features"'
	fi
	diag_section "packages" diag_packages
	diag_section "repositories" diag_repos
	diag_section "dpistack.conf" cat "$(path_conf)"
	diag_section "state" bash -c "grep -vE '^(file_hash|applied)\\.' \"$(path_state_file)\" 2>/dev/null"
	diag_section "services" diag_units
	diag_section "network" bash -c "ip -br addr 2>/dev/null; ss -ltn 2>/dev/null | head -n 25"
	diag_section "SELinux and firewall" bash -c "getenforce 2>&1; (ufw status 2>/dev/null || firewall-cmd --state 2>&1) | head -n 8"
	if command -v suricata >/dev/null 2>&1 && [[ -f "$(path_suricata_yaml)" ]]; then
		diag_section "suricata -T" bash -c "suricata -T -c \"$(path_suricata_yaml)\" 2>&1 | tail -n 12"
	fi
	diag_section "dpistack log (last 80 lines)" bash -c "tail -n 80 \"$(path_install_log)\" 2>&1"
	if command -v journalctl >/dev/null 2>&1; then
		diag_section "journalctl (suricata, evebox, ntopng)" bash -c 'journalctl -u suricata -u evebox -u ntopng -n 40 --no-pager 2>&1'
	fi
}

cmd_diag() {
	os_detect >/dev/null 2>&1 || true
	local out="${DIAG_OUT:-$(mktemp -t dpistack-diag.XXXXXX)}"
	diag_report 2>&1 |
		sed -E 's/((TOKEN|PASSWORD|PASS|SECRET)[A-Z_]*=).*/\1<hidden>/; s#(://)[^/@[:space:]]+:[^/@[:space:]]+@#\1<hidden>@#g' |
		tee "$out"
	echo "report saved: $out" >&2
}

# require_root - dpistack changes the system and reads secrets: it runs as
# root or not at all. The panel gets there through `sudo -n`, which makes
# the process root as well.
require_root() {
	if [[ "$(id -u)" -ne 0 ]]; then
		echo "dpistack: the command runs as root only (sudo dpistack ...)" >&2
		exit 1
	fi
}

# The verbs that act on an installed system (tech.md 4.5). `status` and
# `reconfigure` also exist as installer commands: see dispatch_ctl.
CTL_VERBS=(status start stop restart reload logs config-read config-write config-revert settings
	reconfigure rules-update rules-sources rules-group rules-sid rules-search iface mode
	mode-confirm mode-rollback fw panel-passwd test health version self-update)

# restricted_caller - the panel (and nothing else) comes through sudo as
# the panel user. It gets the verbs above and no installer command: a stolen
# panel session cannot run install, uninstall or upgrade. The one exception is
# `self-update run|job` (the Update button): it installs only a newer release
# of the project itself, never anything the caller names.
restricted_caller() {
	[[ -n "${SUDO_USER:-}" && "$SUDO_USER" == "$PANEL_USER" ]] ||
		[[ "${DPISTACK_CALLER:-}" == "panel" ]]
}

# dispatch_ctl <args...> - returns 0 after running a verb (the caller exits
# with its code through exit inside ctl_main); returns 1 when the arguments
# are an installer command.
dispatch_ctl() {
	local verb="${1:-}" arg
	# The panel is restricted to the control verbs. DPISTACK_VERBS_ONLY=1 is
	# a test hook: every argument is a verb, `reconfigure` included.
	if [[ "$VERBS_ONLY" == "1" ]] || restricted_caller; then
		ctl_main "$@"
		exit $?
	fi
	in_list "$verb" "${CTL_VERBS[@]}" || return 1
	case "$verb" in
	reconfigure)
		# `reconfigure --light` is the non-interactive, light-only form.
		local -a rest=()
		local light=0
		shift
		for arg in "$@"; do
			if [[ "$arg" == "--light" ]]; then light=1; else rest+=("$arg"); fi
		done
		((light)) || return 1
		ctl_main reconfigure "${rest[@]}"
		exit $?
		;;
	status)
		if [[ "${2:-}" == "--json" ]]; then
			ctl_main "$@"
			exit $?
		fi
		return 1
		;;
	esac
	ctl_main "$@"
	exit $?
}

main() {
	require_root
	dispatch_ctl "$@" || true
	# No command: the menu that fits the state. Without a terminal or
	# DPISTACK_INPUT parse_args prints the usage as before.
	if [[ $# -eq 0 ]] && have_input_source; then
		if [[ "$BIN_NAME" == "dpistack" && -f "$(path_conf)" ]]; then
			os_detect
			menu_run_manage
			exit 0
		fi
		set -- install
	fi
	# An option first (`install.sh --fast`): the command is install.
	if [[ "${1:-}" == -* && "${1:-}" != "-h" && "${1:-}" != "--help" ]]; then
		set -- install "$@"
	fi
	parse_args "$@"
	case "$COMMAND" in
	install)
		cmd_install
		;;
	reconfigure)
		cmd_reconfigure
		;;
	upgrade)
		cmd_upgrade
		;;
	uninstall)
		cmd_uninstall
		;;
	status)
		# Components first (what runs), then the installer's own check of
		# every step (what differs from the configuration).
		ctl_main status
		echo
		echo "Install steps:"
		cmd_status
		;;
	diag)
		cmd_diag
		;;
	help | -h | --help)
		usage
		echo
		ctl_usage
		;;
	*)
		echo "unknown command: $COMMAND" >&2
		usage
		exit 2
		;;
	esac
}

main "$@"
DPISTACK_BUNDLE_END
put bin/dpistack-watch 755 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# dpistack watchdog (tech.md 8): one run per call, started by
# dpistack-watch.timer or by `dpistack health`. It writes
# health.json atomically and a line to events.jsonl for every status
# change. It repairs nothing unless WATCH_AUTORESTART=yes.
#
# Ready-made parts instead of new code: jq builds and reads the JSON,
# flock keeps two runs apart, `dpistack status --json` gives the
# component state through the runtime, and the schema supplies every
# default threshold.
set -uo pipefail

SCRIPT_DIR=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" &>/dev/null && pwd)
for _lib in "$SCRIPT_DIR/../lib" "$SCRIPT_DIR/../lib/dpistack/installer/lib"; do
	if [[ -r "$_lib/paths.sh" && -r "$_lib/common.sh" ]]; then
		# shellcheck source=lib/paths.sh
		source "$_lib/paths.sh"
		# shellcheck source=lib/common.sh
		source "$_lib/common.sh"
		# shellcheck source=lib/state.sh
		source "$_lib/state.sh"
		# shellcheck source=lib/schema.sh
		source "$_lib/schema.sh"
		# shellcheck source=lib/config.sh
		source "$_lib/config.sh"
		break
	fi
done
unset _lib
if ! declare -F path_conf >/dev/null; then
	echo "dpistack-watch: lib/paths.sh not found" >&2
	exit 1
fi
command -v jq >/dev/null 2>&1 || {
	echo "dpistack-watch: jq is not installed" >&2
	exit 1
}

# awk prints decimals by the locale; "5,00" would break the JSON values.
export LC_NUMERIC=C

CTL="${DPISTACK_BIN:-$SCRIPT_DIR/dpistack}"
[[ -x "$CTL" ]] || CTL="$SCRIPT_DIR/../install.sh"
RESTARTS_PER_HOUR=3
PORT_CRIT_AFTER_MISSES=3 # missing for more than two runs in a row

# DPISTACK_NOW pins the clock for tests.
now() { echo "${DPISTACK_NOW:-$(date +%s)}"; }
iso() { date -u -d "@$1" +%Y-%m-%dT%H:%M:%SZ; }

CHECK_IDS=()
declare -A C_STATUS C_VALUE C_DETAIL

# record <id> <status> <value> <detail>
record() {
	CHECK_IDS+=("$1")
	C_STATUS[$1]="$2"
	C_VALUE[$1]="$3"
	C_DETAIL[$1]="$4"
}

# ge/le <number> <threshold>: at the threshold itself the worse status
# wins, the same way for every check (4.6 note).
ge() { awk -v a="$1" -v b="$2" 'BEGIN{exit !(a >= b)}'; }
le() { awk -v a="$1" -v b="$2" 'BEGIN{exit !(a <= b)}'; }

eve_checks_apply() {
	[[ "${CONF[EVE_FILE]}" == "yes" && ",${CONF[EVE_TYPES]}," == *",stats,"* ]]
}

declare -A COMP_STATE

load_component_states() {
	local out
	out=$("$CTL" status --json 2>/dev/null) || return 0
	while IFS=$'\t' read -r id state; do
		COMP_STATE[$id]="$state"
	done < <(jq -r '.components[] | [.id, .state] | @tsv' <<<"$out" 2>/dev/null)
}

check_process() {
	local id="$1" state="${COMP_STATE[$1]:-absent}"
	case "$state" in
	active) record "$id.process" ok "$state" "" ;;
	absent) record "$id.process" na "$state" "component not installed" ;;
	*) record "$id.process" crit "$state" "$id: $state" ;;
	esac
}

# backend_port <public-port> - with ACCESS_MODE=nginx the services listen
# on <public>+10000 behind nginx (tech.md 7, same rule as access_backend_port
# in the installer); the check must look at the service, not at nginx.
backend_port() {
	if [[ "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]]; then
		echo $(($1 + 10000))
	else
		echo "$1"
	fi
}

# component_port <id> - empty when the component has no port to check.
component_port() {
	case "$1" in
	evebox) backend_port "${CONF[EVEBOX_PORT]}" ;;
	ntopng) backend_port "${CONF[NTOPNG_PORT]}" ;;
	redis) echo 6379 ;;
	panel) backend_port "${CONF[PANEL_PORT]}" ;;
	victoriametrics | prometheus) echo "${CONF[METRICS_BACKEND_PORT]}" ;;
	node_exporter) echo "${CONF[NODE_EXPORTER_PORT]}" ;;
	grafana) echo "${CONF[GRAFANA_PORT]}" ;;
	esac
}

check_port() {
	local id="$1" port misses key
	port=$(component_port "$id")
	if [[ "${COMP_STATE[$id]:-absent}" == "absent" || -z "$port" ]]; then
		record "$id.port" na "" "component not installed"
		return
	fi
	key="watch.miss.$id"
	if ss -ltn 2>/dev/null | awk -v p=":$port\$" '$4 ~ p {f=1} END{exit !f}'; then
		state_write_value "$key" 0
		record "$id.port" ok "$port" ""
		return
	fi
	misses=$(state_read_value "$key")
	misses=$((${misses:-0} + 1))
	state_write_value "$key" "$misses"
	if ((misses >= PORT_CRIT_AFTER_MISSES)); then
		record "$id.port" crit "$port" "port $port is not listening for $misses runs in a row"
	else
		record "$id.port" warn "$port" "port $port is not listening"
	fi
}

check_eve_fresh() {
	if ! eve_checks_apply; then
		record suricata.eve_fresh na "" "EVE_FILE=no or no stats in EVE_TYPES"
		return
	fi
	local eve mtime age
	eve=$(path_suricata_eve_json)
	if [[ ! -f "$eve" ]]; then
		record suricata.eve_fresh warn "" "eve.json not found"
		return
	fi
	mtime=$(stat -c %Y "$eve")
	age=$(($(now) - mtime))
	if ge "$age" "${CONF[WATCH_EVE_STALE_SEC]}"; then
		record suricata.eve_fresh crit "$age" "no new events for $age s"
	else
		record suricata.eve_fresh ok "$age" ""
	fi
}

check_drop_rate() {
	if ! eve_checks_apply; then
		record suricata.drop_rate na "" "EVE_FILE=no or no stats in EVE_TYPES"
		return
	fi
	local eve
	eve=$(path_suricata_eve_json)
	if [[ ! -f "$eve" ]]; then
		record suricata.drop_rate na "" "eve.json not found"
		return
	fi
	# Only the tail is read, never the whole file (9: eve.json is not parsed whole).
	local rows p0 d0 p1 d1
	rows=$(tail -c 4194304 "$eve" | grep -F '"event_type":"stats"' | tail -n 2 |
		jq -r '[.stats.capture.kernel_packets, .stats.capture.kernel_drops] | select(all(. != null)) | @tsv' 2>/dev/null)
	if [[ $(wc -l <<<"$rows") -lt 2 ]]; then
		record suricata.drop_rate na "" "fewer than two stats events"
		return
	fi
	read -r p0 d0 < <(sed -n 1p <<<"$rows")
	read -r p1 d1 < <(sed -n 2p <<<"$rows")
	if ((p1 < p0 || d1 < d0)); then
		record suricata.drop_rate ok "" "counters were reset, the interval is skipped"
		return
	fi
	# Thresholds are compared as integers (drops*100 against pct*packets),
	# so a value just under a threshold is never rounded up onto it.
	local dp=$((p1 - p0)) dd=$((d1 - d0)) pct=0.00
	local crit_pct="${CONF[WATCH_DROP_CRIT_PCT]}" warn_pct="${CONF[WATCH_DROP_WARN_PCT]}"
	((dp > 0)) && pct=$(awk -v dp="$dp" -v dd="$dd" 'BEGIN{printf "%.2f", dd * 100 / dp}')
	if ((dp > 0)) && ge "$((dd * 100))" "$((crit_pct * dp))"; then
		record suricata.drop_rate crit "$pct" "drops $pct%"
	elif ((dp > 0)) && ge "$((dd * 100))" "$((warn_pct * dp))"; then
		record suricata.drop_rate warn "$pct" "drops $pct%"
	else
		record suricata.drop_rate ok "$pct" ""
	fi
}

check_disk_free() {
	local -a paths=()
	paths+=("$(dirname "$(path_suricata_eve_json)")")
	[[ "${CONF[EVEBOX_DB]}" == "sqlite" ]] && paths+=("$(path_evebox_data_dir)")
	# The series of the metrics backend are the fastest-growing data.
	[[ "${CONF[METRICS_BACKEND]:-none}" != "none" && -d "$(path_metrics_data_dir)" ]] && paths+=("$(path_metrics_data_dir)")
	local p total avail worst_total="" worst_avail="" worst_path=""
	for p in "${paths[@]}"; do
		[[ -d "$p" ]] || continue
		read -r total avail < <(df -P "$p" 2>/dev/null | awk 'NR==2 && $2 > 0 {print $2, $4}')
		[[ -n "${total:-}" ]] || continue
		# The smallest free share wins: avail/total, cross-multiplied.
		if [[ -z "$worst_total" ]] || awk -v a="$avail" -v t="$total" -v wa="$worst_avail" -v wt="$worst_total" 'BEGIN{exit !(a * wt <= wa * t)}'; then
			worst_total="$total"
			worst_avail="$avail"
			worst_path="$p"
		fi
	done
	if [[ -z "$worst_total" ]]; then
		record disk.free na "" "no directories to check"
		return
	fi
	local pct detail
	pct=$(awk -v a="$worst_avail" -v t="$worst_total" 'BEGIN{printf "%.2f", a * 100 / t}')
	detail="$worst_path: $pct% free"
	if awk -v a="$worst_avail" -v t="$worst_total" -v c="${CONF[WATCH_DISK_CRIT_PCT]}" 'BEGIN{exit !(a * 100 <= c * t)}'; then
		record disk.free crit "$pct" "$detail"
	elif awk -v a="$worst_avail" -v t="$worst_total" -v c="${CONF[WATCH_DISK_WARN_PCT]}" 'BEGIN{exit !(a * 100 <= c * t)}'; then
		record disk.free warn "$pct" "$detail"
	else
		record disk.free ok "$pct" "$detail"
	fi
}

check_rules_age() {
	if [[ "${CONF[RULES_UPDATE]}" == "off" || "${COMP_STATE[suricata]:-absent}" == "absent" ]]; then
		record rules.age na "" "rule updates are off or Suricata is not installed"
		return
	fi
	local rules mtime age_sec age_days crit_days="${CONF[WATCH_RULES_CRIT_DAYS]}" warn_days="${CONF[WATCH_RULES_WARN_DAYS]}"
	rules=$(path_suricata_ruleset)
	if [[ ! -f "$rules" ]]; then
		record rules.age warn "" "suricata.rules not found"
		return
	fi
	mtime=$(stat -c %Y "$rules")
	age_sec=$(($(now) - mtime))
	age_days=$(awk -v s="$age_sec" 'BEGIN{printf "%.2f", s / 86400}')
	if ge "$age_sec" "$((crit_days * 86400))"; then
		record rules.age crit "$age_days" "rules are $age_days days old"
	elif ge "$age_sec" "$((warn_days * 86400))"; then
		record rules.age warn "$age_days" "rules are $age_days days old"
	else
		record rules.age ok "$age_days" ""
	fi
}

rank() {
	case "$1" in
	ok) echo 0 ;;
	warn) echo 1 ;;
	crit) echo 2 ;;
	*) echo -1 ;;
	esac
}

# ---------------------------------------------------------------- alerts
# Channels are independent: a failing one writes its reason to stderr
# (the journal of the oneshot unit) and never stops the others or the
# events.jsonl line. Tokens and passwords travel to curl through
# `-K -` on stdin, so they are not visible in `ps` and never printed.

CHANNELS=()

channel_on() {
	local c
	for c in "${CHANNELS[@]}"; do
		[[ "$c" == "$1" ]] && return 0
	done
	return 1
}

channel_error() {
	echo "dpistack-watch: channel $1: $2" >&2
}

# curl_cfg_escape <text> - a value inside quotes of a curl config line.
curl_cfg_escape() {
	local t="$1"
	t="${t//\\/\\\\}"
	t="${t//\"/\\\"}"
	t="${t//$'\n'/ }"
	t="${t//$'\r'/ }"
	printf '%s' "$t"
}

alert_log() {
	local sev="$1" msg="$2"
	logger -t dpistack-watch -p "daemon.$sev" -- "$msg" || channel_error log "logger failed"
}

alert_tg() {
	local msg="$1" token="${SECRETS[ALERT_TG_TOKEN]:-}" chat="${CONF[ALERT_TG_CHAT_ID]:-}"
	if [[ -z "$token" || -z "$chat" ]]; then
		channel_error tg "ALERT_TG_TOKEN or ALERT_TG_CHAT_ID is not set"
		return 1
	fi
	printf 'url = "https://api.telegram.org/bot%s/sendMessage"\ndata-urlencode = "chat_id=%s"\ndata-urlencode = "text=%s"\n' \
		"$(curl_cfg_escape "$token")" "$(curl_cfg_escape "$chat")" "$(curl_cfg_escape "$msg")" |
		curl -sS --fail --max-time 10 -o /dev/null -K - 2>/dev/null || {
		channel_error tg "sending failed"
		return 1
	}
}

alert_mail() {
	local subject="$1" msg="$2" url="${SECRETS[ALERT_SMTP_URL]:-}"
	local to="${CONF[ALERT_MAIL_TO]:-}" from="${CONF[ALERT_MAIL_FROM]:-}"
	if [[ -z "$url" || -z "$to" || -z "$from" ]]; then
		channel_error mail "ALERT_SMTP_URL, ALERT_MAIL_TO or ALERT_MAIL_FROM is not set"
		return 1
	fi
	local body cfg rcpt rc
	body=$(mktemp)
	chmod 0600 "$body"
	printf 'From: %s\nTo: %s\nSubject: %s\nMIME-Version: 1.0\nContent-Type: text/plain; charset=utf-8\n\n%s\n' \
		"$from" "$to" "$subject" "$msg" >"$body"
	cfg=$(printf 'url = "%s"\nmail-from = "%s"\nupload-file = "%s"\n' \
		"$(curl_cfg_escape "$url")" "$(curl_cfg_escape "$from")" "$body")
	local -a rcpts=()
	# read -a, not an unquoted expansion: no globbing of the address list.
	IFS=, read -ra rcpts <<<"$to"
	for rcpt in "${rcpts[@]}"; do
		cfg+=$'\n'"mail-rcpt = \"$(curl_cfg_escape "$rcpt")\""
	done
	printf '%s\n' "$cfg" | curl -sS --fail --max-time 20 -o /dev/null -K - 2>/dev/null
	rc=$?
	rm -f "$body"
	((rc == 0)) || {
		channel_error mail "sending failed"
		return 1
	}
}

# notify <id> <from> <to> <detail> <kind> <since>
# kind: change | repeat | recovery. One message per channel.
notify() {
	local id="$1" from="$2" to="$3" detail="$4" kind="$5" since="$6" msg sev=warning host
	host=$(hostname -s 2>/dev/null || echo host)
	case "$kind" in
	recovery)
		msg="[dpistack] $host: $id recovered ($from -> $to)"
		sev=notice
		;;
	repeat)
		msg="[dpistack] $host: $id is still $to: $detail (since $since)"
		;;
	*) msg="[dpistack] $host: $id $from -> $to: $detail" ;;
	esac
	[[ "$to" == "crit" ]] && sev=err

	if channel_on panel; then
		jq -nc --arg ts "$(iso "$(now)")" --arg check "$id" --arg from "$from" --arg to "$to" \
			--arg detail "$detail" --arg kind "$kind" \
			'{ts: $ts, check: $check, from: $from, to: $to, detail: $detail, kind: $kind}' >>"$(path_events_jsonl)"
		chmod 0644 "$(path_events_jsonl)"
	fi
	channel_on log && alert_log "$sev" "$msg"
	channel_on tg && { alert_tg "$msg" || true; }
	channel_on mail && { alert_mail "dpistack: $id $to" "$msg" || true; }
	return 0
}

# alert_for <id> <prev-status> <prev-since> <status> <since> <detail>
# decides whether this run sends something and records the time.
alert_for() {
	local id="$1" prev="$2" status="$4" since="$5" detail="$6" key last now_s
	key="watch.alerted.$id"
	now_s=$(now)
	if [[ "$prev" != "$status" ]]; then
		case "$status" in
		warn | crit)
			notify "$id" "${prev:-na}" "$status" "$detail" change "$since"
			state_write_value "$key" "$now_s"
			;;
		ok)
			if [[ "$prev" == "warn" || "$prev" == "crit" ]]; then
				notify "$id" "$prev" "$status" "$detail" recovery "$since"
				state_write_value "$key" 0
			fi
			;;
		esac
		return 0
	fi
	[[ "$status" == "warn" || "$status" == "crit" ]] || return 0
	local repeat_min="${CONF[WATCH_REPEAT_MIN]}" repeat_sec
	repeat_sec=$((repeat_min * 60))
	((repeat_sec > 0)) || return 0
	last=$(state_read_value "$key")
	if [[ -z "$last" ]] || ((now_s - last >= repeat_sec)); then
		notify "$id" "$status" "$status" "$detail" repeat "$since"
		state_write_value "$key" "$now_s"
	fi
}

# write_health - `since` stays while a status is unchanged. Alerts go
# out on a change and, while the status is not ok, every WATCH_REPEAT_MIN.
write_health() {
	local health prev_status prev_since since overall="ok" worst=0 r ts
	ts=$(iso "$(now)")
	health=$(path_health_json)
	mkdir -p "$(dirname "$health")"

	local lines="" id line
	for id in "${CHECK_IDS[@]}"; do
		prev_status="" prev_since=""
		if [[ -f "$health" ]]; then
			IFS=$'\t' read -r prev_status prev_since < <(
				jq -r --arg id "$id" '.checks[]? | select(.id == $id) | [.status, .since] | @tsv' "$health" 2>/dev/null
			)
		fi
		if [[ "$prev_status" == "${C_STATUS[$id]}" && -n "$prev_since" ]]; then
			since="$prev_since"
		else
			since="$ts"
		fi
		alert_for "$id" "$prev_status" "$prev_since" "${C_STATUS[$id]}" "$since" "${C_DETAIL[$id]}"
		r=$(rank "${C_STATUS[$id]}")
		((r > worst)) && worst=$r
		line=$(jq -nc --arg id "$id" --arg status "${C_STATUS[$id]}" --arg value "${C_VALUE[$id]}" \
			--arg detail "${C_DETAIL[$id]}" --arg since "$since" \
			'{id: $id, status: $status, value: $value, detail: $detail, since: $since}')
		lines+="$line"$'\n'
	done
	case "$worst" in
	1) overall=warn ;;
	2) overall=crit ;;
	esac
	printf '%s' "$lines" | jq -s --arg ts "$ts" --arg overall "$overall" \
		'{ts: $ts, overall: $overall, checks: .}' | atomic_write "$health"
	chmod 0644 "$health"
}

# autorestart: at most 3 restarts per component per hour.
autorestart() {
	[[ "${CONF[WATCH_AUTORESTART]}" == "yes" ]] || return 0
	local id key stamps t now_s kept
	now_s=$(now)
	for id in "${CHECK_IDS[@]}"; do
		[[ "$id" == *.process && "${C_STATUS[$id]}" == "crit" ]] || continue
		id="${id%.process}"
		key="watch.restarts.$id"
		kept=()
		for t in $(state_read_value "$key"); do
			((now_s - t < 3600)) && kept+=("$t")
		done
		if ((${#kept[@]} >= RESTARTS_PER_HOUR)); then
			echo "dpistack-watch: $id: restart limit ($RESTARTS_PER_HOUR per hour) used up" >&2
			stamps="${kept[*]}"
		else
			echo "dpistack-watch: restarting $id" >&2
			"$CTL" restart "$id" >/dev/null 2>&1 || echo "dpistack-watch: restarting $id failed" >&2
			kept+=("$now_s")
			stamps="${kept[*]}"
		fi
		state_write_value "$key" "$stamps"
	done
}

main() {
	mkdir -p "$(path_state_dir)"
	exec 9>"$(path_state_dir)/.watch.lock"
	flock -n 9 || exit 0

	config_reset
	config_load_defaults
	[[ -r "$(path_conf)" ]] && config_load_kv_file "$(path_conf)"
	[[ -r "$(path_secrets)" ]] && config_load_kv_file "$(path_secrets)"
	IFS=',' read -ra CHANNELS <<<"${CONF[ALERT_CHANNELS]}"

	load_component_states
	local id
	for id in suricata evebox ntopng redis panel victoriametrics prometheus node_exporter grafana; do
		# Backends are listed by `ctl status` only when selected.
		[[ -n "${COMP_STATE[$id]:-}" ]] || continue
		check_process "$id"
		[[ "$id" == "suricata" ]] || check_port "$id"
	done
	check_eve_fresh
	check_drop_rate
	check_disk_free
	check_rules_age

	write_health
	autorestart
}

main "$@"
DPISTACK_BUNDLE_END
put lib/common.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Shared primitives every step and lib file uses instead of calling
# system commands or writing files directly (tech.md section 3, 5.6).

# Single source of the program version; the menu header, usage and
# dpistack version all print it.
# shellcheck disable=SC2034 # read by menu.sh, install.sh and dpistack
DPISTACK_VERSION="0.26.1"

: "${DRY_RUN:=0}"

log() {
	# log <level> <message>
	local level="$1"
	shift
	local msg="$*"
	local ts
	ts=$(date -u +"%Y-%m-%dT%H:%M:%SZ")
	local line="${ts} [${level}] ${msg}"
	echo "$line" >&2
	local log_dir
	log_dir=$(path_log_dir)
	mkdir -p "$log_dir" 2>/dev/null || true
	echo "$line" >>"$(path_install_log)" 2>/dev/null || true
}

die() {
	# die <exit-code> <message>
	local code="$1"
	shift
	log "ERROR" "$*"
	exit "$code"
}

run() {
	# run <command...>
	# Dry-run prints "+ command" and does not execute (5.6). Real mode
	# executes and logs both the command and whether it failed.
	if [[ "$DRY_RUN" == "1" ]]; then
		printf '+ %s\n' "$*"
		return 0
	fi
	log "RUN" "$*"
	# The status is read straight after the command: inside `if ! cmd`
	# $? is the negated result, so a failing command used to look like 0.
	"$@"
	local rc=$?
	if ((rc != 0)); then
		log "ERROR" "command failed (rc=$rc): $*"
		return "$rc"
	fi
}

lock_acquire() {
	# Takes an flock on the dpistack lock file. A second concurrent
	# instance must exit 1 immediately (5.1, tested by tests/lock.bats).
	# The OS releases the flock on process exit, so there is no
	# matching lock_release: nothing else would ever call it.
	#
	# DPISTACK_LOCK_HELD is a plain (not exported) variable: a subshell of
	# the process that holds the lock inherits it, another process never
	# does. The control menu runs `cmd_reconfigure` in a subshell of the
	# install process; without this the second flock (a new open file
	# description) refused the process that already owned the lock.
	[[ "${DPISTACK_LOCK_HELD:-0}" == "1" ]] && return 0
	local lock_file
	lock_file=$(path_lock_file)
	# {fd} picks a free descriptor; no eval, so odd characters in the
	# path cannot become code.
	mkdir -p "$(dirname "$lock_file")" 2>/dev/null || true
	local fd
	exec {fd}>>"$lock_file"
	if ! flock -n "$fd"; then
		local holder
		holder=$(head -n1 "$lock_file" 2>/dev/null)
		if [[ "$holder" =~ ^[0-9]+$ ]] && kill -0 "$holder" 2>/dev/null; then
			die 1 "another dpistack instance is running (pid $holder, lock: $lock_file); close it or wait for it to finish"
		fi
		die 1 "another dpistack instance is running (lock: $lock_file); close it or wait for it to finish"
	fi
	DPISTACK_LOCK_HELD=1
	# The pid is only a hint for the message above; the flock decides.
	echo "$$" >"$lock_file" 2>/dev/null || true
}

# SELinux (slice 26). "Active" means Enforcing or Permissive: labels are
# worth setting in Permissive too, otherwise switching to Enforcing later
# starts denying what worked. Disabled or no getenforce: nothing to do.
selinux_active() {
	local mode
	command -v getenforce >/dev/null 2>&1 || return 1
	mode=$(getenforce 2>/dev/null) || return 1
	[[ "$mode" == "Enforcing" || "$mode" == "Permissive" ]]
}

# selinux_restore <path...> - give existing paths the label the policy
# says they should have (a file moved in from another directory keeps
# the source's label, and the confined daemon that must read it is then
# denied). Missing paths are skipped; a failure is only a warning, the
# install itself does not depend on it.
selinux_restore() {
	selinux_active || return 0
	command -v restorecon >/dev/null 2>&1 || return 0
	local p
	local -a existing=()
	for p in "$@"; do
		[[ -e "$p" ]] && existing+=("$p")
	done
	((${#existing[@]} > 0)) || return 0
	run restorecon -RF "${existing[@]}" ||
		echo "selinux: restorecon failed for: ${existing[*]}" >&2
	return 0
}

atomic_write() {
	# atomic_write <target-path> [mode] < content-on-stdin
	# mktemp makes the temp file 0600, and the rename would hand that mode
	# to the target: a rendered evebox.yaml became unreadable for the
	# evebox user. An explicit mode wins (secrets pass it so they are
	# never wider than intended, even for a moment); otherwise an existing
	# target keeps its mode and owner and a new file gets 0644.
	local target="$1" mode="${2:-}"
	local dir
	dir=$(dirname "$target")
	mkdir -p "$dir"
	local tmp
	tmp=$(mktemp "${dir}/.tmp.XXXXXX")
	local ok=0
	if [[ -n "$mode" ]]; then
		chmod "$mode" "$tmp" || ok=1
	elif [[ -e "$target" ]]; then
		chmod --reference="$target" "$tmp" || ok=1
		chown --reference="$target" "$tmp" 2>/dev/null || true
	else
		chmod 0644 "$tmp" || ok=1
	fi
	# A failed write (disk full) must not replace the target with a
	# truncated file.
	if ((ok != 0)) || ! cat >"$tmp" || ! mv -f "$tmp" "$target"; then
		rm -f "$tmp"
		return 1
	fi
	if selinux_active && command -v restorecon >/dev/null 2>&1; then
		restorecon -F "$target" 2>/dev/null || true
	fi
}

# dry_run_write <path> [mode] - atomic_write that also honours --dry-run,
# printing "+ render <path>" instead of writing (5.6).
dry_run_write() {
	local path="$1" mode="${2:-}"
	if [[ "${DRY_RUN:-0}" == "1" ]]; then
		printf '+ render %s\n' "$path"
		cat >/dev/null
		return 0
	fi
	atomic_write "$path" "$mode"
}

# write_rendered_file <path> <content> [mode]
# Any step that renders a config file uses this, not atomic_write
# directly, so the 5.4 manual-edit guard is applied uniformly: a file
# that was hand-edited since our last render is left alone with a
# notice unless --force is given (which backs it up first).
write_rendered_file() {
	local path="$1" content="$2" mode="${3:-}"
	local new_hash
	new_hash=$(printf '%s\n' "$content" | state_hash_content)

	if [[ -f "$path" ]]; then
		local on_disk_hash last_hash
		on_disk_hash=$(state_hash_content <"$path")
		last_hash=$(state_file_hash "$path")
		if [[ -n "$last_hash" && "$on_disk_hash" != "$last_hash" && "${FORCE:-0}" != "1" ]]; then
			echo "  $path was changed by hand, leaving it as it is (--force is needed)" >&2
			return 0
		fi
		if [[ "$on_disk_hash" == "$new_hash" ]]; then
			return 0
		fi
		[[ "${FORCE:-0}" == "1" ]] && backup "$path"
	fi

	printf '%s\n' "$content" | dry_run_write "$path" "$mode"
	# A dry run wrote nothing: recording the hash would make the next real
	# run take the old file for a hand-edited one and leave it alone.
	[[ "${DRY_RUN:-0}" == "1" ]] || state_set_file_hash "$path" "$new_hash"
}

backup() {
	# backup <path-to-existing-file>
	# Copies the file into backups/<basename>.<timestamp> before it gets
	# overwritten. No-op if the file does not exist yet.
	local src="$1"
	[[ -f "$src" ]] || return 0
	local backups_dir
	backups_dir=$(path_backups_dir)
	mkdir -p "$backups_dir"
	local ts
	ts=$(date -u +"%Y%m%dT%H%M%SZ")
	local dest n=1
	dest="${backups_dir}/$(basename "$src").${ts}"
	# Two backups in one second must not collide: config-revert takes
	# the newest by `sort -V`, so a counter suffix keeps the order.
	while [[ -e "$dest" ]]; do
		dest="${backups_dir}/$(basename "$src").${ts}.${n}"
		n=$((n + 1))
	done
	cp -p "$src" "$dest"
}

# panel_auth_write <plaintext> - writes an argon2id hash (PHC string,
# the format golang.org/x/crypto/argon2 users parse) into panel.auth.
# The password goes to argon2 on stdin, never as an argument.
# 0640 root:dpistack (4.2); before the panel step creates the user the
# group is missing, and step_panel_apply fixes the group afterwards.
panel_auth_write() {
	local plaintext="$1"
	command -v argon2 >/dev/null 2>&1 || return 2
	local salt hash
	salt=$(head -c 16 /dev/urandom | base64 | tr -dc 'A-Za-z0-9')
	hash=$(printf '%s' "$plaintext" | argon2 "$salt" -id -t 3 -m 14 -p 4 -l 32 -e) || return 1
	# shellcheck disable=SC2016 # literal PHC prefix, not an expansion
	[[ "$hash" == '$argon2id$'* ]] || return 1
	printf '%s\n' "$hash" | atomic_write "$(path_panel_auth)" 0640 || return 1
	if getent group dpistack >/dev/null 2>&1; then
		chown root:dpistack "$(path_panel_auth)" || return 1
	fi
	return 0
}

# conf_get <KEY> <default> - reads one key straight from dpistack.conf.
# The helper stays independent of the installer's schema loader.
conf_get() {
	local key="$1" default="$2" value=""
	local file
	file=$(path_conf)
	[[ -r "$file" ]] && value=$(grep -m1 "^${key}=" "$file" | cut -d= -f2-)
	value="${value%\"}"
	value="${value#\"}"
	echo "${value:-$default}"
}

# git_ref_commit <repo-dir> <ref> - the commit a tag, branch or sha names
# in that checkout; empty when the ref is unknown there.
git_ref_commit() {
	git -C "$1" rev-parse --verify -q "${2}^{commit}" 2>/dev/null
}

# Components that can be left out (v0.25.0). A step of a component that is
# switched off reports "no changes" and does nothing; what is already
# installed stays (removing is `uninstall`). The *_ENABLE keys are in
# lib/schema.sh, the cross rules in lib/config.sh.
step_component_enabled() {
	local yes=yes
	case "$1" in
	ndpi | suricata | verify) [[ "${CONF[SURICATA_ENABLE]:-$yes}" == "$yes" ]] ;;
	rules) [[ "${CONF[SURICATA_ENABLE]:-$yes}" == "$yes" && "${CONF[RULES_ENABLE]:-$yes}" == "$yes" ]] ;;
	redis | ntopng) [[ "${CONF[NTOPNG_ENABLE]:-$yes}" == "$yes" ]] ;;
	evebox) [[ "${CONF[EVEBOX_ENABLE]:-$yes}" == "$yes" ]] ;;
	panel) [[ "${CONF[PANEL_ENABLE]:-$yes}" == "$yes" ]] ;;
	*) return 0 ;;
	esac
}
DPISTACK_BUNDLE_END
put lib/config.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Layers dpistack.conf together (schema defaults -> dpistack.conf ->
# secrets.conf/env -> --config -> --set -> interactive answers),
# validates the result against lib/schema.sh, and can diff two
# configs for `reconfigure` (tech.md 5.1, 5.3, 4.3).

declare -A CONF SECRETS
ACCESS_CONFIRM=""

config_reset() {
	CONF=()
	SECRETS=()
	ACCESS_CONFIRM=""
}

config_set_kv() {
	# config_set_kv <key> <value>
	# Routes to CONF or SECRETS depending on the schema.
	local key="$1" value="$2"
	if schema_known "$key" && schema_is_secret "$key"; then
		SECRETS["$key"]="$value"
	else
		CONF["$key"]="$value"
	fi
}

config_load_defaults() {
	local key
	for key in "${SCHEMA_KEYS[@]}"; do
		config_set_kv "$key" "${SCHEMA_DEFAULT[$key]}"
	done
}

# config_load_kv_file <path>
# Reads KEY=value lines (tech.md 4.3: one per line, no quotes, no
# substitution), skipping blanks and comments, and applies each
# through config_set_kv so secrets land in the right array.
config_load_kv_file() {
	local file="$1"
	[[ -f "$file" ]] || return 0
	local line key value
	while IFS= read -r line || [[ -n "$line" ]]; do
		[[ -z "$line" || "$line" == \#* ]] && continue
		[[ "$line" == *=* ]] || continue
		key="${line%%=*}"
		value="${line#*=}"
		# PANEL_MODE (limited/unlimited) is gone since v0.23.0: an old file
		# still loads, the key is dropped.
		[[ "$key" == "PANEL_MODE" ]] && continue
		config_set_kv "$key" "$value"
	done <"$file"
}

config_apply_env_secrets() {
	local key
	for key in "${SCHEMA_KEYS[@]}"; do
		schema_is_secret "$key" || continue
		local env_value="${!key:-}"
		[[ -n "$env_value" ]] && SECRETS["$key"]="$env_value"
	done
}

# config_apply_set <KEY=VALUE>
config_apply_set() {
	local kv="$1"
	if [[ "$kv" != *=* ]]; then
		echo "bad --set, KEY=VALUE expected: $kv"
		return 1
	fi
	local key="${kv%%=*}" value="${kv#*=}"
	if [[ "$key" == "ACCESS_CONFIRM" ]]; then
		# Documented in 4.3's cross-checks, not in the key table: it
		# confirms ACCESS_MODE != localhost non-interactively and is
		# never written to dpistack.conf.
		ACCESS_CONFIRM="$value"
		return 0
	fi
	config_set_kv "$key" "$value"
}

# config_validate
# Prints every problem found (schema + cross-field, tech.md 4.3) and
# returns the number of errors.
config_validate() {
	local errors=0
	local key msg

	for key in "${!CONF[@]}"; do
		if ! msg=$(schema_validate_one "$key" "${CONF[$key]}"); then
			echo "$msg"
			errors=$((errors + 1))
		fi
	done

	# nginx takes the public port, the service moves to <public>+10000.
	if [[ "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]]; then
		local port_key
		for port_key in NTOPNG_PORT EVEBOX_PORT PANEL_PORT; do
			if [[ "${CONF[$port_key]:-0}" =~ ^[0-9]+$ ]] && ((${CONF[$port_key]:-0} > 55535)); then
				echo "ACCESS_MODE=nginx needs $port_key not above 55535 (the service listens on the port plus 10000)"
				errors=$((errors + 1))
			fi
		done
	fi

	if [[ "${CONF[EVEBOX_DB]:-}" == "elasticsearch" && -z "${CONF[EVEBOX_ES_URL]:-}" ]]; then
		echo "EVEBOX_DB=elasticsearch needs EVEBOX_ES_URL"
		errors=$((errors + 1))
	fi

	if [[ "${CONF[METRICS_BACKEND]:-}" != "none" && "${CONF[METRICS_EXPORT]:-}" == "no" ]]; then
		echo "METRICS_BACKEND=${CONF[METRICS_BACKEND]} needs METRICS_EXPORT=yes (the backend has nothing to scrape)"
		errors=$((errors + 1))
	fi

	if [[ "${CONF[SURICATA_MODE]:-ids}" == "ips" ]]; then
		if [[ "${CONF[SURICATA_RUNTIME]:-native}" == "docker" ]]; then
			echo "SURICATA_MODE=ips works only with SURICATA_RUNTIME=native (NFQUEUE and copy-mode are not supported in a container)"
			errors=$((errors + 1))
		fi
		if [[ "${CONF[IPS_METHOD]:-nfq}" == "afpacket" ]]; then
			local -a ips_ifaces=()
			IFS=',' read -ra ips_ifaces <<<"${CONF[IFACES]:-}"
			if ((${#ips_ifaces[@]} < 2 || ${#ips_ifaces[@]} % 2 != 0)); then
				echo "IPS_METHOD=afpacket pairs interfaces: IFACES needs an even number of interfaces (at least two)"
				errors=$((errors + 1))
			fi
		fi
	fi
	local ips_chain
	local -a ips_chains=()
	IFS=',' read -ra ips_chains <<<"${CONF[IPS_NFQ_CHAINS]:-INPUT,OUTPUT,FORWARD}"
	for ips_chain in "${ips_chains[@]}"; do
		if [[ ! "$ips_chain" =~ ^(INPUT|OUTPUT|FORWARD)$ ]]; then
			echo "IPS_NFQ_CHAINS: INPUT, OUTPUT, FORWARD are allowed, got $ips_chain"
			errors=$((errors + 1))
		fi
	done

	# VictoriaMetrics reads a bare number as months and the suffix m as
	# months, Prometheus reads m as minutes: only the suffixes both read the
	# same way (h, d, w, y) are allowed once a backend is installed.
	if [[ "${CONF[METRICS_BACKEND]:-none}" != "none" && ! "${CONF[METRICS_RETENTION]:-30d}" =~ ^[0-9]+[hdwy]$ ]]; then
		echo "METRICS_RETENTION=${CONF[METRICS_RETENTION]:-} with a metrics backend: a number with the suffix h, d, w or y is needed (for example 30d); backends read a bare number or m differently"
		errors=$((errors + 1))
	fi

	if [[ "${CONF[EVE_ROTATE]:-}" == "size" && -z "${CONF[EVE_MAX_SIZE_MB]:-}" ]]; then
		echo "EVE_ROTATE=size needs EVE_MAX_SIZE_MB"
		errors=$((errors + 1))
	fi

	local bind_value="${CONF[BIND_ADDR]:-auto}" bind_open=0
	if [[ "$bind_value" != "auto" ]]; then
		local octet bad=0
		IFS=. read -ra _octets <<<"$bind_value"
		for octet in "${_octets[@]}"; do
			((10#$octet <= 255)) || bad=1
		done
		if ((bad)) || [[ "$bind_value" == "0.0.0.0" ]]; then
			echo "BIND_ADDR=$bind_value is not an address of a host; use auto or an IPv4 address of this machine"
			errors=$((errors + 1))
		elif [[ "$bind_value" != 127.* ]]; then
			bind_open=1
		fi
	fi
	if [[ "${CONF[ACCESS_MODE]:-}" == "nginx" ]]; then
		bind_open=0
	fi
	if { [[ "${CONF[ACCESS_MODE]:-}" != "localhost" ]] || ((bind_open)); } && [[ "${ACCESS_CONFIRM:-}" != "yes" && "${NON_INTERACTIVE:-0}" == "1" ]]; then
		echo "ACCESS_MODE=${CONF[ACCESS_MODE]} with BIND_ADDR=${bind_value} in non-interactive mode needs --set ACCESS_CONFIRM=yes"
		errors=$((errors + 1))
	fi

	if [[ "${CONF[NDPI_ENABLE]:-no}" == "yes" && "${CONF[SURICATA_SOURCE]:-}" != "source" &&
		! -f "$(path_suricata_ndpi_plugin)" && "${NON_INTERACTIVE:-0}" == "1" ]]; then
		echo "NDPI_ENABLE=yes with SURICATA_SOURCE=${CONF[SURICATA_SOURCE]:-} does not give ndpi.so; use SURICATA_SOURCE=source or build the plugin beforehand"
		errors=$((errors + 1))
	fi

	if [[ "${CONF[METRICS_BACKEND]:-none}" != "none" && "${CONF[PANEL_ENABLE]:-yes}" == "no" ]]; then
		echo "METRICS_BACKEND=${CONF[METRICS_BACKEND]} scrapes the panel: set PANEL_ENABLE=yes or METRICS_BACKEND=none"
		errors=$((errors + 1))
	fi
	if [[ "${CONF[SURICATA_ENABLE]:-yes}" == "no" ]]; then
		local dep
		for dep in NDPI_ENABLE RULES_ENABLE; do
			if [[ "${CONF[$dep]:-no}" == "yes" ]]; then
				echo "SURICATA_ENABLE=no with ${dep}=yes: ${dep%_ENABLE} works only together with Suricata; set ${dep}=no"
				errors=$((errors + 1))
			fi
		done
	fi

	if [[ "${CONF[NGINX_TLS]:-none}" == "existing" && (-z "${CONF[NGINX_CERT]:-}" || -z "${CONF[NGINX_KEY]:-}") ]]; then
		echo "NGINX_TLS=existing needs NGINX_CERT and NGINX_KEY"
		errors=$((errors + 1))
	fi

	if [[ "${CONF[EVE_FILE]:-yes}" == "no" && "${CONF[EVEBOX_DB]:-sqlite}" == "sqlite" ]]; then
		echo "EVE_FILE=no with EVEBOX_DB=sqlite: EveBox cannot read events (eve.json is not written). Enable EVE_FILE=yes or choose EVEBOX_DB=elasticsearch"
		errors=$((errors + 1))
	fi

	local channel
	local -a channels=()
	IFS=',' read -ra channels <<<"${CONF[ALERT_CHANNELS]:-}"
	for channel in "${channels[@]}"; do
		case "$channel" in
		panel | log | tg | mail) ;;
		*)
			echo "ALERT_CHANNELS: unknown channel '$channel' (panel, log, tg, mail are allowed)"
			errors=$((errors + 1))
			;;
		esac
	done
	if [[ ",${CONF[ALERT_CHANNELS]:-}," == *",tg,"* ]]; then
		if [[ -z "${SECRETS[ALERT_TG_TOKEN]:-}" || -z "${CONF[ALERT_TG_CHAT_ID]:-}" ]]; then
			echo "ALERT_CHANNELS contains tg: needs ALERT_TG_TOKEN and ALERT_TG_CHAT_ID"
			errors=$((errors + 1))
		fi
	fi
	if [[ ",${CONF[ALERT_CHANNELS]:-}," == *",mail,"* ]]; then
		if [[ -z "${SECRETS[ALERT_SMTP_URL]:-}" || -z "${CONF[ALERT_MAIL_TO]:-}" || -z "${CONF[ALERT_MAIL_FROM]:-}" ]]; then
			echo "ALERT_CHANNELS contains mail: needs ALERT_SMTP_URL, ALERT_MAIL_TO and ALERT_MAIL_FROM"
			errors=$((errors + 1))
		fi
	fi

	return "$errors"
}

METRICS_TOKEN_JUST_GENERATED=0

config_generate_metrics_token_if_needed() {
	METRICS_TOKEN_JUST_GENERATED=0
	if [[ "${CONF[METRICS_EXPORT]:-}" == "yes" && -z "${SECRETS[METRICS_TOKEN]:-}" ]]; then
		SECRETS[METRICS_TOKEN]=$(head -c 32 /dev/urandom | od -An -tx1 | tr -d ' \n')
		# shellcheck disable=SC2034 # read by install.sh right after this call
		METRICS_TOKEN_JUST_GENERATED=1
	fi
}

# config_write_conf <path>
# Deterministic, sorted output so two runs with the same values give
# byte-identical files (tech.md 5.1 criterion: repeat -y = same conf).
config_write_conf() {
	local path="$1"
	local key
	{
		for key in $(printf '%s\n' "${!CONF[@]}" | sort); do
			printf '%s=%s\n' "$key" "${CONF[$key]}"
		done
	} | atomic_write "$path"
	chmod 0644 "$path"
}

# The applied config lives in state as applied.<KEY>=<value>, so a
# later `dpistack reconfigure` can diff dpistack.conf (already
# edited by config-write) against what the system was last built from.
config_snapshot_applied() {
	local f tmp key lock_fd
	f=$(path_state_file)
	# Same lock as state_write_value: the watchdog rewrites this file too,
	# and an unlocked read-modify-write here could drop its update.
	mkdir -p "$(dirname "$f")"
	exec {lock_fd}>"${f}.lock"
	flock -x "$lock_fd"
	tmp=$(mktemp)
	if [[ -f "$f" ]]; then
		grep -v '^applied\.' "$f" >"$tmp" || true
	fi
	for key in $(printf '%s\n' "${!CONF[@]}" | sort); do
		printf 'applied.%s=%s\n' "$key" "${CONF[$key]}" >>"$tmp"
	done
	atomic_write "$f" 0600 <"$tmp"
	rm -f "$tmp"
	exec {lock_fd}>&-
}

config_write_secrets() {
	local path="$1"
	local key
	{
		for key in $(printf '%s\n' "${!SECRETS[@]}" | sort); do
			[[ -n "${SECRETS[$key]}" ]] || continue
			printf '%s=%s\n' "$key" "${SECRETS[$key]}"
		done
	} | atomic_write "$path" 0600
}

# config_print_summary
# Secrets never show their value, only whether one is set (tech.md 5.0).
config_print_summary() {
	local key
	for key in $(printf '%s\n' "${!CONF[@]}" | sort); do
		printf '  %s=%s\n' "$key" "${CONF[$key]}"
	done
	for key in $(printf '%s\n' "${!SECRETS[@]}" | sort); do
		if [[ -n "${SECRETS[$key]}" ]]; then
			printf '  %s=set\n' "$key"
		else
			printf '  %s=not set\n' "$key"
		fi
	done
}

# config_diff_and_steps <old-conf-file>
# Compares CONF (already layered/validated) against a previously
# applied dpistack.conf, prints "KEY: old -> new", and returns the
# affected steps and worst weight on stdout after a marker line
# (tech.md 5.3).
# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure after calling config_diff_and_steps
CONFIG_CHANGE_WEIGHT="none"
# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure after calling config_diff_and_steps
CONFIG_CHANGED_KEYS=()
# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure after calling config_diff_and_steps
CONFIG_AFFECTED_STEPS=()

config_diff_and_steps() {
	local old_file="$1"
	# Old side = the applied snapshot when there is one, else the file.
	local snapshot_file=""
	if grep -q '^applied\.' "$(path_state_file)" 2>/dev/null; then
		snapshot_file=$(mktemp)
		grep '^applied\.' "$(path_state_file)" | sed 's/^applied\.//' >"$snapshot_file"
		old_file="$snapshot_file"
	fi
	CONFIG_CHANGE_WEIGHT="none"
	CONFIG_CHANGED_KEYS=()
	CONFIG_AFFECTED_STEPS=()
	declare -A OLD
	local line key value
	while IFS= read -r line || [[ -n "$line" ]]; do
		[[ -z "$line" || "$line" == \#* ]] && continue
		[[ "$line" == *=* ]] || continue
		key="${line%%=*}"
		value="${line#*=}"
		OLD["$key"]="$value"
	done <"$old_file"
	[[ -n "$snapshot_file" ]] && rm -f "$snapshot_file"

	local -a changed=()
	for key in "${!CONF[@]}"; do
		if [[ "${OLD[$key]-__unset__}" != "${CONF[$key]}" ]]; then
			changed+=("$key")
		fi
	done

	if [[ "${#changed[@]}" -eq 0 ]]; then
		echo "no changes"
		return 0
	fi
	# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure
	CONFIG_CHANGED_KEYS=("${changed[@]}")

	echo "Changed keys:"
	local k
	for k in "${changed[@]}"; do
		printf '  %s: %s -> %s\n' "$k" "${OLD[$k]-(not set)}" "${CONF[$k]}"
	done

	declare -A steps_seen
	local overall_weight="light"
	for k in "${changed[@]}"; do
		schema_known "$k" || continue
		local step
		for step in ${SCHEMA_STEPS[$k]}; do
			steps_seen["$step"]=1
		done
		[[ "${SCHEMA_WEIGHT[$k]}" == "heavy" ]] && overall_weight="heavy"
	done
	# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure
	CONFIG_CHANGE_WEIGHT="$overall_weight"
	# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure
	# In the order of the pipeline (suricata before rules, access before
	# panel...), not in the arbitrary order of an associative array; a step
	# that is not in STEPS_ORDER goes last, sorted.
	CONFIG_AFFECTED_STEPS=()
	for step in "${STEPS_ORDER[@]:-}"; do
		[[ -n "${steps_seen[$step]:-}" ]] && CONFIG_AFFECTED_STEPS+=("$step")
	done
	for step in $(printf '%s\n' "${!steps_seen[@]}" | sort); do
		[[ " ${CONFIG_AFFECTED_STEPS[*]} " == *" $step "* ]] || CONFIG_AFFECTED_STEPS+=("$step")
	done

	echo "Affected steps:"
	printf '  %s\n' "${CONFIG_AFFECTED_STEPS[@]}"

	echo "Change type: $overall_weight"
	return 0
}
DPISTACK_BUNDLE_END
put lib/ctl.sh 755 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# The privileged verbs of dpistack (tech.md 4.5): status, start, stop, config
# editing, rules, interfaces, mode, tests, health, panel password. They are
# part of the one `dpistack` command (install.sh dispatches here); the panel
# and the watchdog reach them through `sudo -n dpistack <verb>`. Sourced by
# install.sh after the other libraries; it defines functions only.
#
# Exit codes: 0 ok, 1 error, 2 usage, 3 check failed, 4 component
# absent, 5 name outside the allowed list.

COMPONENTS=(suricata evebox ntopng redis victoriametrics prometheus node_exporter grafana panel watch rules)
LOGS_MAX=1000
LOGS_DEFAULT=100

MODE_TIMEOUT_DEFAULT=120
MODE_TIMEOUT_MIN=10
MODE_TIMEOUT_MAX=3600
MODE_ROLLBACK_UNIT="dpistack-mode-rollback"

RULES_SEARCH_MAX=50

ctl_usage() {
	cat <<'USAGE'
Usage: dpistack <command> [arguments]

  status [--json]                    component state
  start|stop|restart <id>            control a component
  reload suricata                    reload the rules without stopping
  logs <id> [-n N] [--follow]        component log, N up to 1000 (--until-stdin-closed: for the panel)
  config-read <name>                 prints the current file
  config-write <name> [--apply|--check] new content from stdin; --check only validates
  settings list [--json] | check K=V... | set [--apply|--apply-heavy] [--confirm-access] K=V... | secret KEY | job
  config-revert <name>               restores the latest backup
  reconfigure [--dry-run]            applies the current dpistack.conf
  rules-update                       update the rules, roll back on error
  rules-sources list [--enabled]|enable|disable|add-url|remove [arg]
  rules-group enable|disable <group>
  rules-sid enable|disable <sid>
  rules-search <query>              up to 50 rules by sid or msg
  iface list|add|remove [name]        capture interfaces
  mode ids|ips [--confirm-timeout S] Suricata mode; ips rolls back by itself without mode-confirm (default 120 s)
  mode status [--json]               mode, method and countdown
  mode-confirm                       confirm the switch to ips
  fw apply|remove|restore            DPISTACK chain (restore: at boot)
  panel-passwd                       panel password from stdin
  test bittorrent|https|all [--json] check tests (section 10)
  health [--json]                    one watchdog run
  version                            bundle version

Config names: suricata.yaml evebox.yaml ntopng.conf dpistack.conf local.rules
                enable.conf disable.conf modify.conf drop.conf

Components: suricata evebox ntopng redis victoriametrics prometheus node_exporter grafana panel watch rules
USAGE
}

fail() {
	# fail <code> <message>
	local code="$1"
	shift
	echo "dpistack: $*" >&2
	exit "$code"
}

in_list() {
	# in_list <item> <list...>
	local item="$1" x
	shift
	for x in "$@"; do
		[[ "$x" == "$item" ]] && return 0
	done
	return 1
}

# Unit load state is the only portable "is it installed" test that
# also covers units for source builds, which have no package.
unit_loaded() {
	local state
	state=$(systemctl show -p LoadState --value "$1" 2>/dev/null)
	[[ -n "$state" && "$state" != "not-found" ]]
}

# component_unit <id> - prints the unit that controls the component.
component_unit() {
	# docker runtime: no unit, the compose service is addressed as docker:<id>.
	if [[ "$1" =~ ^(suricata|evebox|ntopng|redis|victoriametrics|prometheus|node_exporter|grafana|panel)$ && "$(component_runtime "$1")" == "docker" ]]; then
		echo "docker:$1"
		return
	fi
	case "$1" in
	suricata) echo "suricata.service" ;;
	evebox) echo "evebox.service" ;;
	ntopng) echo "ntopng.service" ;;
	redis)
		# redis.service on rpm, redis-server.service on deb.
		if unit_loaded "redis-server.service"; then
			echo "redis-server.service"
		else
			echo "redis.service"
		fi
		;;
	victoriametrics) echo "dpistack-vm.service" ;;
	prometheus) echo "prometheus.service" ;;
	node_exporter) echo "dpistack-node-exporter.service" ;;
	grafana) echo "dpistack-grafana.service" ;;
	panel) echo "dpistack-panel.service" ;;
	watch) echo "dpistack-watch.timer" ;;
	rules) echo "dpistack-rules.timer" ;;
	esac
}

# component_listed <id> - backend components exist only when selected; a
# part that is switched off (*_ENABLE=no) is left out of status and health
# unless it is installed anyway (switching off does not remove it).
component_listed() {
	local key=""
	case "$1" in
	suricata) key=SURICATA_ENABLE ;;
	rules) key=RULES_ENABLE ;;
	evebox) key=EVEBOX_ENABLE ;;
	ntopng | redis) key=NTOPNG_ENABLE ;;
	panel) key=PANEL_ENABLE ;;
	esac
	if [[ -n "$key" && "$(conf_get "$key" yes)" == "no" ]]; then
		unit_loaded "$(component_unit "$1")"
		return
	fi
	case "$1" in
	victoriametrics | prometheus)
		[[ "$(conf_get METRICS_BACKEND none)" == "$1" ]]
		;;
	node_exporter) [[ "$(conf_get NODE_EXPORTER_ENABLE no)" == "yes" ]] ;;
	grafana) [[ "$(conf_get GRAFANA_ENABLE no)" == "yes" ]] ;;
	*) return 0 ;;
	esac
}

component_runtime() {
	case "$1" in
	suricata) conf_get SURICATA_RUNTIME native ;;
	evebox) conf_get EVEBOX_RUNTIME native ;;
	ntopng | redis) conf_get NTOPNG_RUNTIME native ;;
	victoriametrics | prometheus) conf_get METRICS_BACKEND_RUNTIME native ;;
	node_exporter) conf_get NODE_EXPORTER_RUNTIME native ;;
	grafana) conf_get GRAFANA_RUNTIME native ;;
	panel) conf_get PANEL_RUNTIME native ;;
	*) echo native ;;
	esac
}

component_version() {
	if [[ "$(component_unit "$1")" == docker:* ]]; then
		docker_compose_argv
		"${DOCKER_COMPOSE_ARGV[@]}" ps --format '{{.Image}}' "$1" 2>/dev/null | head -1
		return 0
	fi
	local pkg=""
	case "$1" in
	suricata) pkg="suricata" ;;
	evebox) pkg="evebox" ;;
	ntopng) pkg="ntopng" ;;
	redis)
		pkg="redis-server"
		command -v dpkg-query >/dev/null 2>&1 || pkg="redis"
		;;
	*) return 0 ;;
	esac
	local v
	if command -v dpkg-query >/dev/null 2>&1; then
		v=$(dpkg-query -W -f='${Version}' "$pkg" 2>/dev/null)
	else
		v=$(rpm -q --qf '%{VERSION}-%{RELEASE}' "$pkg" 2>/dev/null) || v=""
	fi
	if [[ -z "$v" && "$1" == "suricata" ]] && command -v suricata >/dev/null 2>&1; then
		# Source builds have no package; the binary reports its version.
		v=$(suricata -V 2>/dev/null | sed -n 's/.*version \([0-9][^ ]*\).*/\1/p' | head -1)
	fi
	echo "$v"
}

component_state() {
	# component_state <unit> -> active|inactive|failed|absent
	local unit="$1"
	if [[ "$unit" == docker:* ]]; then
		docker_component_state "${unit#docker:}"
		return
	fi
	if ! unit_loaded "$unit"; then
		echo absent
		return
	fi
	local s
	s=$(systemctl is-active "$unit" 2>/dev/null)
	case "$s" in
	active | failed) echo "$s" ;;
	*) echo inactive ;;
	esac
}

json_escape() {
	local s="$1"
	s="${s//\\/\\\\}"
	s="${s//\"/\\\"}"
	s="${s//$'\t'/\\t}"
	s="${s//$'\r'/\\r}"
	# the other control characters have no place in a JSON string
	s=$(printf '%s' "$s" | tr -d '\000-\010\013\014\016-\037')
	printf '%s' "$s"
}

ctl_cmd_status() {
	local json=0
	case "${1:-}" in
	"") ;;
	--json) json=1 ;;
	*) fail 2 "status: unknown argument" ;;
	esac
	[[ $# -le 1 ]] || fail 2 "status: extra arguments"

	local plugin=absent
	[[ -e "$(path_suricata_ndpi_plugin)" ]] && plugin=loaded

	local id unit runtime state enabled version first=1
	((json)) && printf '{"components":['
	for id in "${COMPONENTS[@]}"; do
		component_listed "$id" || continue
		unit=$(component_unit "$id")
		runtime=$(component_runtime "$id")
		state=$(component_state "$unit")
		if [[ "$state" == "absent" ]]; then
			enabled=false
		elif [[ "$unit" == docker:* ]]; then
			# restart: unless-stopped brings the container back at boot.
			enabled=true
		elif systemctl is-enabled --quiet "$unit" 2>/dev/null; then
			enabled=true
		else
			enabled=false
		fi
		version=$(component_version "$id")
		if ((json)); then
			((first)) || printf ','
			first=0
			printf '{"id":"%s","runtime":"%s","state":"%s","enabled":%s,"version":"%s"}' \
				"$id" "$runtime" "$state" "$enabled" "$(json_escape "$version")"
		else
			printf '%-16s %-7s %-9s enabled=%-5s %s\n' "$id" "$runtime" "$state" "$enabled" "$version"
		fi
	done
	if ((json)); then
		printf '],"ndpi_plugin":"%s"}\n' "$plugin"
	else
		echo "ndpi_plugin      $plugin"
	fi
}

# resolve_component <id> - validates the id (5) and presence (4), then
# prints the unit. Runtime other than native is not supported yet:
# the schema rejects docker until slice 27.
resolve_component() {
	local id="$1"
	in_list "$id" "${COMPONENTS[@]}" || fail 5 "unknown component: $id"
	component_listed "$id" || fail 4 "component not installed: $id"
	local unit
	unit=$(component_unit "$id")
	[[ "$(component_state "$unit")" != "absent" ]] || fail 4 "component not installed: $id"
	echo "$unit"
}

cmd_control() {
	local verb="$1"
	shift
	[[ $# -eq 1 ]] || fail 2 "$verb: exactly one <id> is needed"
	local unit
	unit=$(resolve_component "$1") || exit $?
	if [[ "$unit" == docker:* ]]; then
		docker_compose_argv
		"${DOCKER_COMPOSE_ARGV[@]}" "$verb" "${unit#docker:}" || fail 1 "$verb $1: docker compose failed"
		return 0
	fi
	systemctl "$verb" "$unit" || fail 1 "$verb $1: systemctl failed"
}

# suricata_reload_now - reload the rules of the running Suricata, native
# or in its container.
suricata_reload_now() {
	if [[ "$(component_unit suricata)" == docker:* ]]; then
		docker_suricata_reload
	else
		suricatasc -c ruleset-reload-nonblocking "$(path_suricata_socket)"
	fi
}

cmd_reload() {
	[[ $# -eq 1 ]] || fail 2 "reload: the argument suricata is needed"
	[[ "$1" == "suricata" ]] || fail 5 "reload: only suricata is supported"
	resolve_component suricata >/dev/null || exit $?
	suricata_reload_now ||
		fail 1 "reload suricata: suricatasc failed"
}

cmd_logs() {
	[[ $# -ge 1 ]] || fail 2 "logs: <id> is needed"
	local id="$1"
	shift
	local n="$LOGS_DEFAULT" follow=0 until_eof=0
	while [[ $# -gt 0 ]]; do
		case "$1" in
		-n)
			[[ $# -ge 2 ]] || fail 2 "logs: -n needs a number"
			n="$2"
			shift 2
			;;
		--follow)
			follow=1
			shift
			;;
		--until-stdin-closed)
			# For the panel: it is not root, so it cannot signal sudo to
			# stop us. It holds our stdin open while it listens and closes
			# it to end the stream, which works even when no new line comes.
			follow=1
			until_eof=1
			shift
			;;
		*) fail 2 "logs: unknown argument: $1" ;;
		esac
	done
	[[ "$n" =~ ^[0-9]{1,6}$ ]] || fail 2 "logs: N must be a number"
	# 10#: a leading zero is not octal ("08" is eight, "01750" is 1750).
	n=$((10#$n))
	((n >= 1 && n <= LOGS_MAX)) || fail 2 "logs: N from 1 to $LOGS_MAX"

	local unit
	unit=$(resolve_component "$id") || exit $?
	# logs_argv <follow:0|1> - the command that prints the component's log.
	logs_argv() {
		if [[ "$unit" == docker:* ]]; then
			docker_compose_argv
			LOGS_ARGV=("${DOCKER_COMPOSE_ARGV[@]}" logs --no-color --tail "$n")
			(($1)) && LOGS_ARGV+=(--follow)
			LOGS_ARGV+=("${unit#docker:}")
		else
			LOGS_ARGV=(journalctl -u "$unit" -n "$n" --no-pager)
			(($1)) && LOGS_ARGV+=(--follow)
		fi
		return 0
	}
	local -a LOGS_ARGV
	if ((until_eof)); then
		logs_argv 1
		"${LOGS_ARGV[@]}" &
		local jpid=$!
		# <&0: a background command otherwise gets /dev/null as stdin and
		# would see end of input at once.
		cat <&0 >/dev/null &
		local cpid=$!
		wait -n
		kill "$jpid" "$cpid" 2>/dev/null
		wait 2>/dev/null
		return 0
	fi
	if ((follow)); then
		# No pipe trap: journalctl dies of SIGPIPE when the reader closes.
		logs_argv 1
		"${LOGS_ARGV[@]}"
	else
		logs_argv 0
		"${LOGS_ARGV[@]}"
	fi
}

# ---------------------------------------------------------------- config

# config_path <name> - prints the file behind a name from the 4.5 list.
config_path() {
	case "$1" in
	suricata.yaml) path_suricata_yaml ;;
	evebox.yaml) path_evebox_yaml ;;
	ntopng.conf) path_ntopng_conf ;;
	dpistack.conf) path_conf ;;
	local.rules) path_suricata_local_rules ;;
	enable.conf) path_suricata_enable_conf ;;
	disable.conf) path_suricata_disable_conf ;;
	modify.conf) path_suricata_modify_conf ;;
	drop.conf) path_suricata_drop_conf ;;
	*) return 1 ;;
	esac
}

# ctl_lock / ctl_unlock - the installer's own lock, so a config file is
# never replaced while `install.sh` renders from it. Waits up to 30 s;
# it must not be held while the installer is started (reconfigure).
ctl_lock() {
	local lock_file
	lock_file=$(path_lock_file)
	mkdir -p "$(dirname "$lock_file")"
	exec {CTL_LOCK_FD}>"$lock_file"
	if ! flock -w 30 "$CTL_LOCK_FD"; then
		fail 1 "the installer is busy (lock $lock_file), try again later"
	fi
}

ctl_unlock() {
	exec {CTL_LOCK_FD}>&-
}

# config_commit <name> <staged-file> - backup, then atomic replace.
# Deliberately leaves the render hash in state alone: a file changed
# here counts as edited by hand, so the installer will not overwrite
# it without --force (5.4).
config_commit() {
	local name="$1" staged="$2" path mode
	path=$(config_path "$name")
	ctl_lock
	mode=$(stat -c %a "$path" 2>/dev/null || echo 644)
	backup "$path"
	atomic_write "$path" <"$staged"
	chmod "$mode" "$path"
	ctl_unlock
}

# suricata_check_set <name> <staged-file>
# `suricata -T` on a temporary copy of the set: the live ruleset plus
# the candidate local.rules, with the candidate suricata.yaml when that
# is what changes. Nothing outside the temp dir is touched.
suricata_check_set() {
	local name="$1" staged="$2" tmp yaml rc docker=0 rulepath
	[[ "$(component_unit suricata)" == docker:* ]] && docker=1
	((docker)) || command -v suricata >/dev/null 2>&1 || {
		echo "suricata is not installed" >&2
		return 4
	}
	tmp=$(mktemp -d)
	mkdir -p "$tmp/rules"
	if [[ -f "$(path_suricata_ruleset)" ]]; then
		cp "$(path_suricata_ruleset)" "$tmp/rules/suricata.rules"
	else
		: >"$tmp/rules/suricata.rules"
	fi
	[[ "$name" == "local.rules" ]] && cat "$staged" >>"$tmp/rules/suricata.rules"
	yaml="$(path_suricata_yaml)"
	[[ "$name" == "suricata.yaml" ]] && yaml="$staged"
	# In docker the check runs in the same image the service uses, with the
	# scratch directory mounted at /dpistack-check.
	rulepath="$tmp/rules"
	((docker)) && rulepath="/dpistack-check/rules"
	sed "s#^default-rule-path:.*#default-rule-path: $rulepath#" "$yaml" >"$tmp/suricata.yaml" 2>/dev/null
	if ((docker)); then
		docker_compose_argv
		"${DOCKER_COMPOSE_ARGV[@]}" run --rm --no-deps -v "$tmp:/dpistack-check" suricata -T -c /dpistack-check/suricata.yaml -l /dpistack-check 2>&1
	else
		suricata -T -c "$tmp/suricata.yaml" -l "$tmp" 2>&1
	fi
	rc=$?
	rm -rf "$tmp"
	((rc == 0)) || return 3
	return 0
}

# config_validate_staged <name> <staged-file> - output on stdout,
# returns 0 ok, 3 check failed, 4 component absent.
config_validate_staged() {
	local name="$1" staged="$2"
	case "$name" in
	dpistack.conf)
		# Secrets live in secrets.conf; in dpistack.conf (0644) they would
		# be readable by everyone.
		local line key
		while IFS= read -r line || [[ -n "$line" ]]; do
			key="${line%%=*}"
			if [[ "$line" == *=* && "$line" != \#* ]] && schema_is_secret "$key" 2>/dev/null; then
				echo "$key: a secret is kept in secrets.conf and cannot be changed through config-write"
				return 3
			fi
		done <"$staged"
		# Schema and cross-field checks of 4.3.
		config_reset
		config_load_defaults
		config_load_kv_file "$staged"
		# Secrets live in their own file; the cross-field checks need them.
		[[ -r "$(path_secrets)" ]] && config_load_kv_file "$(path_secrets)"
		config_validate && return 0
		return 3
		;;
	evebox.yaml | ntopng.conf)
		# A8: neither component has a config-test mode we can rely on,
		# so the only check is that the file is not empty.
		[[ -s "$staged" ]] && return 0
		echo "$name: the file is empty"
		return 3
		;;
	*) suricata_check_set "$name" "$staged" ;;
	esac
}

cmd_config_read() {
	[[ $# -eq 1 ]] || fail 2 "config-read: a file name is needed"
	local path
	path=$(config_path "$1") || fail 5 "unknown file name: $1"
	[[ -f "$path" ]] || fail 4 "file missing: $1"
	cat "$path"
}

# apply_config <name> - reloads whatever reads the file.
apply_config() {
	case "$1" in
	dpistack.conf) ctl_cmd_reconfigure ;;
	suricata.yaml)
		cmd_control restart suricata
		;;
	evebox.yaml)
		cmd_control restart evebox
		;;
	ntopng.conf)
		cmd_control restart ntopng
		;;
	*) cmd_rules_update ;;
	esac
}

cmd_config_write() {
	[[ $# -ge 1 && $# -le 2 ]] || fail 2 "config-write: <name> [--apply|--check]"
	local name="$1" apply=0 check=0
	config_path "$name" >/dev/null || fail 5 "unknown file name: $name"
	if [[ $# -eq 2 ]]; then
		case "$2" in
		--apply) apply=1 ;;
		--check) check=1 ;;
		*) fail 2 "config-write: unknown argument: $2" ;;
		esac
	fi

	local staging staged out rc
	staging=$(path_staging_dir)
	mkdir -p "$staging"
	chmod 0700 "$staging"
	staged="$staging/$name"
	(umask 077 && cat >"$staged")

	out=$(config_validate_staged "$name" "$staged")
	rc=$?
	if ((rc != 0)); then
		rm -f "$staged"
		[[ -n "$out" ]] && echo "$out"
		((rc == 4)) && fail 4 "component missing"
		fail 3 "$name: check failed, file unchanged"
	fi

	if ((check)); then
		# The panel's "Check": the verdict and the checker's own words,
		# and nothing is replaced.
		rm -f "$staged"
		[[ -n "$out" ]] && echo "$out"
		echo "$name: check passed, file unchanged"
		return 0
	fi

	config_commit "$name" "$staged"
	rm -f "$staged"
	if ((apply)); then
		apply_config "$name" || return $?
	fi
	return 0
}

cmd_config_revert() {
	[[ $# -eq 1 ]] || fail 2 "config-revert: a file name is needed"
	local name="$1" path latest mode
	path=$(config_path "$name") || fail 5 "unknown file name: $name"
	latest=$(printf '%s\n' "$(path_backups_dir)/$(basename "$path")".* | sort -V | tail -1)
	[[ -e "$latest" ]] || latest=""
	[[ -n "$latest" ]] || fail 1 "no backup for $name"
	ctl_lock
	mode=$(stat -c %a "$path" 2>/dev/null || echo 644)
	atomic_write "$path" <"$latest"
	chmod "$mode" "$path"
	ctl_unlock
	echo "restored from $latest"
}

# ctl_cmd_reconfigure [--dry-run] - the installer does the diff, the step
# selection and the re-render; it never installs packages here, because
# --force is not passed and a heavy change stops with code 3.
ctl_cmd_reconfigure() {
	[[ $# -le 1 ]] || fail 2 "reconfigure: extra arguments"
	local -a args=(reconfigure -y)
	case "${1:-}" in
	"") ;;
	--dry-run) args+=(--dry-run) ;;
	*) fail 2 "reconfigure: unknown argument: $1" ;;
	esac
	INSTALLER="$SCRIPT_DIR/install.sh"
	[[ -r "$INSTALLER" ]] || fail 1 "install.sh not found"

	# -y asks for an explicit ACCESS_CONFIRM when the access mode is not
	# localhost. An unchanged mode is already confirmed; a changed one
	# must go through install.sh reconfigure.
	local applied_access applied_bind
	applied_access=$(state_read_value "applied.ACCESS_MODE")
	applied_bind=$(state_read_value "applied.BIND_ADDR")
	if [[ -n "$applied_access" && "$applied_access" == "$(conf_get ACCESS_MODE localhost)" &&
	"${applied_bind:-auto}" == "$(conf_get BIND_ADDR auto)" ]] ||
		[[ "${DPISTACK_ACCESS_CONFIRM:-0}" == "1" ]]; then
		args+=(--set ACCESS_CONFIRM=yes)
	fi

	bash "$INSTALLER" "${args[@]}"
	local rc=$?
	if ((rc == 3)); then
		echo "dpistack: this change needs a reinstall or rebuild, run: dpistack reconfigure" >&2
	fi
	return "$rc"
}

# -------------------------------------------------------------- settings
# The dashboard's settings screen (tech.md 9): every key of the schema
# (lib/schema.sh), its value, the checks of config_validate, and the
# application of a change. The panel never edits dpistack.conf as text for
# this; it sends KEY=VALUE pairs.

SETTINGS_UNIT="dpistack-apply"

settings_json_array() {
	local IFS=',' item first=1
	printf '['
	for item in $1; do
		((first)) || printf ','
		first=0
		printf '"%s"' "$(json_escape "$item")"
	done
	printf ']'
}

# settings_lines_json [max] - stdin lines as a JSON array of strings (the
# last <max> of them); no interpreter besides bash.
settings_lines_json() {
	local max="${1:-200}" line first=1
	local -a all=()
	while IFS= read -r line || [[ -n "$line" ]]; do
		[[ -n "$line" ]] && all+=("$line")
	done
	local n=${#all[@]} i start=0
	((n > max)) && start=$((n - max))
	printf '['
	for ((i = start; i < n; i++)); do
		((first)) || printf ','
		first=0
		printf '"%s"' "$(json_escape "${all[i]}")"
	done
	printf ']'
}

# settings_secret_set <key> - whether secrets.conf holds a value for it.
settings_secret_set() {
	[[ -r "$(path_secrets)" ]] && grep -q "^$1=." "$(path_secrets)"
}

settings_list() {
	local json=0 key first=1 type opts min max value secret set pattern
	[[ "${1:-}" == "--json" ]] && json=1
	if ((json)); then printf '{"keys":['; fi
	for key in "${SCHEMA_KEYS[@]}"; do
		type="${SCHEMA_TYPE[$key]}"
		secret="${SCHEMA_SECRET[$key]}"
		value=""
		set=false
		if [[ "$secret" == "yes" ]]; then
			settings_secret_set "$key" && set=true
		else
			value=$(conf_get "$key" "${SCHEMA_DEFAULT[$key]}")
		fi
		if ((json == 0)); then
			if [[ "$secret" == "yes" ]]; then
				printf '%s=%s\n' "$key" "$([[ $set == true ]] && echo '(set)' || echo '(not set)')"
			else
				printf '%s=%s\n' "$key" "$value"
			fi
			continue
		fi
		((first)) || printf ','
		first=0
		opts="[]"
		min="null"
		max="null"
		if [[ "$type" == "enum" ]]; then
			opts=$(settings_json_array "${SCHEMA_OPTIONS[$key]}")
		elif [[ "$type" == "int" ]]; then
			min="${SCHEMA_OPTIONS[$key]%%..*}"
			max="${SCHEMA_OPTIONS[$key]##*..}"
		fi
		pattern="${SCHEMA_PATTERN[$key]:-}"
		printf '{"key":"%s","type":"%s","options":%s,"min":%s,"max":%s,"default":"%s","level":"%s","group":"%s","weight":"%s","secret":%s,"set":%s,"value":"%s","pattern":"%s"}' \
			"$key" "$type" "$opts" "$min" "$max" "$(json_escape "${SCHEMA_DEFAULT[$key]}")" \
			"${SCHEMA_LEVEL[$key]}" "${SCHEMA_GROUP[$key]}" "${SCHEMA_WEIGHT[$key]}" \
			"$([[ $secret == yes ]] && echo true || echo false)" "$set" \
			"$(json_escape "$value")" "$(json_escape "$pattern")"
	done
	if ((json)); then printf ']}\n'; fi
}

# settings_collect_pairs <args...> - SETTINGS_PAIRS: the KEY=VALUE pairs
# from the arguments, or one per line from stdin when there are none. The
# panel uses stdin: some values (a BPF filter, a rules URL) hold characters
# that the argument check of every verb refuses, and the schema patterns
# are the check that matters for them.
settings_collect_pairs() {
	SETTINGS_PAIRS=()
	local line
	if (($# > 0)); then
		SETTINGS_PAIRS=("$@")
		return 0
	fi
	while IFS= read -r line || [[ -n "$line" ]]; do
		[[ -n "$line" ]] && SETTINGS_PAIRS+=("$line")
	done
	return 0
}

# settings_stage <KEY=VALUE...> - dpistack.conf with the pairs applied, in
# the staging directory; prints its path. Secrets and unknown keys are
# refused here (code 3) so that no later step has to care.
settings_stage() {
	local staging staged pair key value
	staging=$(path_staging_dir)
	mkdir -p "$staging"
	chmod 0700 "$staging"
	staged="$staging/dpistack.conf"
	cp "$(path_conf)" "$staged"
	for pair in "$@"; do
		[[ "$pair" == *=* ]] || fail 2 "settings: KEY=VALUE expected, got: $pair"
		key="${pair%%=*}"
		value="${pair#*=}"
		schema_known "$key" || fail 5 "unknown key: $key"
		if schema_is_secret "$key"; then
			fail 3 "$key: a secret, changed with the settings secret command"
		fi
		awk -v k="$key" -v v="$value" 'BEGIN{done=0} index($0, k "=")==1 {print k "=" v; done=1; next} {print} END{if(!done) print k "=" v}' \
			"$staged" >"$staged.new" && mv "$staged.new" "$staged"
	done
	echo "$staged"
}

# settings_changed <KEY=VALUE...> - the keys whose value differs from the
# current one, one per line.
settings_changed() {
	local pair key
	for pair in "$@"; do
		key="${pair%%=*}"
		[[ "$(conf_get "$key" "${SCHEMA_DEFAULT[$key]}")" == "${pair#*=}" ]] || echo "$key"
	done
}

settings_weight() {
	local key
	for key in "$@"; do
		[[ "${SCHEMA_WEIGHT[$key]}" == "heavy" ]] && {
			echo heavy
			return
		}
	done
	echo light
}

# settings_load_staged <file> - CONF as it will be after the change. The
# validation runs in a command substitution and keeps nothing, so the port
# checks load the staged file themselves.
settings_load_staged() {
	config_reset
	config_load_defaults
	config_load_kv_file "$1"
	[[ -r "$(path_secrets)" ]] && config_load_kv_file "$(path_secrets)"
	return 0
}

# settings_port_warnings <changed keys...> - lines KEY|port|holder|suggestion
# for changed port keys whose port is already taken. Reads CONF as loaded
# from the staged file by config_validate_staged.
settings_port_warnings() {
	local line key
	while IFS= read -r line; do
		[[ -z "$line" ]] && continue
		key="${line%%|*}"
		in_list "$key" "$@" && echo "$line"
	done < <(preflight_port_conflicts)
}

settings_check() {
	local staged out rc changed weight errors warnings first=1 key port who suggestion kind
	settings_collect_pairs "$@"
	[[ ${#SETTINGS_PAIRS[@]} -ge 1 ]] || fail 2 "settings check: at least one KEY=VALUE is needed"
	staged=$(settings_stage "${SETTINGS_PAIRS[@]}") || exit $?
	changed=$(settings_changed "${SETTINGS_PAIRS[@]}")
	# shellcheck disable=SC2086
	weight=$(settings_weight $changed)
	out=$(config_validate_staged dpistack.conf "$staged")
	rc=$?
	errors="[]"
	if ((rc == 0)); then
		# The one conflict of two keys that the preflight would stop on only
		# at the end of a long apply: say it now, in the panel's own words.
		settings_load_staged "$staged"
		if [[ "${CONF[SURICATA_RUNTIME]:-native}" == "docker" && "${CONF[NDPI_ENABLE]:-no}" == "yes" ]]; then
			rc=3
			out="NDPI_ENABLE: the nDPI plugin is not in the Suricata docker image; set NDPI_ENABLE=no in the same change, or keep SURICATA_RUNTIME=native"
		fi
	fi
	if ((rc != 0)); then
		errors=$(printf '%s\n' "$out" | settings_lines_json 50)
	fi
	warnings='['
	if ((rc == 0)); then
		settings_load_staged "$staged"
		# shellcheck disable=SC2086
		while IFS='|' read -r key port who suggestion kind; do
			[[ -z "$key" ]] && continue
			((first)) || warnings+=','
			first=0
			warnings+=$(printf '{"key":"%s","port":%s,"holder":"%s","suggestion":%s,"kind":"%s"}' \
				"$key" "$port" "$(json_escape "$who")" "${suggestion:-null}" "$kind")
		done < <(settings_port_warnings $changed)
	fi
	warnings+=']'
	rm -f "$staged"
	printf '{"ok":%s,"weight":"%s","changed":%s,"errors":%s,"warnings":%s}\n' \
		"$([[ $rc -eq 0 ]] && echo true || echo false)" "$weight" \
		"$(settings_json_array "$(paste -sd, <<<"$changed")")" "$errors" "$warnings"
	return "$rc"
}

settings_set() {
	local mode=commit confirm=0 arg
	local -a pairs=()
	for arg in "$@"; do
		case "$arg" in
		--apply) mode=apply ;;
		--apply-heavy) mode=heavy ;;
		--confirm-access) confirm=1 ;;
		*) pairs+=("$arg") ;;
		esac
	done
	settings_collect_pairs "${pairs[@]}"
	pairs=("${SETTINGS_PAIRS[@]}")
	[[ ${#pairs[@]} -ge 1 ]] || fail 2 "settings set: at least one KEY=VALUE is needed"
	local staged out rc changed weight warn
	staged=$(settings_stage "${pairs[@]}") || exit $?
	changed=$(settings_changed "${pairs[@]}")
	if [[ -z "$changed" ]]; then
		rm -f "$staged"
		echo "no changes"
		return 0
	fi
	# shellcheck disable=SC2086
	weight=$(settings_weight $changed)
	out=$(config_validate_staged dpistack.conf "$staged")
	rc=$?
	if ((rc != 0)); then
		rm -f "$staged"
		[[ -n "$out" ]] && echo "$out"
		fail 3 "settings: check failed, dpistack.conf unchanged"
	fi
	# A busy port is a stop with a way out: the holder and a free port.
	settings_load_staged "$staged"
	# shellcheck disable=SC2086
	warn=$(settings_port_warnings $changed | head -n 1)
	if [[ -n "$warn" ]]; then
		local key port who suggestion
		IFS='|' read -r key port who suggestion _ <<<"$warn"
		rm -f "$staged"
		fail 3 "port $port ($key) is already busy: $who${suggestion:+; free: $suggestion}"
	fi
	if [[ "$weight" == "heavy" && "$mode" == "apply" ]]; then
		rm -f "$staged"
		fail 3 "heavy change ($(paste -sd, <<<"$changed")): --apply-heavy is needed"
	fi
	if ((confirm)); then
		DPISTACK_ACCESS_CONFIRM=1
		export DPISTACK_ACCESS_CONFIRM
	fi
	config_commit dpistack.conf "$staged"
	rm -f "$staged"
	case "$mode" in
	commit) echo "dpistack.conf written, not applied" ;;
	apply)
		if ! ctl_cmd_reconfigure; then
			cmd_config_revert dpistack.conf >/dev/null
			fail 1 "reconfigure failed, dpistack.conf restored"
		fi
		;;
	heavy) settings_start_job "$confirm" ;;
	esac
}

# settings_start_job <confirm-access> - the heavy reconfigure runs as a
# transient unit: packages and builds take minutes, longer than a request.
settings_start_job() {
	local -a args=(reconfigure -y --force)
	[[ "$1" == "1" ]] && args+=(--set ACCESS_CONFIRM=yes)
	case "$(systemctl is-active "$SETTINGS_UNIT.service" 2>/dev/null)" in
	active | activating) fail 3 "applying is already running" ;;
	esac
	systemctl reset-failed "$SETTINGS_UNIT.service" >/dev/null 2>&1 || true
	systemd-run --quiet --unit="$SETTINGS_UNIT" --description="dpistack: applying settings" \
		--collect "$SCRIPT_DIR/install.sh" "${args[@]}" >/dev/null ||
		fail 1 "could not start applying"
	echo "applying started: $SETTINGS_UNIT"
}

settings_job() {
	local state result lines
	state=$(systemctl is-active "$SETTINGS_UNIT.service" 2>/dev/null || true)
	[[ -n "$state" ]] || state=unknown
	result=$(systemctl show -p Result --value "$SETTINGS_UNIT.service" 2>/dev/null || true)
	lines=$(journalctl -u "$SETTINGS_UNIT.service" -n 200 --no-pager -o cat 2>/dev/null | settings_lines_json 200)
	printf '{"state":"%s","result":"%s","log":%s}\n' "$(json_escape "$state")" "$(json_escape "${result:-}")" "$lines"
}

# settings_secret <KEY> - the value comes on stdin and never in an argument.
settings_secret() {
	[[ $# -eq 1 ]] || fail 2 "settings secret: KEY is needed"
	local key="$1" value tmp
	if ! schema_known "$key" || ! schema_is_secret "$key"; then
		fail 5 "$key: not a schema secret"
	fi
	IFS= read -r value || true
	if [[ -n "$value" ]]; then
		schema_validate_one "$key" "$value" >/dev/null || fail 3 "$key: the value does not fit"
	fi
	ctl_lock
	tmp=$(mktemp)
	if [[ -r "$(path_secrets)" ]]; then
		grep -v "^$key=" "$(path_secrets)" >"$tmp" || true
	fi
	if [[ -n "$value" ]]; then
		printf '%s=%s\n' "$key" "$value" >>"$tmp"
	fi
	atomic_write "$(path_secrets)" 0600 <"$tmp"
	rm -f "$tmp"
	ctl_unlock
	if ! ctl_cmd_reconfigure; then
		fail 1 "reconfigure failed, the secret is written"
	fi
}

cmd_settings() {
	local sub="${1:-}"
	[[ $# -ge 1 ]] && shift
	case "$sub" in
	list) settings_list "$@" ;;
	check) settings_check "$@" ;;
	set) settings_set "$@" ;;
	secret) settings_secret "$@" ;;
	job) settings_job ;;
	*) fail 2 "settings: list [--json] | check KEY=VALUE... | set [--apply|--apply-heavy] [--confirm-access] KEY=VALUE... | secret KEY | job" ;;
	esac
}

# ------------------------------------------------------------ self-update
#
# `dpistack self-update [--check] | run | job`: the update of dpistack itself.
# Only a release of the project's own repository is ever installed: the tag
# comes from its "latest release" document, has to be newer than the running
# version, the archive is the one GitHub builds for that tag over https and
# must carry that same version in lib/common.sh. `run` starts the update as
# the transient unit below (the panel restarts in the middle of it), `job`
# shows that unit, `apply` is what the unit runs.

SELFUPDATE_UNIT="dpistack-selfupdate"
SELFUPDATE_API="https://api.github.com/repos/FlexEbat/dpistack/releases/latest"
SELFUPDATE_ARCHIVE="https://github.com/FlexEbat/dpistack/archive/refs/tags"

# selfupdate_url <default> <override-variable> - the override exists for the
# tests only: it is honoured only when DPISTACK_ROOT is set (a sandbox).
selfupdate_url() {
	local default="$1" override="${2:-}"
	if [[ -n "${DPISTACK_ROOT:-}" && -n "$override" ]]; then
		echo "$override"
	else
		echo "$default"
	fi
}

# selfupdate_latest_tag - prints v1.2.3 of the latest release or fails.
selfupdate_latest_tag() {
	local url doc tag
	url=$(selfupdate_url "$SELFUPDATE_API" "${DPISTACK_UPDATE_API:-}")
	doc=$(curl -fsS --max-time 20 -H 'Accept: application/vnd.github+json' "$url") ||
		fail 1 "could not reach the release server"
	tag=$(printf '%s' "$doc" | sed -n 's/.*"tag_name"[[:space:]]*:[[:space:]]*"\([^"]*\)".*/\1/p' | head -n1)
	[[ "$tag" =~ ^v[0-9]+\.[0-9]+\.[0-9]+$ ]] || fail 1 "the latest release has no usable version tag"
	echo "$tag"
}

# selfupdate_is_newer <tag> - 0 when the tag is a higher version than the running one.
selfupdate_is_newer() {
	local v="${1#v}"
	[[ "$v" != "$DPISTACK_VERSION" ]] &&
		[[ "$(printf '%s\n%s\n' "$v" "$DPISTACK_VERSION" | sort -V | tail -n1)" == "$v" ]]
}

selfupdate_check() {
	local tag newer=false json=0
	[[ "${1:-}" == "--json" ]] && json=1
	tag=$(selfupdate_latest_tag) || exit 1
	selfupdate_is_newer "$tag" && newer=true
	if ((json)); then
		printf '{"version":"%s","latest":"%s","update_available":%s}\n' "$DPISTACK_VERSION" "${tag#v}" "$newer"
	elif [[ "$newer" == true ]]; then
		echo "dpistack $DPISTACK_VERSION is running, ${tag#v} is available: sudo dpistack self-update"
	else
		echo "dpistack $DPISTACK_VERSION is the latest version"
	fi
}

selfupdate_run() {
	local tag
	tag=$(selfupdate_latest_tag) || exit 1
	selfupdate_is_newer "$tag" || fail 3 "there is no newer release than $DPISTACK_VERSION"
	case "$(systemctl is-active "$SELFUPDATE_UNIT.service" 2>/dev/null)" in
	active | activating) fail 3 "an update is already running" ;;
	esac
	systemctl reset-failed "$SELFUPDATE_UNIT.service" >/dev/null 2>&1 || true
	systemd-run --quiet --unit="$SELFUPDATE_UNIT" --description="dpistack: updating to ${tag#v}" \
		--collect "$SCRIPT_DIR/install.sh" self-update apply >/dev/null ||
		fail 1 "could not start the update"
	echo "update to ${tag#v} started: $SELFUPDATE_UNIT"
}

selfupdate_job() {
	local state result lines
	state=$(systemctl is-active "$SELFUPDATE_UNIT.service" 2>/dev/null || true)
	[[ -n "$state" ]] || state=unknown
	result=$(systemctl show -p Result --value "$SELFUPDATE_UNIT.service" 2>/dev/null || true)
	lines=$(journalctl -u "$SELFUPDATE_UNIT.service" -n 200 --no-pager -o cat 2>/dev/null | settings_lines_json 200)
	printf '{"state":"%s","result":"%s","log":%s}\n' "$(json_escape "$state")" "$(json_escape "${result:-}")" "$lines"
}

# selfupdate_apply - download, check, then run the NEW installer on the saved
# config: it renews the persistent command, the panel and its unit, and
# restarts what changed. The config is never rewritten with defaults.
selfupdate_apply() {
	local tag url tmp src
	tag=$(selfupdate_latest_tag) || exit 1
	if ! selfupdate_is_newer "$tag"; then
		echo "dpistack $DPISTACK_VERSION is the latest version, nothing to do"
		return 0
	fi
	url=$(selfupdate_url "$SELFUPDATE_ARCHIVE/${tag}.tar.gz" "${DPISTACK_UPDATE_ARCHIVE:-}")
	tmp=$(mktemp -d) || fail 1 "no temporary directory"
	# shellcheck disable=SC2064
	trap "rm -rf '$tmp'" EXIT
	echo "downloading $tag"
	curl -fsSL --max-time 300 -o "$tmp/src.tar.gz" "$url" || fail 1 "could not download $tag"
	# Nothing outside the target directory, whatever the archive says.
	if tar -tzf "$tmp/src.tar.gz" | grep -Eq '(^/|(^|/)\.\.(/|$))'; then
		fail 1 "the archive has an unsafe path, nothing was installed"
	fi
	src="$tmp/src"
	mkdir -p "$src"
	tar -xzf "$tmp/src.tar.gz" -C "$src" --strip-components=1 --no-same-owner ||
		fail 1 "could not unpack the archive"
	[[ -f "$src/install.sh" && -f "$src/lib/common.sh" ]] || fail 1 "the archive is not a dpistack release"
	grep -q "^DPISTACK_VERSION=\"${tag#v}\"" "$src/lib/common.sh" ||
		fail 1 "the archive does not carry the version ${tag#v}, nothing was installed"
	echo "installing ${tag#v} on the saved config"
	(cd "$src" && bash ./install.sh install -y)
}

cmd_self_update() {
	local sub="${1:-}"
	[[ $# -ge 1 ]] && shift
	case "$sub" in
	"" | --check) selfupdate_check ;;
	--json | check) selfupdate_check --json ;;
	run) selfupdate_run ;;
	job) selfupdate_job ;;
	apply)
		restricted_caller && fail 2 "self-update apply: not for the panel, use run"
		selfupdate_apply
		;;
	*) fail 2 "self-update: [--check] | check | run | job | apply" ;;
	esac
}

# ----------------------------------------------------------------- iface

# iface_set_list <comma-list> - writes IFACES into dpistack.conf and
# applies it; a failed apply puts the previous file back.
# conf_apply_value <KEY> <value> - one key of dpistack.conf: checked as a
# whole, committed with a backup, applied by reconfigure; the old file comes
# back when reconfigure fails.
conf_apply_value() {
	local key="$1" value="$2" staging staged out rc
	staging=$(path_staging_dir)
	mkdir -p "$staging"
	chmod 0700 "$staging"
	staged="$staging/dpistack.conf"
	awk -v k="$key" -v v="$value" 'BEGIN{done=0} $0 ~ "^" k "=" {print k "=" v; done=1; next} {print} END{if(!done) print k "=" v}' \
		"$(path_conf)" >"$staged"

	out=$(config_validate_staged dpistack.conf "$staged")
	rc=$?
	if ((rc != 0)); then
		rm -f "$staged"
		[[ -n "$out" ]] && echo "$out"
		fail 3 "$key: check failed, file unchanged"
	fi
	config_commit dpistack.conf "$staged"
	rm -f "$staged"
	if ! ctl_cmd_reconfigure; then
		cmd_config_revert dpistack.conf >/dev/null
		fail 1 "reconfigure failed, dpistack.conf restored"
	fi
}

iface_set_list() { conf_apply_value IFACES "$1"; }

# --------------------------------------------------------------- IPS mode

mode_now() { "${DPISTACK_NOW_CMD:-date}" +%s; }

# mode_pending_deadline - epoch seconds of the rollback, empty when none.
mode_pending_deadline() {
	sed -n 's/^deadline=//p' "$(path_mode_pending)" 2>/dev/null | head -1
}

mode_cancel_timer() {
	systemctl stop "${MODE_ROLLBACK_UNIT}.timer" "${MODE_ROLLBACK_UNIT}.service" >/dev/null 2>&1 || true
	# A rollback service that failed stays loaded under the same name, and
	# the next systemd-run --unit=... would be refused ("already loaded").
	systemctl reset-failed "${MODE_ROLLBACK_UNIT}.timer" "${MODE_ROLLBACK_UNIT}.service" >/dev/null 2>&1 || true
}

# mode_check_ips_possible - everything IPS needs, or the refusal (code 3).
mode_check_ips_possible() {
	[[ "$(conf_get SURICATA_RUNTIME native)" == "native" ]] ||
		fail 3 "mode ips: only for SURICATA_RUNTIME=native"
	if [[ "$(conf_get IPS_METHOD nfq)" == "nfq" ]]; then
		[[ -n "$(ips_backend)" ]] || fail 3 "mode ips: neither iptables nor nft found (needed for the NFQUEUE queue)"
	fi
	command -v suricata >/dev/null 2>&1 || fail 4 "mode ips: suricata is not installed"
}

# mode_drop_rules_present - something can drop: a "drop" or "reject" rule in
# local.rules, or a line in drop.conf (suricata-update turns the rules it
# names into drop). Without either IPS only alerts, like IDS.
mode_drop_rules_present() {
	grep -Eqs '^[[:space:]]*(drop|reject)[[:space:]]' "$(path_suricata_local_rules)" && return 0
	grep -Eqs '^[[:space:]]*[^#[:space:]]' "$(path_suricata_drop_conf)"
}

mode_go_ids() {
	mode_cancel_timer
	rm -f "$(path_mode_pending)"
	# The rules go first: with no NFQUEUE jump, nothing waits for Suricata
	# while it restarts in ids mode.
	ips_fw_remove
	if [[ "$(conf_get SURICATA_MODE ids)" != "ids" ]]; then
		conf_apply_value SURICATA_MODE ids
	fi
}

cmd_mode_status() {
	local json=0
	[[ "${1:-}" == "--json" ]] && json=1
	local mode method deadline now remaining=0 pending=false
	mode=$(conf_get SURICATA_MODE ids)
	method=$(conf_get IPS_METHOD nfq)
	deadline=$(mode_pending_deadline)
	if [[ -n "$deadline" ]]; then
		now=$(mode_now)
		remaining=$((deadline - now))
		((remaining < 0)) && remaining=0
		pending=true
	fi
	if ((json)); then
		printf '{"mode":"%s","method":"%s","pending":%s,"remaining_sec":%d}\n' "$mode" "$method" "$pending" "$remaining"
	else
		echo "mode: $mode (method $method)"
		[[ "$pending" == "true" ]] && echo "waiting for mode-confirm: ${remaining} s until the rollback to ids"
	fi
	return 0
}

cmd_mode() {
	[[ $# -ge 1 ]] || fail 2 "mode: ids|ips|status"
	local target="$1"
	shift
	case "$target" in
	status)
		cmd_mode_status "$@"
		return
		;;
	ids | ips) ;;
	*) fail 2 "mode: ids|ips|status" ;;
	esac

	local timeout="$MODE_TIMEOUT_DEFAULT"
	while (($# > 0)); do
		case "$1" in
		--confirm-timeout)
			[[ $# -ge 2 && "$2" =~ ^[0-9]+$ ]] || fail 2 "mode: --confirm-timeout needs a number of seconds"
			timeout="$2"
			shift 2
			;;
		*) fail 2 "mode: unknown argument: $1" ;;
		esac
	done
	((timeout >= MODE_TIMEOUT_MIN && timeout <= MODE_TIMEOUT_MAX)) ||
		fail 2 "mode: --confirm-timeout from $MODE_TIMEOUT_MIN to $MODE_TIMEOUT_MAX seconds"

	if [[ "$target" == "ids" ]]; then
		mode_go_ids
		echo "ids mode"
		return 0
	fi

	mode_check_ips_possible
	if [[ "$(conf_get SURICATA_MODE ids)" == "ips" && -z "$(mode_pending_deadline)" ]]; then
		echo "already in ips mode"
		return 0
	fi

	# Suricata restarts in ips first; only then do the rules start sending
	# it traffic. --queue-bypass is there for the time it is down.
	mode_cancel_timer
	conf_apply_value SURICATA_MODE ips
	if [[ "$(conf_get IPS_METHOD nfq)" == "nfq" ]]; then
		if ! ips_fw_apply "$(conf_get IPS_NFQ_CHAINS INPUT,OUTPUT,FORWARD)"; then
			ips_fw_remove
			conf_apply_value SURICATA_MODE ids
			fail 1 "mode ips: the firewall rules were not applied, the mode is back to ids"
		fi
	fi

	local deadline
	deadline=$(($(mode_now) + timeout))
	mkdir -p "$(path_state_dir)"
	printf 'deadline=%s\n' "$deadline" >"$(path_mode_pending)"
	if ! systemd-run --unit="$MODE_ROLLBACK_UNIT" --on-active="${timeout}s" --timer-property=AccuracySec=1s \
		"$(path_ctl_bin)" mode-rollback >/dev/null 2>&1; then
		# Without a timer there is nothing to bring the host back.
		mode_go_ids
		fail 1 "mode ips: could not start the rollback timer, the mode is back to ids"
	fi
	echo "ips mode enabled; confirm with the mode-confirm command within ${timeout} s, or it goes back to ids"
	mode_drop_rules_present ||
		echo "warning: there are no drop rules (neither in local.rules nor in drop.conf), IPS will only alert, like IDS"
}

cmd_mode_confirm() {
	[[ $# -eq 0 ]] || fail 2 "mode-confirm: no arguments"
	local deadline
	deadline=$(mode_pending_deadline)
	[[ -n "$deadline" ]] || fail 3 "mode-confirm: nothing to confirm (there is no switch to ips or it has already rolled back)"
	if (($(mode_now) > deadline)); then
		fail 3 "mode-confirm: the confirmation time is over, the mode is going back to ids"
	fi
	mode_cancel_timer
	rm -f "$(path_mode_pending)"
	echo "ips mode confirmed"
}

# mode-rollback runs from the timer (and at boot): an unconfirmed switch
# goes back to ids, the DPISTACK rules go away.
cmd_mode_rollback() {
	[[ -n "$(mode_pending_deadline)" ]] || return 0
	mode_go_ids
	echo "ips mode not confirmed, back to ids"
}

cmd_fw() {
	[[ $# -eq 1 ]] || fail 2 "fw: apply|remove|restore"
	case "$1" in
	apply)
		ips_fw_apply "$(conf_get IPS_NFQ_CHAINS INPUT,OUTPUT,FORWARD)" || fail 1 "fw apply: the firewall refused"
		;;
	remove) ips_fw_remove ;;
	restore)
		# Boot: an unconfirmed switch did not survive the reboot, the rest
		# is put back as the config says.
		if [[ -n "$(mode_pending_deadline)" ]]; then
			cmd_mode_rollback
		elif [[ "$(conf_get SURICATA_MODE ids)" == "ips" && "$(conf_get IPS_METHOD nfq)" == "nfq" ]]; then
			ips_fw_apply "$(conf_get IPS_NFQ_CHAINS INPUT,OUTPUT,FORWARD)" || fail 1 "fw restore: the firewall refused"
		elif ips_fw_present; then
			ips_fw_remove
		fi
		;;
	*) fail 2 "fw: apply|remove|restore" ;;
	esac
}

cmd_iface() {
	[[ $# -ge 1 ]] || fail 2 "iface: list|add|remove"
	local sub="$1"
	shift
	local -a current=()
	IFS=',' read -ra current <<<"$(conf_get IFACES enp2s0)"

	case "$sub" in
	list)
		[[ $# -eq 0 ]] || fail 2 "iface list: no arguments"
		printf '%s\n' "${current[@]}"
		;;
	add)
		[[ $# -eq 1 ]] || fail 2 "iface add: an interface name is needed"
		if [[ ! "$1" =~ ^[A-Za-z0-9][A-Za-z0-9._-]{0,14}$ ]] || ! ip link show "$1" >/dev/null 2>&1; then
			fail 5 "the interface is not in the system: $1"
		fi
		if in_list "$1" "${current[@]}"; then
			echo "already in the list: $1"
			return 0
		fi
		current+=("$1")
		iface_set_list "$(
			IFS=,
			echo "${current[*]}"
		)"
		;;
	remove)
		[[ $# -eq 1 ]] || fail 2 "iface remove: an interface name is needed"
		in_list "$1" "${current[@]}" || fail 5 "the interface is not in IFACES: $1"
		((${#current[@]} > 1)) || fail 3 "cannot remove the last interface"
		local -a rest=() i
		for i in "${current[@]}"; do
			[[ "$i" == "$1" ]] || rest+=("$i")
		done
		iface_set_list "$(
			IFS=,
			echo "${rest[*]}"
		)"
		;;
	*) fail 2 "iface: unknown subcommand: $sub" ;;
	esac
}

# ----------------------------------------------------------------- rules

# rules_edit_line <name> add|remove <line> - one exact line in a
# suricata-update input file, through the same backup and atomic
# replace as config-write.
rules_edit_line() {
	local name="$1" op="$2" line="$3" path staging staged
	path=$(config_path "$name")
	staging=$(path_staging_dir)
	mkdir -p "$staging"
	chmod 0700 "$staging"
	staged="$staging/$name"
	if [[ -f "$path" ]]; then
		grep -vxF -- "$line" "$path" >"$staged" || true
	else
		: >"$staged"
	fi
	[[ "$op" == "add" ]] && printf '%s\n' "$line" >>"$staged"
	config_commit "$name" "$staged"
	rm -f "$staged"
}

cmd_rules_group() {
	[[ $# -eq 2 ]] || fail 2 "rules-group: enable|disable <group>"
	[[ "$2" =~ ^[A-Za-z0-9][A-Za-z0-9._-]*$ ]] || fail 5 "invalid group name"
	case "$1" in
	enable) rules_edit_line enable.conf add "group:$2.rules" ;;
	disable) rules_edit_line enable.conf remove "group:$2.rules" ;;
	*) fail 2 "rules-group: enable|disable" ;;
	esac
}

cmd_rules_sid() {
	[[ $# -eq 2 ]] || fail 2 "rules-sid: enable|disable <sid>"
	[[ "$2" =~ ^[0-9]+$ ]] || fail 5 "sid must be a number"
	case "$1" in
	disable) rules_edit_line disable.conf add "$2" ;;
	enable) rules_edit_line disable.conf remove "$2" ;;
	*) fail 2 "rules-sid: enable|disable" ;;
	esac
}

cmd_rules_sources() {
	[[ $# -ge 1 ]] || fail 2 "rules-sources: list|enable|disable|add-url|remove"
	local sub="$1" data_dir
	shift
	data_dir=$(path_rules_data_dir)
	command -v suricata-update >/dev/null 2>&1 || fail 4 "suricata-update is not installed"
	case "$sub" in
	list)
		if [[ $# -eq 1 && "$1" == "--enabled" ]]; then
			suricata-update list-enabled-sources -D "$data_dir"
			return
		fi
		[[ $# -eq 0 ]] || fail 2 "rules-sources list: no arguments or --enabled"
		suricata-update list-sources -D "$data_dir"
		;;
	enable | disable | remove)
		[[ $# -eq 1 ]] || fail 2 "rules-sources $sub: a source name is needed"
		# No leading "-": the name goes to suricata-update as an argument and
		# would be read as an option.
		[[ "$1" =~ ^[A-Za-z0-9][A-Za-z0-9._/-]*$ ]] || fail 5 "invalid source name"
		suricata-update "$sub-source" -D "$data_dir" "$1"
		;;
	add-url)
		[[ $# -eq 1 ]] || fail 2 "rules-sources add-url: a URL is needed"
		[[ "$1" =~ ^https?://[A-Za-z0-9._:/@+,=-]+$ ]] || fail 5 "invalid URL"
		suricata-update add-source -D "$data_dir" \
			"dpistack-custom-$(printf '%s' "$1" | sha256sum | cut -c1-8)" "$1"
		;;
	*) fail 2 "rules-sources: unknown subcommand: $sub" ;;
	esac
}

cmd_rules_search() {
	[[ $# -eq 1 && -n "$1" ]] || fail 2 "rules-search: exactly one query is needed"
	local ruleset
	ruleset=$(path_suricata_ruleset)
	[[ -f "$ruleset" ]] || fail 4 "no rule set"
	# A number matches the sid exactly, anything else matches msg text.
	RULES_Q="$1" awk -v max="$RULES_SEARCH_MAX" '
		BEGIN { q = tolower(ENVIRON["RULES_Q"]); num = (q ~ /^[0-9]+$/) }
		/^[ \t]*#/ { next }
		{
			sid = ""; msg = ""
			if (match($0, /sid: *[0-9]+/)) { sid = substr($0, RSTART, RLENGTH); gsub(/[^0-9]/, "", sid) }
			if (match($0, /msg: *"[^"]*"/)) { msg = substr($0, RSTART, RLENGTH); sub(/^msg: *"/, "", msg); sub(/"$/, "", msg) }
			if (sid == "") next
			if (num ? (sid == q) : (index(tolower(msg), q) > 0)) {
				print sid "\t" msg
				if (++n >= max) exit
			}
		}' "$ruleset"
}

# cmd_rules_update - snapshot, suricata-update, suricata -T, reload;
# any failure puts the previous ruleset back. What the tools said goes to
# stdout (the last RULES_UPDATE_TAIL lines) on success and on failure, so
# the panel can show the reason: its caller keeps only the first line of
# stderr, which for suricata-update is a log header, not the cause.
RULES_UPDATE_TAIL=40

cmd_rules_update() {
	[[ $# -eq 0 ]] || fail 2 "rules-update: no arguments"
	command -v suricata-update >/dev/null 2>&1 || fail 4 "suricata-update is not installed"
	local ruleset snap log
	ruleset=$(path_suricata_ruleset)
	snap=$(mktemp)
	log=$(mktemp)
	if [[ -f "$ruleset" ]]; then
		cp -p "$ruleset" "$snap"
	else
		rm -f "$snap"
		snap=""
	fi

	local ok=1
	rules_update_argv
	"${RULES_UPDATE_ARGV[@]}" >"$log" 2>&1 || ok=0
	if ((ok)) && [[ "$(component_unit suricata)" == docker:* ]]; then
		if ! docker_suricata_test >>"$log" 2>&1; then
			echo "suricata -T did not accept the new rule set" >>"$log"
			ok=0
		fi
	elif ((ok)) && command -v suricata >/dev/null 2>&1; then
		local check_dir
		check_dir=$(mktemp -d)
		if ! suricata -T -c "$(path_suricata_yaml)" -l "$check_dir" >>"$log" 2>&1; then
			echo "suricata -T did not accept the new rule set" >>"$log"
			ok=0
		fi
		rm -rf "$check_dir"
	fi
	if ((ok)); then
		suricata_reload_now >>"$log" 2>&1 || {
			echo "reloading the rules failed" >>"$log"
			ok=0
		}
	fi
	tail -n "$RULES_UPDATE_TAIL" "$log"
	rm -f "$log"

	if ((!ok)); then
		if [[ -n "$snap" ]]; then
			cp -p "$snap" "$ruleset"
			rm -f "$snap"
		fi
		fail 1 "rules-update failed, the previous rule set is restored"
	fi
	[[ -n "$snap" ]] && rm -f "$snap"
	return 0
}

# ------------------------------------------------------------------ test

cmd_test() {
	[[ $# -ge 1 && $# -le 2 ]] || fail 2 "test: bittorrent|https|all [--json]"
	local which="$1" json=0
	if [[ $# -eq 2 ]]; then
		[[ "$2" == "--json" ]] || fail 2 "test: unknown argument: $2"
		json=1
	fi
	local -a names
	case "$which" in
	bittorrent | https) names=("$which") ;;
	all) names=("${VERIFY_TESTS[@]}") ;;
	*) fail 5 "unknown test: $which" ;;
	esac
	# shellcheck disable=SC2034 # read by lib/step_verify.sh
	VERIFY_HTTPS_URL=$(conf_get TEST_HTTPS_URL https://example.com)
	# shellcheck disable=SC2034 # read by lib/step_verify.sh
	VERIFY_BT_LIVE=$(conf_get TEST_BT_LIVE no)
	# shellcheck disable=SC2034 # read by lib/step_verify.sh
	VERIFY_IFACES=$(conf_get IFACES enp2s0)
	verify_run "$json" "${names[@]}" || exit 1
}

# ---------------------------------------------------------------- health

# cmd_health - one watchdog run, then the same JSON it wrote.
cmd_health() {
	local json=0
	case "${1:-}" in
	"") ;;
	--json) json=1 ;;
	*) fail 2 "health: unknown argument" ;;
	esac
	[[ $# -le 1 ]] || fail 2 "health: extra arguments"
	local watch="$SCRIPT_DIR/bin/dpistack-watch"
	[[ -x "$watch" ]] || fail 4 "dpistack-watch is not installed"
	"$watch" || fail 1 "health: dpistack-watch failed"
	local file
	file=$(path_health_json)
	[[ -f "$file" ]] || fail 1 "health: $file was not created"
	if ((json)); then
		cat "$file"
	else
		jq -r '"overall: \(.overall)  (\(.ts))", (.checks[] | "\(.id)\t\(.status)\t\(.value)\t\(.detail)")' "$file" || fail 1 "health: jq is needed"
	fi
}

# ----------------------------------------------------------- panel-passwd

cmd_panel_passwd() {
	[[ $# -eq 0 ]] || fail 2 "panel-passwd: the password is read from stdin"
	local pw=""
	IFS= read -r pw || true
	[[ -n "$pw" ]] || fail 2 "panel-passwd: empty password"
	command -v argon2 >/dev/null 2>&1 || fail 1 "the argon2 package is not installed"
	panel_auth_write "$pw" || fail 1 "could not write the password hash"
	echo "panel password updated"
}

ctl_main() {
	if [[ $# -eq 0 ]]; then
		ctl_usage
		exit 2
	fi

	# Every argument is checked before any command runs (4.5).
	local arg
	for arg in "$@"; do
		[[ "$arg" =~ ^[A-Za-z0-9._:=/@+,\ -]*$ ]] || fail 5 "invalid characters in the argument"
	done

	local cmd="$1"
	shift
	case "$cmd" in
	status) ctl_cmd_status "$@" ;;
	start | stop | restart) cmd_control "$cmd" "$@" ;;
	reload) cmd_reload "$@" ;;
	logs) cmd_logs "$@" ;;
	config-read) cmd_config_read "$@" ;;
	config-write) cmd_config_write "$@" ;;
	config-revert) cmd_config_revert "$@" ;;
	settings) cmd_settings "$@" ;;
	self-update) cmd_self_update "$@" ;;
	reconfigure) ctl_cmd_reconfigure "$@" ;;
	rules-update) cmd_rules_update "$@" ;;
	rules-sources) cmd_rules_sources "$@" ;;
	rules-group) cmd_rules_group "$@" ;;
	rules-sid) cmd_rules_sid "$@" ;;
	rules-search) cmd_rules_search "$@" ;;
	iface) cmd_iface "$@" ;;
	mode) cmd_mode "$@" ;;
	mode-confirm) cmd_mode_confirm "$@" ;;
	mode-rollback) cmd_mode_rollback "$@" ;;
	fw) cmd_fw "$@" ;;
	panel-passwd) cmd_panel_passwd "$@" ;;
	test) cmd_test "$@" ;;
	health) cmd_health "$@" ;;
	version) echo "$DPISTACK_VERSION" ;;
	*)
		ctl_usage >&2
		exit 2
		;;
	esac
}
DPISTACK_BUNDLE_END
put lib/ips.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# IPS mode (slice 29): the DPISTACK chain and its jumps. Shared by
# dpistack (mode, fw) and the installer (uninstall).
#
# The installer never flushes, deletes or reorders a chain that is not its
# own. What it does add to the standard chains is one rule each, the jump
# "-j DPISTACK" at position 1 (IPS_NFQ_CHAINS says which chains); the
# chain DPISTACK holds one NFQUEUE rule with --queue-bypass, so a stopped
# Suricata lets traffic through instead of cutting the network.

IPS_CHAIN="DPISTACK"
IPS_QUEUE_NUM=0
IPS_ALL_CHAINS=(INPUT OUTPUT FORWARD)

# ips_tools - the iptables front ends that exist (v4 and v6 if there).
ips_tools() {
	command -v iptables >/dev/null 2>&1 && echo iptables
	command -v ip6tables >/dev/null 2>&1 && echo ip6tables
	return 0
}

# ips_backend - which firewall front end carries the queue rules: iptables
# where it exists (also iptables-nft), nft on a system that has only nft
# (a minimal Rocky/Alma, say). Prints nothing when there is neither.
# nft keeps its own table "inet dpistack" (v4 and v6 in one), so the rules of
# the host stay untouched there too.
ips_backend() {
	if command -v iptables >/dev/null 2>&1; then
		echo iptables
	elif command -v nft >/dev/null 2>&1; then
		echo nft
	fi
	return 0
}

IPS_NFT_TABLE="dpistack"

# ips_nft_hook <chain> - the nft hook of an iptables chain name.
ips_nft_hook() {
	case "$1" in
	INPUT) echo input ;;
	OUTPUT) echo output ;;
	FORWARD) echo forward ;;
	esac
}

# ips_nft_ruleset <chains> - the table as one nft script. "add" and "delete"
# first make the rebuild atomic and repeatable whether or not it existed.
ips_nft_ruleset() {
	local chain hook
	echo "add table inet $IPS_NFT_TABLE"
	echo "delete table inet $IPS_NFT_TABLE"
	echo "table inet $IPS_NFT_TABLE {"
	for chain in $(ips_nfq_chains "$1"); do
		hook=$(ips_nft_hook "$chain")
		[[ -n "$hook" ]] || continue
		echo "	chain $hook {"
		echo "		type filter hook $hook priority -10; policy accept;"
		echo "		queue num $IPS_QUEUE_NUM bypass"
		echo "	}"
	done
	echo "}"
}

# ips_nfq_chains - the chains that get the jump, from IPS_NFQ_CHAINS.
ips_nfq_chains() {
	local list="${1:-INPUT,OUTPUT,FORWARD}" c
	local IFS=,
	for c in $list; do
		[[ -n "$c" ]] && echo "$c"
	done
	return 0
}

# ips_fw_apply <chains> - create and fill DPISTACK, put the jumps in.
# Repeatable: the chain is rebuilt, a jump is added only if missing.
ips_fw_apply() {
	local chains="$1" tool chain
	if [[ "$(ips_backend)" == "nft" ]]; then
		ips_nft_ruleset "$chains" | nft -f - || return 1
		return 0
	fi
	# iptables carries the rules: a table left by an earlier nft run must go,
	# or every packet would be queued twice.
	ips_nft_remove
	for tool in $(ips_tools); do
		"$tool" -w -N "$IPS_CHAIN" 2>/dev/null || true
		"$tool" -w -F "$IPS_CHAIN" || return 1
		"$tool" -w -A "$IPS_CHAIN" -j NFQUEUE --queue-num "$IPS_QUEUE_NUM" --queue-bypass || return 1
		for chain in $(ips_nfq_chains "$chains"); do
			"$tool" -w -C "$chain" -j "$IPS_CHAIN" 2>/dev/null ||
				"$tool" -w -I "$chain" 1 -j "$IPS_CHAIN" || return 1
		done
	done
	return 0
}

# ips_fw_present - DPISTACK exists in iptables.
ips_fw_present() {
	local tool
	ips_nft_present && return 0
	for tool in $(ips_tools); do
		"$tool" -w -n -L "$IPS_CHAIN" >/dev/null 2>&1 && return 0
	done
	return 1
}

# ips_fw_remove - take out every jump to DPISTACK (whatever the current
# IPS_NFQ_CHAINS says) and then the chain itself. Nothing else is touched.
ips_fw_remove() {
	local tool chain
	ips_nft_remove
	for tool in $(ips_tools); do
		for chain in "${IPS_ALL_CHAINS[@]}"; do
			while "$tool" -w -C "$chain" -j "$IPS_CHAIN" 2>/dev/null; do
				"$tool" -w -D "$chain" -j "$IPS_CHAIN" || break
			done
		done
		if "$tool" -w -n -L "$IPS_CHAIN" >/dev/null 2>&1; then
			"$tool" -w -F "$IPS_CHAIN"
			"$tool" -w -X "$IPS_CHAIN"
		fi
	done
	return 0
}

# ips_nft_present - the table "inet dpistack" exists.
ips_nft_present() {
	command -v nft >/dev/null 2>&1 && nft list table inet "$IPS_NFT_TABLE" >/dev/null 2>&1
}

# ips_nft_remove - delete our own table, and only that.
ips_nft_remove() {
	if ips_nft_present; then
		nft delete table inet "$IPS_NFT_TABLE" || return 1
	fi
	return 0
}
DPISTACK_BUNDLE_END
put lib/menu.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Plain-Bash text menu for `install`/`reconfigure` (tech.md 5.0, 5.1,
# 5.3). No dialog/whiptail/ncurses/cursor codes: every screen is just
# printed again, so it works over SSH, in tmux, and stays in scrollback.

MENU_GROUPS=(capture components eve rules access metrics watch tests)
declare -A MENU_GROUP_TITLE=(
	[capture]="Capture and mode"
	[components]="Components and sources"
	[eve]="EVE and storage"
	[rules]="Rules"
	[access]="Access"
	[metrics]="Metrics"
	[watch]="Watch and alerts"
	[tests]="Tests"
)

MENU_SHOW_ADVANCED=0
MENU_FAST=0 # --fast: the quick install questions first, no guided setup
MENU_DIRTY=0
declare -A MENU_OLD_CONF # snapshot for reconfigure's "~" marker and diff
MENU_PANEL_PASSWORD=""   # plaintext, held only in memory until hashed
MENU_PANEL_PASSWORD_SET=0

menu_color_on() {
	[[ -z "${NO_COLOR:-}" && "${CLI_NO_COLOR:-0}" != "1" && -t 1 ]]
}
menu_c() {
	# menu_c <code> <text>
	if menu_color_on; then
		printf '\033[%sm%s\033[0m' "$1" "$2"
	else
		printf '%s' "$2"
	fi
}
menu_bold() { menu_c 1 "$1"; }
menu_red() { menu_c 31 "$1"; }

MENU_INPUT_OPENED=0
menu_open_input() {
	[[ "$MENU_INPUT_OPENED" == "1" ]] && return 0
	exec 8<"${DPISTACK_INPUT:-${DPISTACK_TTY_DEV:-/dev/tty}}"
	MENU_INPUT_OPENED=1
	trap 'menu_on_interrupt' INT
}
menu_close_input() {
	[[ "$MENU_INPUT_OPENED" == "1" ]] && exec 8<&-
	MENU_INPUT_OPENED=0
}

# menu_on_interrupt - Ctrl+C: change nothing, leave no temp files.
menu_on_interrupt() {
	echo >&2
	echo "interrupted, nothing changed" >&2
	menu_close_input
	exit 130
}

MENU_EOF=0

# menu_read <varname> [prompt] - reads one line from fd 8 straight into
# $varname (no command substitution: that runs in a subshell, so an
# EOF flag set inside it would never reach the caller). Sets MENU_EOF
# on a failed read; $varname is cleared to "" in that case.
menu_read() {
	local __menu_read_var="$1" prompt="${2:-}"
	[[ -n "$prompt" ]] && printf '%s' "$prompt" >&2
	# shellcheck disable=SC2229 # intentional indirection: read into the variable named by $__menu_read_var
	if IFS= read -r "$__menu_read_var" <&8; then
		MENU_EOF=0
	else
		MENU_EOF=1
		printf -v "$__menu_read_var" '%s' ""
	fi
}

# menu_die_on_eof - call right after menu_read in every screen loop:
# a closed/exhausted input source must stop the menu instead of
# spinning forever on "" being treated as an unknown choice.
menu_die_on_eof() {
	if [[ "$MENU_EOF" == "1" ]]; then
		echo "end of input, leaving without applying" >&2
		menu_close_input
		exit 2
	fi
}

# menu_confirm <question> [y|n] - a yes/no question before an action (v0.25.0:
# every action of the menu asks first). `0` and `q` cancel like `n`; Enter
# takes the default (second argument, `y` unless said). Returns 0 on yes.
# DPISTACK_MENU_ASSUME_YES=1 answers yes without asking (a test hook: the
# older menu tests drive the screens with fixed input lines).
menu_confirm() {
	local question="$1" default="${2:-y}" answer hint
	[[ "${DPISTACK_MENU_ASSUME_YES:-0}" == "1" ]] && return 0
	if [[ "$default" == "y" ]]; then hint="[Y/n, 0 = cancel]"; else hint="[y/N, 0 = cancel]"; fi
	while true; do
		menu_read answer "$question $hint "
		menu_die_on_eof
		case "${answer,,}" in
		"")
			[[ "$default" == "y" ]]
			return
			;;
		y | yes) return 0 ;;
		n | no | 0 | q | cancel) return 1 ;;
		*) echo "  answer y, n or 0" >&2 ;;
		esac
	done
}

# menu_read_secret <varname> [prompt] - like menu_read, but suppresses
# echo on a real tty (a file source like DPISTACK_INPUT has nothing to
# suppress).
menu_read_secret() {
	local __menu_read_var="$1" prompt="${2:-}"
	[[ -n "$prompt" ]] && printf '%s' "$prompt" >&2
	local is_tty=0
	[[ -t 8 ]] && is_tty=1
	[[ "$is_tty" == "1" ]] && stty -echo 2>/dev/null
	# shellcheck disable=SC2229 # intentional indirection: read into the variable named by $__menu_read_var
	if IFS= read -r "$__menu_read_var" <&8; then
		MENU_EOF=0
	else
		MENU_EOF=1
		printf -v "$__menu_read_var" '%s' ""
	fi
	[[ "$is_tty" == "1" ]] && {
		stty echo 2>/dev/null
		echo >&2
	}
}

# shellcheck disable=SC2034 # read by install.sh after panel_password_apply
PANEL_PASSWORD_JUST_GENERATED=0
# shellcheck disable=SC2034 # read by install.sh after panel_password_apply
PANEL_PASSWORD_GENERATED_VALUE=""

# panel_password_apply - called from cmd_install/cmd_reconfigure after
# validation. The hash is argon2id (4.5 panel-passwd, 9), so the
# plaintext never reaches dpistack.conf, secrets.conf or the logs.
panel_password_apply() {
	local plaintext=""
	# --dry-run must not write panel.auth, install argon2 or print a
	# password: a generated one would be shown but never stored, so the
	# real run would then create a different one (R81).
	[[ "${DRY_RUN:-0}" == "1" ]] && return 0
	if [[ "$MENU_PANEL_PASSWORD_SET" == "1" ]]; then
		plaintext="$MENU_PANEL_PASSWORD"
	elif [[ "${NON_INTERACTIVE:-0}" == "1" && ! -f "$(path_panel_auth)" ]]; then
		if [[ -n "${DPISTACK_PANEL_PASSWORD:-}" ]]; then
			plaintext="$DPISTACK_PANEL_PASSWORD"
		else
			plaintext=$(head -c 24 /dev/urandom | base64 | tr -dc 'A-Za-z0-9' | head -c 24)
			# shellcheck disable=SC2034 # read by install.sh after panel_password_apply
			PANEL_PASSWORD_JUST_GENERATED=1
			# shellcheck disable=SC2034 # read by install.sh after panel_password_apply
			PANEL_PASSWORD_GENERATED_VALUE="$plaintext"
		fi
	else
		return 0
	fi

	command -v argon2 >/dev/null 2>&1 || pkg_install argon2
	panel_auth_write "$plaintext" || die 1 "could not write the panel password hash (argon2)"
	MENU_PANEL_PASSWORD=""
}

menu_draft_save() {
	local key
	{
		for key in $(printf '%s\n' "${!CONF[@]}" | sort); do
			printf '%s=%s\n' "$key" "${CONF[$key]}"
		done
	} | atomic_write "$(path_conf_draft)" 0600
}

menu_draft_delete() { rm -f "$(path_conf_draft)"; }

menu_mark_for_key() {
	local key="$1" mark="" current
	if schema_is_secret "$key"; then
		current="${SECRETS[$key]:-}"
	else
		current="${CONF[$key]:-}"
	fi
	if schema_validate_one "$key" "$current" >/dev/null; then :; else mark="!"; fi
	if [[ -n "${MENU_OLD_CONF[$key]+x}" ]]; then
		[[ "$current" != "${MENU_OLD_CONF[$key]}" ]] && mark="~${mark}"
	elif [[ -n "${SCHEMA_DEFAULT[$key]+x}" && "$current" != "${SCHEMA_DEFAULT[$key]}" ]]; then
		mark="*${mark}"
	fi
	printf '%s' "$mark"
}

# menu_reconcile_conflicts - keys that cannot be on together are settled at
# the moment they are set, not only at the preflight: the Suricata image of
# the docker runtime has no nDPI plugin, so choosing that runtime switches
# the plugin off and says so (decision D6 of 18.27).
menu_reconcile_conflicts() {
	if [[ "${CONF[SURICATA_RUNTIME]:-native}" == "docker" && "${CONF[NDPI_ENABLE]:-no}" == "yes" ]]; then
		config_set_kv NDPI_ENABLE no
		echo "  note: the nDPI plugin is not in the Suricata docker image, so \"with the nDPI plugin\" is switched off (use the native runtime to have it)" >&2
	fi
}

menu_problems() { config_validate; }

menu_problems_count() {
	local out
	out=$(config_validate)
	[[ -z "$out" ]] && {
		echo 0
		return
	}
	printf '%s\n' "$out" | wc -l
}

menu_group_summary() {
	# One short line per group for the main screen's right column.
	case "$1" in
	capture) echo "${CONF[SURICATA_MODE]^^}, ${CONF[IFACES]:-?}" ;;
	components) echo "Suricata: ${CONF[SURICATA_SOURCE]}, with the nDPI plugin: $([[ ${CONF[NDPI_ENABLE]} == yes ]] && echo yes || echo no)" ;;
	eve)
		local n
		n=$(tr ',' '\n' <<<"${CONF[EVE_TYPES]}" | grep -c .)
		echo "$n types, rotation ${CONF[EVE_ROTATE]}"
		;;
	rules) echo "${CONF[RULES_SOURCES]}, ${CONF[RULES_UPDATE_CALENDAR]}" ;;
	access) echo "${CONF[ACCESS_MODE]}" ;;
	metrics) echo "export: $([[ ${CONF[METRICS_EXPORT]} == yes ]] && echo yes || echo no), backend: ${CONF[METRICS_BACKEND]}" ;;
	watch) echo "${CONF[ALERT_CHANNELS]}" ;;
	tests) echo "after install: $([[ ${CONF[TEST_ON_INSTALL]} == yes ]] && echo yes || echo no)" ;;
	esac
}

# menu_edit_key <key> - the single-key editing loop (5.0): Enter keeps
# the value, '-' resets to default, '?' repeats the hint, anything else
# is validated immediately; an invalid value is rejected with the
# allowed list and the old value stays.
menu_edit_key() {
	local key="$1"
	while true; do
		local current="${CONF[$key]:-}"
		local opts="${SCHEMA_OPTIONS[$key]}"
		echo "$key (now: ${current:-<empty>}, default: ${SCHEMA_DEFAULT[$key]:-<empty>})" >&2
		[[ -n "$opts" ]] && echo "  options: $opts" >&2
		local answer
		if schema_is_secret "$key"; then
			menu_read_secret answer "New value (Enter or cancel = leave, - resets, ? help): "
		else
			menu_read answer "New value (Enter or cancel = leave, - resets, ? help): "
		fi
		menu_die_on_eof
		case "$answer" in
		"" | cancel) return 0 ;;
		"?")
			echo "  ${key}: group ${SCHEMA_GROUP[$key]}, type ${SCHEMA_TYPE[$key]}" >&2
			continue
			;;
		"-")
			config_set_kv "$key" "${SCHEMA_DEFAULT[$key]}"
			menu_draft_save
			return 0
			;;
		*)
			local err
			if err=$(schema_validate_one "$key" "$answer"); then
				config_set_kv "$key" "$answer"
				menu_reconcile_conflicts
				menu_draft_save
				MENU_DIRTY=1
				return 0
			else
				echo "  $err" >&2
				continue
			fi
			;;
		esac
	done
}

menu_section_keys() {
	local group="$1" key
	for key in "${SCHEMA_KEYS[@]}"; do
		[[ "${SCHEMA_GROUP[$key]}" == "$group" ]] || continue
		[[ "$key" == "METRICS_TOKEN" ]] && continue # generated, not editable (5.0)
		if [[ "$MENU_SHOW_ADVANCED" != "1" ]] && ! schema_is_basic "$key"; then
			continue
		fi
		echo "$key"
	done
}

menu_section_screen() {
	local group="$1"
	while true; do
		echo >&2
		menu_bold "${MENU_GROUP_TITLE[$group]}" >&2
		echo >&2
		local -a keys=()
		mapfile -t keys < <(menu_section_keys "$group")
		local i=1 key
		for key in "${keys[@]}"; do
			local mark
			mark=$(menu_mark_for_key "$key")
			local shown
			if schema_is_secret "$key"; then
				shown=$([[ -n "${SECRETS[$key]:-}" ]] && echo set || echo "not set")
			else
				shown="${CONF[$key]:-}"
			fi
			printf '  %2d) %-28s = %s %s\n' "$i" "$key" "$shown" "$mark" >&2
			i=$((i + 1))
		done
		echo "  a) $([[ $MENU_SHOW_ADVANCED == 1 ]] && echo "hide" || echo "show") advanced   0) back (Enter too)   ?) help   q) quit" >&2
		local problems
		problems=$(menu_problems_count)
		if [[ "$problems" -gt 0 ]]; then
			menu_red "Problems: $problems" >&2
			echo >&2
		else
			echo "Problems: $problems" >&2
		fi
		local choice
		menu_read choice "> "
		menu_die_on_eof
		case "$choice" in
		"" | 0) return 0 ;;
		q) menu_quit_confirm && exit 0 ;;
		a)
			MENU_SHOW_ADVANCED=$((1 - MENU_SHOW_ADVANCED))
			continue
			;;
		'?')
			echo "  Number - edit a key; Enter/0 - back; a - show/hide advanced." >&2
			continue
			;;
		*)
			# 10#: "08" is eight, not a bad octal number, and "010" is ten.
			if [[ "$choice" =~ ^[0-9]+$ ]] && ((10#$choice >= 1 && 10#$choice <= ${#keys[@]})); then
				menu_edit_key "${keys[$((10#$choice - 1))]}"
			else
				echo "  unclear choice: $choice" >&2
			fi
			;;
		esac
	done
}

menu_quit_confirm() {
	[[ "$MENU_DIRTY" != "1" ]] && return 0
	local answer
	menu_read answer "There are unapplied edits. Leave without applying? [y/N] "
	[[ "$answer" =~ ^[yY] ]]
}

menu_panel_password_screen() {
	while true; do
		local p1 p2
		menu_read_secret p1 "Panel password (!cancel = leave without setting): "
		menu_die_on_eof
		[[ "$p1" == "!cancel" ]] && return 0
		if [[ -z "$p1" ]]; then
			echo "  an empty password is not accepted" >&2
			continue
		fi
		menu_read_secret p2 "Repeat the password: "
		if [[ "$p1" != "$p2" ]]; then
			echo "  the passwords do not match" >&2
			continue
		fi
		MENU_PANEL_PASSWORD="$p1"
		MENU_PANEL_PASSWORD_SET=1
		MENU_DIRTY=1
		return 0
	done
}

# menu_pick_bind - which address the web services listen on: this machine
# only (127.0.0.1 / all addresses in lan mode) or one of its own addresses.
menu_pick_bind() {
	local -a ifaces=() addrs=()
	local line n=0 answer
	while read -r line; do
		[[ -n "$line" ]] || continue
		ifaces+=("${line%% *}")
		addrs+=("${line#* }")
	done < <(access_local_addresses)
	((${#addrs[@]})) || return 0
	echo "  Listen address (BIND_ADDR):" >&2
	echo "    0) auto: 127.0.0.1 (this machine only), or every address in lan mode" >&2
	for n in "${!addrs[@]}"; do
		printf '    %d) %s on %s\n' "$((n + 1))" "${addrs[$n]}" "${ifaces[$n]}" >&2
	done
	menu_read answer "Listen address [number or address, Enter=${CONF[BIND_ADDR]}]: "
	[[ -n "$answer" ]] || return 0
	if [[ "$answer" =~ ^[0-9]+$ ]] && ((answer <= ${#addrs[@]})); then
		if ((answer == 0)); then answer="auto"; else answer="${addrs[$((answer - 1))]}"; fi
	fi
	local err
	if err=$(schema_validate_one BIND_ADDR "$answer"); then
		config_set_kv BIND_ADDR "$answer"
		MENU_DIRTY=1
	else
		echo "  $err" >&2
	fi
}

# menu_ask_yes_no <KEY> <question> - a yes/no question that sets KEY.
menu_ask_yes_no() {
	local key="$1" question="$2" answer
	menu_read answer "$question [y/n, Enter=${CONF[$key]/yes/y}]: "
	case "$answer" in
	y | Y | yes) config_set_kv "$key" yes && MENU_DIRTY=1 ;;
	n | N | no) config_set_kv "$key" no && MENU_DIRTY=1 ;;
	esac
}

# menu_pick_monitoring - the optional metrics stack: a storage (Prometheus or
# VictoriaMetrics), Grafana and node_exporter, each chosen on its own.
menu_pick_monitoring() {
	echo "  Metrics stack (each part is optional and chosen separately):" >&2
	local backend err
	menu_read backend "Metrics storage [none/victoriametrics/prometheus, Enter=${CONF[METRICS_BACKEND]}]: "
	if [[ -n "$backend" ]]; then
		if err=$(schema_validate_one METRICS_BACKEND "$backend"); then
			config_set_kv METRICS_BACKEND "$backend"
			MENU_DIRTY=1
		else
			echo "  $err" >&2
		fi
	fi
	menu_ask_yes_no GRAFANA_ENABLE "Install Grafana (dashboards)"
	menu_ask_yes_no NODE_EXPORTER_ENABLE "Install node_exporter (host metrics)"
}

# menu_quick_install - 5.1 "Quick install": interfaces (ip -o link,
# no lo, default-route one marked), Suricata source, access mode, which
# panel (full or lite), panel password; everything else keeps its default.
menu_quick_install() {
	echo >&2
	menu_bold "Quick install" >&2
	echo >&2
	local default_iface
	default_iface=$(ip -4 route show default 2>/dev/null | awk '/default/{for(i=1;i<=NF;i++) if($i=="dev") print $(i+1)}' | head -1)

	local -a ifaces=()
	while IFS= read -r line; do
		local name="${line#*: }"
		name="${name%%:*}"
		[[ -z "$name" || "$name" == "lo" ]] && continue
		ifaces+=("$name")
	done < <(ip -o link show 2>/dev/null)

	local i=1 name
	for name in "${ifaces[@]}"; do
		local tag=""
		[[ "$name" == "$default_iface" ]] && tag=" (default route)"
		echo "  $i) $name$tag" >&2
		i=$((i + 1))
	done
	local sel
	menu_read sel "Interfaces (numbers, comma separated): "
	local -a chosen=()
	local n
	IFS=',' read -ra sel_nums <<<"$sel"
	for n in "${sel_nums[@]}"; do
		n="${n// /}"
		[[ "$n" =~ ^[0-9]+$ ]] && ((10#$n >= 1 && 10#$n <= ${#ifaces[@]})) && chosen+=("${ifaces[$((10#$n - 1))]}")
	done
	if [[ "${#chosen[@]}" -gt 0 ]]; then
		local joined
		joined=$(
			IFS=,
			echo "${chosen[*]}"
		)
		config_set_kv IFACES "$joined"
		MENU_DIRTY=1
	fi

	local src
	menu_read src "Suricata source [source/oisf/distro, Enter=${CONF[SURICATA_SOURCE]}]: "
	if [[ -n "$src" ]]; then
		local err
		if err=$(schema_validate_one SURICATA_SOURCE "$src"); then
			config_set_kv SURICATA_SOURCE "$src"
			MENU_DIRTY=1
		else
			echo "  $err" >&2
		fi
	fi

	local mode
	menu_read mode "Access mode [localhost/lan/nginx, Enter=${CONF[ACCESS_MODE]}]: "
	if [[ -n "$mode" ]]; then
		local err2
		if err2=$(schema_validate_one ACCESS_MODE "$mode"); then
			config_set_kv ACCESS_MODE "$mode"
			MENU_DIRTY=1
		else
			echo "  $err2" >&2
		fi
	fi

	if [[ "${CONF[ACCESS_MODE]}" != "nginx" ]]; then
		menu_pick_bind
	fi

	menu_pick_monitoring

	echo "  Panel: full (rich design, effects) or lite (same features, plain light page)" >&2
	local edition
	menu_read edition "Panel [full/lite, Enter=${CONF[PANEL_EDITION]}]: "
	if [[ -n "$edition" ]]; then
		local err3
		if err3=$(schema_validate_one PANEL_EDITION "$edition"); then
			config_set_kv PANEL_EDITION "$edition"
			MENU_DIRTY=1
		else
			echo "  $err3" >&2
		fi
	fi

	menu_panel_password_screen
	menu_draft_save
}

menu_check_system_screen() {
	local reasons
	reasons=$(step_preflight_reasons)
	echo >&2
	if [[ -z "$reasons" ]]; then
		echo "preflight: no remarks" >&2
	else
		echo "preflight:" >&2
		echo "  ${reasons//$'\n'/$'\n  '}" >&2
	fi
	local _enter
	menu_read _enter "Enter to continue"
}

menu_plan_screen() {
	echo >&2
	run_plan >&2
	local _enter
	menu_read _enter "Enter to continue"
}

menu_save_to_file_screen() {
	local path
	menu_read path "File path (Enter = cancel): "
	[[ -z "$path" ]] && return 0
	# Only an existing file is at risk: ask before overwriting it.
	if [[ -e "$path" ]]; then
		menu_confirm "$path exists. Overwrite it?" n || return 0
	fi
	config_write_conf "$path"
	echo "  saved to $path" >&2
}

menu_load_from_file_screen() {
	local path
	menu_read path "File path (Enter = cancel): "
	[[ -z "$path" ]] && return 0
	[[ -f "$path" ]] || {
		echo "  file not found" >&2
		return 0
	}
	config_load_kv_file "$path"
	local errs
	errs=$(config_validate)
	if [[ -n "$errs" ]]; then
		echo "  the loaded file has errors:" >&2
		echo "  $errs" >&2
	fi
	MENU_DIRTY=1
	menu_draft_save
}

# ------------------------------------------------------------------
# Choosing components (v0.25.0): every part is switched on or off on its
# own. A switched-off part is skipped by the installer; what is already
# installed stays (removing is `uninstall`).
# ------------------------------------------------------------------
MENU_COMPONENTS=(
	"SURICATA_ENABLE|Suricata (IDS/IPS engine)"
	"NDPI_ENABLE|   with the nDPI plugin"
	"RULES_ENABLE|Rules and their update"
	"EVEBOX_ENABLE|EveBox (alert viewer)"
	"NTOPNG_ENABLE|ntopng with Redis (traffic monitor)"
	"PANEL_ENABLE|Control panel"
	"WATCH_ENABLE|Watchdog"
	"GRAFANA_ENABLE|Grafana (dashboards)"
	"NODE_EXPORTER_ENABLE|node_exporter (host metrics)"
)

menu_toggle_component() {
	local key="$1" label="$2" cur new extra=""
	label="${label#"${label%%[![:space:]]*}"}"
	cur="${CONF[$key]:-yes}"
	if [[ "$cur" == "yes" ]]; then new=no; else new=yes; fi
	if [[ "$new" == "yes" && ("$key" == "NDPI_ENABLE" || "$key" == "RULES_ENABLE") &&
		"${CONF[SURICATA_ENABLE]:-yes}" == "no" ]]; then
		echo "  $label works only together with Suricata (Suricata with the nDPI plugin): switch Suricata on first" >&2
		return 0
	fi
	if [[ "$key" == "NDPI_ENABLE" && "$new" == "yes" && "${CONF[SURICATA_RUNTIME]:-native}" == "docker" ]]; then
		echo "  the nDPI plugin is not in the Suricata docker image: set SURICATA_RUNTIME=native first" >&2
		return 0
	fi
	if [[ "$key" == "SURICATA_ENABLE" && "$new" == "no" ]]; then
		extra=" (nDPI and the rules go off with it)"
	fi
	[[ -n "$extra" ]] && echo "  note:$extra" >&2
	config_set_kv "$key" "$new"
	if [[ "$key" == "SURICATA_ENABLE" && "$new" == "no" ]]; then
		config_set_kv NDPI_ENABLE no
		config_set_kv RULES_ENABLE no
	fi
	[[ "$new" == "no" ]] && echo "  note: anything already installed stays; use uninstall to remove it" >&2
	MENU_DIRTY=1
	menu_draft_save
}

menu_components_screen() {
	while true; do
		echo >&2
		menu_bold "Choose components" >&2
		echo >&2
		local i=1 row key label
		for row in "${MENU_COMPONENTS[@]}"; do
			key="${row%%|*}"
			label="${row#*|}"
			printf '  %2d) [%s] %s\n' "$i" "$([[ ${CONF[$key]:-yes} == yes ]] && echo x || echo ' ')" "$label" >&2
			i=$((i + 1))
		done
		printf '  %2d) %-34s %s\n' "$i" "Metrics storage" "${CONF[METRICS_BACKEND]:-none}" >&2
		echo >&2
		echo "  Number - switch on/off (asks first)   s) all settings of the components" >&2
		echo "  0) back (Enter too)   ?) help   q) quit" >&2
		local choice
		menu_read choice "> "
		menu_die_on_eof
		case "$choice" in
		"" | 0) return 0 ;;
		q) menu_quit_confirm && {
			menu_close_input
			exit 0
		} ;;
		s) menu_section_screen components ;;
		'?') echo "  Each part is chosen on its own; unchecked parts are skipped by the installer." >&2 ;;
		*)
			if [[ "$choice" =~ ^[0-9]+$ ]] && ((10#$choice >= 1 && 10#$choice <= ${#MENU_COMPONENTS[@]})); then
				row="${MENU_COMPONENTS[$((10#$choice - 1))]}"
				menu_toggle_component "${row%%|*}" "${row#*|}"
			elif [[ "$choice" =~ ^[0-9]+$ ]] && ((10#$choice == ${#MENU_COMPONENTS[@]} + 1)); then
				menu_edit_key METRICS_BACKEND
			else
				echo "  unclear choice: $choice" >&2
			fi
			;;
		esac
	done
}

# ------------------------------------------------------------------
# Guided setup (v0.25.0): asks every setting that applies to the chosen
# components, group by group. Enter keeps the value, - resets to the
# default, s skips the rest of the group, x leaves the guided setup.
# ------------------------------------------------------------------

# menu_key_skipped <KEY> - 0 when the key does not apply to the config as it is.
menu_key_skipped() {
	local k="$1" y=yes n=no
	local suri="${CONF[SURICATA_ENABLE]:-yes}"
	case "$k" in
	METRICS_TOKEN) return 0 ;;
	SURICATA_RUNTIME | SURICATA_SOURCE | SURICATA_VERSION | SURICATA_MODE | IFACES | BPF_FILTER | HOME_NET | \
		EVE_SYSLOG | EVE_REDIS | EVE_ROTATE | EVE_KEEP | EVE_MAX_SIZE_MB | STATS_INTERVAL_SEC | TEST_*)
		[[ "$suri" == "$n" ]] && return 0
		;;
	IPS_METHOD | IPS_NFQ_CHAINS)
		[[ "$suri" == "$n" || "${CONF[SURICATA_MODE]:-ids}" != "ips" ]] && return 0
		;;
	NDPI_ENABLE) [[ "$suri" == "$n" ]] && return 0 ;;
	NDPI_SOURCE | NDPI_VERSION) [[ "$suri" == "$n" || "${CONF[NDPI_ENABLE]:-yes}" == "$n" ]] && return 0 ;;
	RULES_ENABLE) [[ "$suri" == "$n" ]] && return 0 ;;
	RULES_*) [[ "$suri" == "$n" || "${CONF[RULES_ENABLE]:-yes}" == "$n" ]] && return 0 ;;
	EVEBOX_ENABLE) ;;
	EVEBOX_ES_URL) [[ "${CONF[EVEBOX_ENABLE]:-yes}" == "$n" || "${CONF[EVEBOX_DB]:-sqlite}" != "elasticsearch" ]] && return 0 ;;
	EVEBOX_*) [[ "${CONF[EVEBOX_ENABLE]:-yes}" == "$n" ]] && return 0 ;;
	NTOPNG_ENABLE) ;;
	NTOPNG_*) [[ "${CONF[NTOPNG_ENABLE]:-yes}" == "$n" ]] && return 0 ;;
	PANEL_ENABLE) ;;
	PANEL_* | METRICS_EXPORT) [[ "${CONF[PANEL_ENABLE]:-yes}" == "$n" ]] && return 0 ;;
	LAN_CIDR) [[ "${CONF[ACCESS_MODE]:-localhost}" != "lan" ]] && return 0 ;;
	NGINX_MANAGE | NGINX_TLS) [[ "${CONF[ACCESS_MODE]:-localhost}" != "nginx" ]] && return 0 ;;
	NGINX_CERT | NGINX_KEY) [[ "${CONF[ACCESS_MODE]:-localhost}" != "nginx" || "${CONF[NGINX_TLS]:-none}" != "existing" ]] && return 0 ;;
	METRICS_BACKEND_RUNTIME | METRICS_BACKEND_PORT | METRICS_RETENTION) [[ "${CONF[METRICS_BACKEND]:-none}" == "none" ]] && return 0 ;;
	NODE_EXPORTER_ENABLE | GRAFANA_ENABLE | WATCH_ENABLE | METRICS_BACKEND) ;;
	NODE_EXPORTER_*) [[ "${CONF[NODE_EXPORTER_ENABLE]:-no}" == "$n" ]] && return 0 ;;
	GRAFANA_*) [[ "${CONF[GRAFANA_ENABLE]:-no}" == "$n" ]] && return 0 ;;
	ALERT_TG_*) [[ "${CONF[WATCH_ENABLE]:-yes}" == "$n" || ",${CONF[ALERT_CHANNELS]:-}," != *",tg,"* ]] && return 0 ;;
	ALERT_MAIL_* | ALERT_SMTP_URL) [[ "${CONF[WATCH_ENABLE]:-yes}" == "$n" || ",${CONF[ALERT_CHANNELS]:-}," != *",mail,"* ]] && return 0 ;;
	WATCH_* | ALERT_*) [[ "${CONF[WATCH_ENABLE]:-yes}" == "$n" ]] && return 0 ;;
	esac
	: "$y"
	return 1
}

# menu_key_is_component <KEY> - 0 for a switch of the component screen; the
# guided setup has asked these there already.
menu_key_is_component() {
	local row
	for row in "${MENU_COMPONENTS[@]}"; do
		[[ "${row%%|*}" == "$1" ]] && return 0
	done
	return 1
}

# menu_wizard_ask <KEY> -> 0 go on, 10 skip the group, 11 leave the wizard.
menu_wizard_ask() {
	local key="$1" answer err
	while true; do
		local shown="${CONF[$key]:-}"
		schema_is_secret "$key" && shown=$([[ -n "${SECRETS[$key]:-}" ]] && echo set || echo "not set")
		echo >&2
		echo "$key (now: ${shown:-<empty>}, default: ${SCHEMA_DEFAULT[$key]:-<empty>})" >&2
		[[ -n "${SCHEMA_OPTIONS[$key]}" ]] && echo "  options: ${SCHEMA_OPTIONS[$key]}" >&2
		if schema_is_secret "$key"; then
			menu_read_secret answer "  value (Enter keeps, - default, s skip group, x leave setup, ? help): "
		else
			menu_read answer "  value (Enter keeps, - default, s skip group, x leave setup, ? help): "
		fi
		menu_die_on_eof
		case "$answer" in
		"") return 0 ;;
		s) return 10 ;;
		x) return 11 ;;
		'?')
			echo "  group ${SCHEMA_GROUP[$key]}, type ${SCHEMA_TYPE[$key]}, level ${SCHEMA_LEVEL[$key]}" >&2
			;;
		-)
			config_set_kv "$key" "${SCHEMA_DEFAULT[$key]}"
			MENU_DIRTY=1
			menu_draft_save
			return 0
			;;
		*)
			if err=$(schema_validate_one "$key" "$answer"); then
				config_set_kv "$key" "$answer"
				menu_reconcile_conflicts
				MENU_DIRTY=1
				menu_draft_save
				return 0
			fi
			echo "  $err" >&2
			;;
		esac
	done
}

menu_wizard() {
	echo >&2
	menu_bold "Guided setup" >&2
	echo >&2
	echo "  Every setting is asked, group by group. Settings of parts you switched off are skipped." >&2
	menu_components_screen
	local g key rc
	for g in "${MENU_GROUPS[@]}"; do
		echo >&2
		menu_bold "== ${MENU_GROUP_TITLE[$g]} ==" >&2
		echo >&2
		for key in "${SCHEMA_KEYS[@]}"; do
			[[ "${SCHEMA_GROUP[$key]}" == "$g" ]] || continue
			menu_key_is_component "$key" && continue
			menu_key_skipped "$key" && continue
			menu_wizard_ask "$key"
			rc=$?
			((rc == 10)) && break
			# x: the answers so far are kept, so there is nothing to confirm
			((rc == 11)) && return 0
		done
	done
	if [[ "$MENU_PANEL_PASSWORD_SET" != "1" ]] && menu_confirm "Set the panel password now?"; then
		menu_panel_password_screen
	fi
	menu_draft_save
}

# menu_main_screen -> 0 (user chose "Install") or exits the process.
menu_main_screen() {
	while true; do
		echo >&2
		echo "$(menu_bold "dpistack v${DPISTACK_VERSION}") | $OS_ID ${OS_VERSION_ID:-}, $(uname -m) | systemd: $(command -v systemctl >/dev/null && echo yes || echo no)" >&2
		echo "Install. Config: $(path_conf) (not created)" >&2
		echo >&2
		echo "  1) Quick install" >&2
		local i=2 g
		for g in "${MENU_GROUPS[@]}"; do
			printf '  %2d) %-30s %s\n' "$i" "${MENU_GROUP_TITLE[$g]}" "$(menu_group_summary "$g")" >&2
			i=$((i + 1))
		done
		printf '  %2d) %-30s %s\n' "$i" "Panel password" "$([[ $MENU_PANEL_PASSWORD_SET == 1 ]] && echo "set" || echo "not set")" >&2
		echo >&2
		echo "  m) Choose components   w) Guided setup (asks every setting)" >&2
		echo "  c) Check the system   p) Plan   s) Save to file   l) Load from file" >&2
		echo "  i) Install             q) Quit" >&2
		local problems
		problems=$(menu_problems_count)
		echo >&2
		if [[ "$problems" -gt 0 ]]; then
			menu_red "Problems ($problems): $(menu_problems | head -1)" >&2
			echo >&2
		else
			echo "Problems ($problems)" >&2
		fi
		local choice
		menu_read choice "> "
		menu_die_on_eof
		case "$choice" in
		1) menu_quick_install ;;
		m) menu_components_screen ;;
		w) menu_wizard ;;
		c) menu_check_system_screen ;;
		p) menu_plan_screen ;;
		s) menu_save_to_file_screen ;;
		l) menu_load_from_file_screen ;;
		q) menu_quit_confirm && {
			menu_close_input
			exit 0
		} ;;
		i)
			if [[ "$problems" != "0" ]]; then
				echo "  cannot install while there are problems" >&2
				continue
			fi
			if [[ "$MENU_PANEL_PASSWORD_SET" != "1" ]]; then
				echo "  installation is unavailable without a panel password" >&2
				continue
			fi
			# A busy port is a warning with a choice here, not a stop later.
			preflight_resolve_ports_interactive || true
			return 0
			;;
		*)
			# Only a number goes into the arithmetic: "zz" there is a bash
			# error that ends the whole menu.
			local idx=0
			[[ "$choice" =~ ^[0-9]+$ ]] && idx=$((10#$choice - 1))
			if [[ "$choice" =~ ^[0-9]+$ && "$idx" -ge 1 && "$idx" -le "${#MENU_GROUPS[@]}" ]]; then
				menu_section_screen "${MENU_GROUPS[$((idx - 1))]}"
			elif [[ "$choice" == "$((${#MENU_GROUPS[@]} + 2))" ]]; then
				menu_panel_password_screen
			else
				echo "  unclear choice: $choice" >&2
			fi
			;;
		esac
	done
}

menu_found_install_screen() {
	local finished=1 apply_label="Apply the current config again"
	state_install_finished || finished=0
	((finished)) || apply_label="Install with the saved config"
	while true; do
		echo >&2
		if ((finished)); then
			menu_bold "dpistack v${DPISTACK_VERSION} | Installation found" >&2
		else
			menu_bold "dpistack v${DPISTACK_VERSION} | Saved config found, the install did not finish" >&2
		fi
		echo >&2
		echo "  1) Configure   2) ${apply_label}   3) Control menu   4) Uninstall   5) Quit" >&2
		local choice
		menu_read choice "> "
		menu_die_on_eof
		case "$choice" in
		1) return 10 ;; # caller switches to the reconfigure menu
		2) return 11 ;; # idempotent re-apply, no questions
		3) return 12 ;; # caller opens the management menu
		4) return 13 ;; # caller asks and removes
		5 | q)
			menu_close_input
			exit 0
			;;
		*) echo "  unclear choice: $choice" >&2 ;;
		esac
	done
}

# menu_run_install - entry point for `install.sh install` without -y.
# Returns 0 once the user chose "Install"; the caller continues
# into the normal validate/summary/preflight/apply pipeline (5.1 item
# 1 onward), the same code -y runs directly.
menu_run_install() {
	menu_open_input

	if [[ -f "$(path_conf)" ]]; then
		menu_found_install_screen
		local rc=$?
		if [[ "$rc" == "11" ]]; then
			NON_INTERACTIVE=1 # "apply current config again" asks nothing
			menu_close_input
			return 0
		fi
		if [[ "$rc" == "12" ]]; then
			menu_run_manage
			exit 0
		fi
		if [[ "$rc" == "13" ]]; then
			menu_manage_uninstall || true
			menu_close_input
			exit 0
		fi
		# rc=10 (configure) falls through to the reconfigure menu below.
	elif [[ -f "$(path_conf_draft)" ]]; then
		local answer
		menu_read answer "Continue the draft? [Y/n] "
		if [[ "$answer" =~ ^[nN] ]]; then
			menu_draft_delete
			config_reset
			config_load_defaults
			config_apply_env_secrets
		else
			config_load_kv_file "$(path_conf_draft)"
		fi
	fi

	if [[ -f "$(path_conf)" ]]; then
		for key in "${!CONF[@]}"; do MENU_OLD_CONF[$key]="${CONF[$key]}"; done
		menu_reconfigure_screen
	else
		if [[ "${MENU_FAST:-0}" == "1" ]]; then
			menu_quick_install
		elif [[ "${DPISTACK_MENU_ASSUME_YES:-0}" != "1" ]] && menu_confirm "Run the guided setup first (asks every setting, you can leave at any time)?"; then
			menu_wizard
		fi
		menu_main_screen
	fi

	menu_draft_delete
	menu_close_input
	return 0
}

# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure
MENU_ALREADY_CONFIRMED=0

# menu_reconfigure_confirm_and_validate - runs entirely inside the
# menu's own input loop (fd 8), so it never needs cmd_reconfigure to
# reread DPISTACK_INPUT afterwards. Returns 1 (stay in the menu) on
# "no changes", a declined heavy confirmation, or a failed suricata -T;
# only a real go-ahead returns 0.
menu_reconfigure_confirm_and_validate() {
	config_diff_and_steps "$(path_conf)" >/dev/null
	if [[ "$CONFIG_CHANGE_WEIGHT" == "none" ]]; then
		echo "  no changes" >&2
		return 1
	fi

	if [[ "$CONFIG_CHANGE_WEIGHT" == "heavy" ]]; then
		echo "  Heavy changes will affect the steps: ${CONFIG_AFFECTED_STEPS[*]}" >&2
		local answer
		menu_read answer "  Continue? [y/N] "
		menu_die_on_eof
		if [[ ! "$answer" =~ ^[yY] ]]; then
			echo "  cancelled" >&2
			return 1
		fi
	fi

	local step
	for step in "${CONFIG_AFFECTED_STEPS[@]}"; do
		if [[ "$step" == "suricata" ]]; then
			if ! suricata_validate_render "$(suricata_render_yaml)"; then
				echo "  suricata -T failed on the new suricata.yaml, the edits stay in the menu (see the output above)" >&2
				return 1
			fi
		fi
	done

	# shellcheck disable=SC2034 # read by install.sh's cmd_reconfigure
	MENU_ALREADY_CONFIRMED=1
	return 0
}

menu_diff_screen() {
	echo >&2
	config_diff_and_steps "$(path_conf)" >&2
	local _enter
	menu_read _enter "Enter to continue"
}

# menu_reconfigure_screen - 5.3's section screen. `0) Back` only makes
# sense when opened from the control menu (not built until slice 15),
# so a direct `dpistack reconfigure` behaves like `q` there, per spec.
menu_reconfigure_screen() {
	while true; do
		echo >&2
		menu_bold "dpistack v${DPISTACK_VERSION}" >&2
		echo " | Configuring an existing installation" >&2
		echo "Config: $(path_conf)" >&2
		echo >&2
		local i=1 g
		for g in "${MENU_GROUPS[@]}"; do
			printf '  %2d) %-30s %s\n' "$i" "${MENU_GROUP_TITLE[$g]}" "$(menu_group_summary "$g")" >&2
			i=$((i + 1))
		done
		printf '  %2d) %-30s %s\n' "$i" "Panel password" "change" >&2
		echo >&2
		echo "  m) Choose components   w) Guided setup (asks every setting)" >&2
		echo "  d) Changes (diff)   a) Apply   r) Discard edits" >&2
		echo "  s) Save to file   l) Load from file   q) Quit$([[ "$MENU_BACK_ENABLED" == "1" ]] && echo "   b) Back")" >&2
		local changed=0 key
		for key in "${!CONF[@]}"; do
			[[ "${CONF[$key]}" != "${MENU_OLD_CONF[$key]:-}" ]] && changed=$((changed + 1))
		done
		local rc_problems
		rc_problems=$(menu_problems_count)
		if [[ "$rc_problems" -gt 0 ]]; then
			echo "Edits: $changed key(s). $(menu_red "Problems: $rc_problems")" >&2
		else
			echo "Edits: $changed key(s). Problems: $rc_problems" >&2
		fi
		local choice
		menu_read choice "> "
		menu_die_on_eof
		case "$choice" in
		m) menu_components_screen ;;
		w) menu_wizard ;;
		d) menu_diff_screen ;;
		a)
			preflight_resolve_ports_interactive || true
			if menu_reconfigure_confirm_and_validate; then
				return 0 # caller writes config.sh and applies the affected steps
			fi
			;;
		r)
			local answer
			menu_read answer "Discard all unapplied edits? [y/N] "
			if [[ "$answer" =~ ^[yY] ]]; then
				# shellcheck disable=SC2004 # CONF is associative (config.sh); $key is required, not arithmetic noise
				for key in "${!MENU_OLD_CONF[@]}"; do CONF[$key]="${MENU_OLD_CONF[$key]}"; done
				MENU_DIRTY=0
				menu_draft_delete
			fi
			;;
		s) menu_save_to_file_screen ;;
		l) menu_load_from_file_screen ;;
		b)
			if [[ "$MENU_BACK_ENABLED" == "1" ]]; then
				return 20
			fi
			echo "  unclear choice: $choice" >&2
			;;
		q) menu_quit_confirm && {
			menu_close_input
			exit 0
		} ;;
		*)
			local idx=0
			[[ "$choice" =~ ^[0-9]+$ ]] && idx=$((10#$choice))
			if [[ "$choice" =~ ^[0-9]+$ && "$idx" -ge 1 && "$idx" -le "${#MENU_GROUPS[@]}" ]]; then
				menu_section_screen "${MENU_GROUPS[$((idx - 1))]}"
			elif [[ "$choice" == "$((${#MENU_GROUPS[@]} + 1))" ]]; then
				menu_panel_password_screen
			else
				echo "  unclear choice: $choice" >&2
			fi
			;;
		esac
	done
}

# menu_run_reconfigure - entry point for `install.sh reconfigure`
# without -y. Returns 0 once the user chose "Apply".
menu_run_reconfigure() {
	menu_open_input
	for key in "${!CONF[@]}"; do MENU_OLD_CONF[$key]="${CONF[$key]}"; done
	menu_reconfigure_screen
	local rc=$?
	menu_draft_delete
	menu_close_input
	return "$rc"
}

# ------------------------------------------------------------------
# Management menu (tech.md 5.2): `dpistack` with an installed config.
# Each action runs in a subshell, so its lock and `exit` calls end with
# the action and the menu carries on.
# ------------------------------------------------------------------

# shellcheck disable=SC2034 # read by menu_reconfigure_screen
MENU_BACK_ENABLED=0
MANAGE_COMPONENTS=(suricata evebox ntopng redis panel victoriametrics prometheus node_exporter grafana)

# manage_ctl - the installed dpistack, or the install.sh next to this file
# when run from a clone (the verbs are the same).
manage_ctl() {
	# DPISTACK_BIN names another program that answers the verbs (tests).
	if [[ -n "${DPISTACK_BIN:-}" && -x "$DPISTACK_BIN" ]]; then
		echo "$DPISTACK_BIN"
		return 0
	fi
	if [[ -x "$(path_ctl_bin)" ]]; then
		path_ctl_bin
	elif [[ -x "$SCRIPT_DIR/install.sh" ]]; then
		echo "$SCRIPT_DIR/install.sh"
	else
		return 1
	fi
}

# menu_manage_ctl <args...> - runs a dpistack verb; an absent or failing
# helper prints the reason and leaves the menu running.
menu_manage_ctl() {
	local ctl rc
	if ! ctl=$(manage_ctl); then
		echo "  dpistack not found, check the installation (the selfinstall step)" >&2
		return 1
	fi
	"$ctl" "$@"
	rc=$?
	((rc == 0)) || echo "  dpistack returned code $rc" >&2
	return "$rc"
}

menu_manage_summary() {
	local ctl out active total health="no data"
	if ctl=$(manage_ctl) && out=$("$ctl" status --json 2>/dev/null) && command -v jq >/dev/null 2>&1; then
		total=$(jq '[.components[] | select(.state != "absent")] | length' <<<"$out" 2>/dev/null)
		active=$(jq '[.components[] | select(.state == "active")] | length' <<<"$out" 2>/dev/null)
		printf 'components: %s of %s active' "${active:-?}" "${total:-?}"
	else
		printf 'components: no data'
	fi
	if [[ -f "$(path_health_json)" ]] && command -v jq >/dev/null 2>&1; then
		health=$(jq -r '.overall // "no data"' "$(path_health_json)" 2>/dev/null)
	fi
	printf '  |  health: %s' "$health"
}

menu_manage_logs() {
	local i=1 id choice
	for id in "${MANAGE_COMPONENTS[@]}"; do
		printf '  %d) %s\n' "$i" "$id" >&2
		i=$((i + 1))
	done
	menu_read choice "Component (number, Enter - back): "
	menu_die_on_eof
	[[ "$choice" =~ ^[0-9]+$ ]] || return 0
	((10#$choice >= 1 && 10#$choice <= ${#MANAGE_COMPONENTS[@]})) || {
		echo "  no such number" >&2
		return 0
	}
	id="${MANAGE_COMPONENTS[$((10#$choice - 1))]}"
	menu_manage_ctl logs "$id" -n 200
	menu_read choice "f - follow the log (Ctrl+C - exit), Enter - back: "
	if [[ "$choice" == "f" ]]; then
		# A no-op handler, not "ignore": the child keeps the default
		# Ctrl+C and stops, the menu itself stays.
		trap 'true' INT
		menu_manage_ctl logs "$id" -n 200 --follow
		trap 'menu_on_interrupt' INT
	fi
}

menu_manage_tests() {
	local ctl out rc
	ctl=$(manage_ctl) || {
		echo "  dpistack not found, check the installation (the selfinstall step)" >&2
		return 1
	}
	out=$("$ctl" test all --json 2>&1)
	rc=$?
	if command -v jq >/dev/null 2>&1 && jq -e . >/dev/null 2>&1 <<<"$out"; then
		jq -r '.[] | "  \(.name): \(.status) (\(.duration_ms) ms) - \(.detail)"' <<<"$out"
	else
		printf '%s\n' "$out" >&2
	fi
	((rc == 0)) || echo "  some tests failed (code $rc)" >&2
}

menu_manage_password() {
	local p1 p2 ctl
	menu_read_secret p1 "New panel password: "
	menu_die_on_eof
	[[ -n "$p1" ]] || {
		echo "  an empty password is not accepted" >&2
		return 0
	}
	menu_read_secret p2 "Repeat the password: "
	if [[ "$p1" != "$p2" ]]; then
		echo "  the passwords do not match, nothing changed" >&2
		return 0
	fi
	ctl=$(manage_ctl) || {
		echo "  dpistack not found, check the installation (the selfinstall step)" >&2
		return 1
	}
	printf '%s\n' "$p1" | "$ctl" panel-passwd
}

# menu_manage_uninstall - returns 0 only when the stack was removed.
menu_manage_uninstall() {
	local word mode
	menu_read word "Type the word \"remove\" to confirm (Enter = cancel): "
	menu_die_on_eof
	if [[ "$word" != "remove" ]]; then
		echo "  cancelled" >&2
		return 1
	fi
	echo "  1) normal removal   2) removal with data (--purge)" >&2
	menu_read mode "> "
	case "$mode" in
	1) (cmd_uninstall) ;;
	2) (PURGE=1 cmd_uninstall) ;;
	*)
		echo "  cancelled" >&2
		return 1
		;;
	esac
}

menu_run_manage() {
	menu_open_input
	local choice rc answer
	while true; do
		echo >&2
		echo "$(menu_bold "dpistack v${DPISTACK_VERSION}")  |  Managing the installed stand" >&2
		echo "Config: $(path_conf)  |  $(menu_manage_summary)" >&2
		echo >&2
		echo "  1) Configure                     config sections, diff, apply" >&2
		echo "  2) Component status" >&2
		echo "  3) Logs" >&2
		echo "  4) Run tests" >&2
		echo "  5) Upgrade packages" >&2
		echo "  6) Uninstall" >&2
		echo "  7) Panel password" >&2
		echo >&2
		echo "  q) Quit" >&2
		menu_read choice "> "
		menu_die_on_eof
		case "$choice" in
		1)
			(
				MENU_BACK_ENABLED=1
				cmd_reconfigure
			)
			rc=$?
			((rc == 0)) || echo "  configuration finished with code $rc" >&2
			;;
		2) menu_manage_ctl status ;;
		3) menu_manage_logs ;;
		4) menu_manage_tests ;;
		5)
			menu_read answer "Upgrade packages? [y/N] "
			if [[ "$answer" =~ ^[yY] ]]; then
				(cmd_upgrade) || echo "  upgrade failed" >&2
			fi
			;;
		6)
			if menu_manage_uninstall; then
				menu_close_input
				return 0
			fi
			;;
		7) menu_manage_password ;;
		q | Q)
			menu_close_input
			return 0
			;;
		*) echo "  unclear choice: $choice" >&2 ;;
		esac
	done
}
DPISTACK_BUNDLE_END
put lib/os.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# OS detection and package-manager wrappers. Steps call pkg_install,
# never apt-get/dnf directly (tech.md section 3).

OS_ID=""
OS_ID_LIKE=""
OS_VERSION_ID=""
OS_FAMILY=""

# Family for a given (id, id_like) pair. ID wins; ID_LIKE is consulted
# for derivatives that do not use their upstream name as ID (tests
# exercise this through stub os-release files).
os_family_for() {
	local id="$1" id_like="$2"
	case " $id $id_like " in
	*" ubuntu "* | *" debian "*)
		echo "apt"
		return
		;;
	*" fedora "* | *" rhel "* | *" centos "*)
		echo "dnf"
		return
		;;
	*" opensuse"* | *" suse "* | *" sles "* | *" sled "*)
		echo "zypper"
		return
		;;
	*" arch "* | *" archlinux "* | *" manjaro "* | *" endeavouros "*)
		echo "pacman"
		return
		;;
	esac
	# Any other Linux: no package manager of its own is driven. Components
	# run in Docker, the installer needs systemd and a few base tools.
	echo "generic"
}

os_detect() {
	local f
	f=$(path_os_release)
	if [[ ! -r "$f" ]]; then
		die 3 "cannot read $f, unsupported or broken system"
	fi

	# shellcheck disable=SC1090
	OS_ID=$(. "$f" && echo "${ID:-}")
	# shellcheck disable=SC1090
	OS_ID_LIKE=$(. "$f" && echo "${ID_LIKE:-}")
	# shellcheck disable=SC1090
	OS_VERSION_ID=$(. "$f" && echo "${VERSION_ID:-}")

	OS_FAMILY=$(os_family_for "$OS_ID" "$OS_ID_LIKE")

	# dpistack manages its services as systemd units, on every family.
	if [[ "$OS_FAMILY" == "generic" && ! -d "$(path_systemd_marker)" ]]; then
		die 3 "$OS_ID: systemd is needed (no $(path_systemd_marker)); dpistack does not work on systems with another init"
	fi

	log "INFO" "detected $OS_ID $OS_VERSION_ID, family=$OS_FAMILY"
	# apt must never stop on a debconf or needrestart question: the
	# installer may run with no terminal (-y, a timer, a pipe).
	if [[ "$OS_FAMILY" == "apt" ]]; then
		export DEBIAN_FRONTEND=noninteractive NEEDRESTART_MODE=a
	fi
	# Package and unit names that differ between the families.
	if [[ "$OS_FAMILY" == "dnf" ]]; then
		# These are read by step_ndpi.sh and step_redis.sh.
		# shellcheck disable=SC2034
		NDPI_PACKAGE="ndpi-devel"
		# shellcheck disable=SC2034
		REDIS_PACKAGE="redis"
		# shellcheck disable=SC2034
		REDIS_UNIT="redis.service"
	fi
}

pkg_install() {
	# pkg_install <package...>
	case "$OS_FAMILY" in
	apt)
		run apt-get install -y "$@"
		;;
	dnf)
		run dnf install -y "$@"
		;;
	zypper)
		run zypper --non-interactive install --no-recommends "$@"
		;;
	pacman)
		run pacman -S --noconfirm --needed "$@"
		;;
	generic)
		echo "$OS_ID: the installer does not install packages on this distribution; install them by hand: $*" >&2
		return 1
		;;
	*)
		die 3 "pkg_install called before os_detect (family=$OS_FAMILY)"
		;;
	esac
}

# pkg_spec <package> [version] - the argument that pins a package to a
# version (NTOPNG_VERSION, EVEBOX_VERSION); no version means the latest.
pkg_spec() {
	local pkg="$1" version="${2:-}"
	if [[ -z "$version" ]]; then
		echo "$pkg"
		return
	fi
	case "$OS_FAMILY" in
	apt) echo "${pkg}=${version}" ;;
	dnf) echo "${pkg}-${version}" ;;
	*) echo "$pkg" ;;
	esac
}

# The OISF COPR series that matches SURICATA_STABLE_REF.
SURICATA_COPR="@oisf/suricata-8.0"

pkg_repo_add() {
	# pkg_repo_add <name>
	# Only "oisf" exists as a named repo (tech.md 4.3 SURICATA_SOURCE=oisf):
	# the OISF PPA on Ubuntu, the OISF COPR on the RHEL family and Fedora.
	local name="$1"
	case "$OS_FAMILY:$name" in
	apt:oisf)
		run add-apt-repository -y ppa:oisf/suricata-stable
		run apt-get update
		;;
	dnf:oisf)
		pkg_install dnf-plugins-core || return 1
		run dnf copr enable -y "$SURICATA_COPR" || return 1
		run dnf -y makecache
		;;
	*)
		die 3 "pkg_repo_add: unknown combination family=$OS_FAMILY repo=$name"
		;;
	esac
}

pkg_pin() {
	# pkg_pin <package>
	case "$OS_FAMILY" in
	apt)
		run apt-mark hold "$1"
		;;
	dnf)
		pkg_install python3-dnf-plugin-versionlock || return 1
		run dnf versionlock add "$1"
		;;
	zypper)
		run zypper --non-interactive addlock "$1"
		;;
	*)
		echo "$OS_ID: pinning the version of package $1 is not supported here (PIN_VERSIONS skipped)" >&2
		;;
	esac
}

# pkg_installed_version <package> - the installed version, empty (and rc 1)
# when the package is not installed.
pkg_installed_version() {
	local out
	case "$OS_FAMILY" in
	apt) out=$(dpkg-query -W -f='${Version}' "$1" 2>/dev/null) || return 1 ;;
	dnf | zypper) out=$(rpm -q --qf '%{VERSION}-%{RELEASE}' "$1" 2>/dev/null) || return 1 ;;
	pacman) out=$(pacman -Q "$1" 2>/dev/null | awk '{print $2}') && [[ -n "$out" ]] || return 1 ;;
	*) return 1 ;;
	esac
	printf '%s' "$out"
}

# pkg_upgrade <package...> - upgrade only what is already installed.
pkg_upgrade() {
	case "$OS_FAMILY" in
	apt) run apt-get install --only-upgrade -y "$@" ;;
	dnf) run dnf upgrade -y "$@" ;;
	zypper) run zypper --non-interactive update "$@" ;;
	pacman) run pacman -S --noconfirm --needed "$@" ;;
	*) return 1 ;;
	esac
}

# One package index refresh per run, before the first install: a fresh
# image has no lists and apt-get install cannot find anything.
# Repository steps still refresh again after they add a source.
PKG_INDEX_FRESH=0
pkg_update_once() {
	[[ "$PKG_INDEX_FRESH" == "1" ]] && return 0
	case "$OS_FAMILY" in
	apt) run apt-get update || return 1 ;;
	dnf) run dnf -y makecache || return 1 ;;
	zypper) run zypper --non-interactive refresh || return 1 ;;
	pacman)
		# a bare -Sy is a partial upgrade, which Arch documents as unsupported
		;;
	esac
	PKG_INDEX_FRESH=1
}

# pkg_available <package> - the package has an installable candidate.
pkg_available() {
	case "$OS_FAMILY" in
	apt)
		local candidate
		candidate=$(apt-cache policy "$1" 2>/dev/null | awk '/Candidate:/ {print $2; exit}')
		[[ -n "$candidate" && "$candidate" != "(none)" ]]
		;;
	dnf) dnf -q list --available "$1" >/dev/null 2>&1 ;;
	zypper) zypper --non-interactive info "$1" >/dev/null 2>&1 ;;
	pacman) pacman -Si "$1" >/dev/null 2>&1 ;;
	*) return 1 ;;
	esac
}

# Tools the steps call directly: curl and wget for keys and repos, gnupg
# for apt keys, jq for the watchdog, openssl for the self-signed
# certificate, logrotate for the Suricata rotation file, git for
# source builds, sudo (visudo) for the panel rule. A minimal image has none of them.
pkg_install_base() {
	case "$OS_FAMILY" in
	apt)
		local -a pkgs=(ca-certificates curl wget gnupg jq git openssl logrotate iproute2 sudo)
		# add-apt-repository (OISF PPA, universe) comes from this package.
		[[ "$OS_ID" == "ubuntu" ]] && pkgs+=(software-properties-common)
		pkg_install "${pkgs[@]}"
		;;
	dnf)
		# Only what is missing: on RHEL 9 the curl binary comes from
		# curl-minimal and installing curl next to it is a conflict.
		local -a missing=()
		local pair
		for pair in curl:curl wget:wget gpg:gnupg2 jq:jq git:git openssl:openssl \
			logrotate:logrotate ip:iproute visudo:sudo update-ca-trust:ca-certificates; do
			command -v "${pair%%:*}" >/dev/null 2>&1 || missing+=("${pair##*:}")
		done
		[[ "${#missing[@]}" -eq 0 ]] || pkg_install "${missing[@]}"
		;;
	zypper | pacman)
		local -a missing=()
		local pair gpgpkg=gnupg gitpkg=git
		[[ "$OS_FAMILY" == "zypper" ]] && gpgpkg=gpg2 && gitpkg=git-core
		for pair in curl:curl wget:wget gpg:"$gpgpkg" jq:jq git:"$gitpkg" openssl:openssl \
			logrotate:logrotate ip:iproute2 visudo:sudo; do
			command -v "${pair%%:*}" >/dev/null 2>&1 || missing+=("${pair##*:}")
		done
		[[ "${#missing[@]}" -eq 0 ]] || pkg_install "${missing[@]}"
		;;
	generic)
		# The Docker runtimes need little from the host: the commands the
		# steps call themselves. They are not installed for the person.
		local -a lacking=()
		local c
		for c in ip visudo openssl jq; do
			command -v "$c" >/dev/null 2>&1 || lacking+=("$c")
		done
		if [[ "${#lacking[@]}" -gt 0 ]]; then
			echo "$OS_ID: commands not found: ${lacking[*]}; install them with the distribution packages and repeat" >&2
			return 1
		fi
		;;
	esac
}

# pkg_enable_extra_repos - the RHEL clones keep Suricata, redis and the
# -devel packages in EPEL and CodeReady Builder. Fedora and Amazon Linux
# need nothing; RHEL itself needs a subscription, so it is left to the
# administrator with a clear message.
pkg_enable_extra_repos() {
	[[ "$OS_FAMILY" == "dnf" ]] || return 0
	local major="${OS_VERSION_ID%%.*}" repo=crb
	case "$OS_ID" in
	fedora | amzn) return 0 ;;
	rocky | almalinux | centos)
		pkg_install dnf-plugins-core epel-release || return 1
		[[ "$major" =~ ^[0-9]+$ ]] && ((major <= 8)) && repo=powertools
		run dnf config-manager --set-enabled "$repo" || return 1
		;;
	rhel)
		# EPEL from the Fedora project; CodeReady Builder needs a
		# subscribed system. A system without one still installs the
		# packages, only the -devel libraries for a source build are
		# missing, and that fails with a clear message later.
		pkg_install dnf-plugins-core "https://dl.fedoraproject.org/pub/epel/epel-release-latest-${major}.noarch.rpm" || return 1
		run subscription-manager repos "--enable=codeready-builder-for-rhel-${major}-$(uname -m)-rpms" ||
			echo "rhel: the CodeReady Builder repository is not enabled (a subscription is needed); enable it by hand to build from source" >&2
		;;
	*)
		echo "$OS_ID: enable EPEL and the -devel repository by hand, the installer does not touch them" >&2
		;;
	esac
}

# pkg_build_deps <suricata|ndpi> - compilers and libraries a source
# build needs; without them autogen.sh fails on a clean image.
pkg_build_deps() {
	case "$OS_FAMILY" in
	apt)
		local -a pkgs=(build-essential git autoconf automake libtool pkg-config make libpcap-dev)
		if [[ "$1" == "suricata" ]]; then
			pkgs+=(libpcre2-dev libyaml-dev libjansson-dev libmagic-dev zlib1g-dev
				libcap-ng-dev libnet1-dev liblz4-dev python3-yaml cargo rustc)
			# A git checkout generates its Rust headers with cbindgen.
			pkg_available cbindgen && pkgs+=(cbindgen)
		fi
		pkg_install "${pkgs[@]}"
		;;
	dnf)
		local -a pkgs=(gcc gcc-c++ make git autoconf automake libtool pkgconf-pkg-config libpcap-devel)
		if [[ "$1" == "suricata" ]]; then
			pkgs+=(pcre2-devel libyaml-devel jansson-devel file-devel zlib-devel
				libcap-ng-devel libnet-devel lz4-devel python3-pyyaml cargo rust)
			pkg_available cbindgen && pkgs+=(cbindgen)
		fi
		pkg_install "${pkgs[@]}"
		;;
	*)
		die 3 "pkg_build_deps: unknown package family: $OS_FAMILY"
		;;
	esac
}

# Suricata 8.0 needs Rust 1.75. Ubuntu keeps rustc-1.N packages next to the
# default one; OISF documents RUSTC/CARGO for ./configure
# to pick them. On a distro with nothing newer configure prints its own
# message and the step stops there.
# Rust 1.75 is the MSRV of the Suricata 8.0 releases (configure.ac).
SURICATA_RUST_MIN_MINOR=75

# pkg_rust_versioned_minor - the smallest N >= 85 for which the apt
# repositories carry rustc-1.N; empty when there is none.
pkg_rust_versioned_minor() {
	apt-cache pkgnames rustc-1. 2>/dev/null | sed -n 's/^rustc-1\.\([0-9][0-9]*\)$/\1/p' |
		awk -v m="$SURICATA_RUST_MIN_MINOR" '$1 >= m' | sort -n | head -n 1
}

# pkg_rust_obtainable - a Rust new enough for Suricata from git is
# installed or can be installed from the repositories.
pkg_rust_obtainable() {
	local have
	have=$(rustc --version 2>/dev/null | sed -n 's/^rustc 1\.\([0-9][0-9]*\)\..*/\1/p')
	((${have:-0} >= SURICATA_RUST_MIN_MINOR)) && return 0
	case "$OS_FAMILY" in
	apt) [[ -n "$(pkg_rust_versioned_minor)" ]] ;;
	dnf)
		have=$(dnf -q repoquery --latest-limit=1 --qf '%{version}' rust 2>/dev/null |
			sed -n 's/^1\.\([0-9][0-9]*\)\..*/\1/p' | head -n 1)
		((${have:-0} >= SURICATA_RUST_MIN_MINOR))
		;;
	*) return 1 ;;
	esac
}

pkg_select_rust() {
	[[ "$DRY_RUN" == "1" ]] && return 0
	local have wanted
	have=$(rustc --version 2>/dev/null | sed -n 's/^rustc 1\.\([0-9][0-9]*\)\..*/\1/p')
	((${have:-0} >= SURICATA_RUST_MIN_MINOR)) && return 0
	wanted=$(pkg_rust_versioned_minor)
	if [[ -z "$wanted" ]]; then
		echo "suricata: rustc 1.${have:-?} is older than 1.${SURICATA_RUST_MIN_MINOR}, there are no newer rustc-1.N packages in the repositories; the build may fail at configure (then use SURICATA_SOURCE=oisf or distro)" >&2
		return 0
	fi
	pkg_install "rustc-1.$wanted" "cargo-1.$wanted" || return 1
	export RUSTC="rustc-1.$wanted" CARGO="cargo-1.$wanted"
}

# net_iface_exists <name> - the interface is there. Uses ip when it is
# installed and sysfs otherwise: a minimal image has no iproute2 yet.
net_iface_exists() {
	if command -v ip >/dev/null 2>&1; then
		ip link show "$1" >/dev/null 2>&1
	else
		[[ -e "$(path_sys_class_net)/$1" ]]
	fi
}

# net_default_iface - the interface of the default route, else the first
# non-loopback interface that has a device behind it, else the first
# non-loopback one; empty when there is none. Read from /proc and sysfs,
# so it works before iproute2 is installed.
net_default_iface() {
	local found="" dir
	if [[ -r "$(path_proc_net_route)" ]]; then
		found=$(awk 'NR > 1 && $2 == "00000000" {print $1; exit}' "$(path_proc_net_route)")
	fi
	dir=$(path_sys_class_net)
	if [[ -z "$found" && -d "$dir" ]]; then
		local candidate
		for candidate in "$dir"/*; do
			[[ "${candidate##*/}" == "lo" ]] && continue
			if [[ -e "$candidate/device" ]]; then
				found="${candidate##*/}"
				break
			fi
		done
		if [[ -z "$found" ]]; then
			for candidate in "$dir"/*; do
				[[ -e "$candidate" && "${candidate##*/}" != "lo" ]] || continue
				found="${candidate##*/}"
				break
			done
		fi
	fi
	printf '%s' "$found"
}

# os_support_level - "supported", "unverified" or "unsupported" for this
# system. Supported: Ubuntu LTS from 22.04, Debian from 12, Rocky Linux and
# AlmaLinux from 8. Anything older of those is unsupported. Anything else
# of a known family (RHEL and CentOS Stream until they become a target, an
# interim Ubuntu, Fedora, Mint) is tried with a warning.
os_support_level() {
	local major="${OS_VERSION_ID%%.*}" minor="${OS_VERSION_ID#*.}"
	if [[ ! "$major" =~ ^[0-9]+$ ]]; then
		echo unverified
		return
	fi
	case "$OS_FAMILY:$OS_ID" in
	apt:ubuntu)
		if ((major < 22)); then
			echo unsupported
		elif [[ "$minor" == "04" ]] && ((major % 2 == 0)); then
			echo supported
		else
			echo unverified
		fi
		;;
	apt:debian)
		if ((major >= 12)); then echo supported; else echo unsupported; fi
		;;
	dnf:rocky | dnf:almalinux)
		if ((major >= 8)); then echo supported; else echo unsupported; fi
		;;
	dnf:rhel | dnf:centos)
		if ((major >= 8)); then echo unverified; else echo unsupported; fi
		;;
	*) echo unverified ;;
	esac
}

# apt_enable_component <component> - add a component such as contrib to
# the Debian archives in the sources, in the one-line format
# (sources.list, *.list) and in deb822 (*.sources). Only lines and
# stanzas that point at a debian.org host are touched, each changed file
# is copied to the backups directory first (apt warns about stray files in
# sources.list.d), and a second call changes nothing.
apt_enable_component() {
	local comp="$1" f dir changed=0
	dir=$(path_apt_dir)
	for f in "$dir/sources.list" "$dir"/sources.list.d/*.list "$dir"/sources.list.d/*.sources; do
		[[ -f "$f" ]] || continue
		local tmp
		tmp=$(mktemp)
		awk -v comp="$comp" '
			function has(list, word,    n, a, i) {
				n = split(list, a, /[ \t]+/)
				for (i = 1; i <= n; i++) if (a[i] == word) return 1
				return 0
			}
			/^(deb|deb-src)[ \t]/ && /debian\.org|debian\.net/ {
				# deb [opts] URI suite comp1 comp2 ...
				line = $0; sub(/\[[^]]*\][ \t]*/, "", line)
				n = split(line, w, /[ \t]+/)
				if (n >= 4 && has(substr(line, index(line, w[4])), "main") && !has(substr(line, index(line, w[4])), comp)) {
					print $0 " " comp; next
				}
			}
			/^URIs:/ { debian = ($0 ~ /debian\.org|debian\.net/) }
			/^$/ { debian = 0 }
			/^Components:/ && debian {
				if (has(substr($0, 13), "main") && !has(substr($0, 13), comp)) { print $0 " " comp; next }
			}
			{ print }
		' "$f" >"$tmp"
		if ! cmp -s "$f" "$tmp"; then
			if [[ "$DRY_RUN" == "1" ]]; then
				echo "+ enable $comp in $f"
			else
				backup "$f"
				cat "$tmp" >"$f"
			fi
			changed=1
		fi
		rm -f "$tmp"
	done
	if [[ "$changed" == "1" && "$DRY_RUN" != "1" ]]; then
		PKG_INDEX_FRESH=0
	fi
	return 0
}

# selinux_port <type> <port> - lets a confined daemon use a non-default
# TCP port (semanage port). Idempotent: a port already carrying the type
# is left alone; -a fails when policy already defines the port with
# another type, then -m remaps it. Not fatal: a missing type (no policy
# module for that daemon) only prints a warning.
selinux_port() {
	local type="$1" port="$2"
	selinux_active || return 0
	if ! command -v semanage >/dev/null 2>&1; then
		[[ "$OS_FAMILY" == "dnf" ]] && pkg_install policycoreutils-python-utils
	fi
	if ! command -v semanage >/dev/null 2>&1; then
		echo "selinux: semanage not found, port $port did not get the type $type" >&2
		return 0
	fi
	if semanage port -l 2>/dev/null | awk -v t="$type" '$1 == t && $2 == "tcp" {$1 = ""; $2 = ""; gsub(/,/, " "); print}' | grep -qw -- "$port"; then
		return 0
	fi
	run semanage port -a -t "$type" -p tcp "$port" ||
		run semanage port -m -t "$type" -p tcp "$port" ||
		echo "selinux: could not give port $port the type $type (the policy may have no such type)" >&2
	return 0
}

# selinux_relabel_installed - one pass over everything dpistack writes,
# at the end of install and reconfigure.
selinux_relabel_installed() {
	selinux_restore \
		"$(path_etc)" "$(path_state_dir)" "$(path_log_dir)" \
		"$(path_sbin_dir)" "$(path_lib_dir)" "$(path_panel_bin)" \
		"$(path_panel_service_unit)" "$(path_watch_service_unit)" "$(path_watch_timer_unit)" \
		"$(path_sudoers)" \
		"${DPISTACK_ROOT}/etc/suricata" "${DPISTACK_ROOT}/var/lib/suricata" \
		"${DPISTACK_ROOT}/var/log/suricata" "${DPISTACK_ROOT}/usr/lib/suricata" \
		"${DPISTACK_ROOT}/etc/ntopng" "${DPISTACK_ROOT}/etc/evebox" "$(path_evebox_data_dir)" \
		"${DPISTACK_ROOT}/etc/nginx/conf.d"
}

# copr_chroot - the COPR chroot dnf would pick for this system
# (epel-N for the RHEL family, fedora-N for Fedora), empty when unknown.
copr_chroot() {
	local major="${OS_VERSION_ID%%.*}"
	[[ "$major" =~ ^[0-9]+$ ]] || return 0
	case "$OS_ID" in
	fedora) echo "fedora-$major" ;;
	*) echo "epel-$major" ;;
	esac
}
DPISTACK_BUNDLE_END
