schema_known() { [[ -n "${SCHEMA_TYPE[$1]+x}" ]]; }

schema_is_basic() { [[ "${SCHEMA_LEVEL[$1]}" == "basic" ]]; }
schema_is_secret() { [[ "${SCHEMA_SECRET[$1]}" == "yes" ]]; }

schema_not_yet_supported() {
	# schema_not_yet_supported <key> <value>
	local combo="$1=$2"
	[[ -n "${SCHEMA_NOT_YET_SUPPORTED[$combo]+x}" ]]
}

schema_validate_one() {
	# schema_validate_one <key> <value>
	# Prints an error to stdout and returns 1 if invalid, silent 0 if ok.
	local key="$1" value="$2"

	if ! schema_known "$key"; then
		echo "unknown key: $key"
		return 1
	fi

	if schema_not_yet_supported "$key" "$value"; then
		echo "$key=$value: not supported yet"
		return 1
	fi

	local type="${SCHEMA_TYPE[$key]}"

	if [[ -z "$value" && "$type" != "enum" ]]; then
		return 0
	fi

	case "$type" in
	enum)
		local opts="${SCHEMA_OPTIONS[$key]}"
		local ok=0
		local IFS=','
		for opt in $opts; do
			[[ "$value" == "$opt" ]] && ok=1
		done
		if [[ "$ok" -ne 1 ]]; then
			echo "$key=$value: invalid value, allowed: $opts"
			return 1
		fi
		;;
	int)
		# No leading zeros: bash reads "08" as a bad octal number, "010" as
		# eight, and a value kept as "08" breaks every later calculation.
		if ! [[ "$value" =~ ^(0|-?[1-9][0-9]*)$ ]]; then
			echo "$key=$value: an integer without leading zeros expected"
			return 1
		fi
		local range="${SCHEMA_OPTIONS[$key]}"
		if [[ -n "$range" ]]; then
			local min="${range%..*}" max="${range#*..}"
			if ((value < min || value > max)); then
				echo "$key=$value: out of range $range"
				return 1
			fi
		fi
		;;
	free)
		local pattern="${SCHEMA_PATTERN[$key]:-}"
		if [[ -n "$pattern" && ! "$value" =~ $pattern ]]; then
			# A secret is never echoed back, not even in an error.
			if schema_is_secret "$key"; then
				echo "$key: invalid value format"
			else
				echo "$key=$value: invalid characters or format"
			fi
			return 1
		fi
		;;
	*)
		echo "$key: unknown schema type $type"
		return 1
		;;
	esac
	return 0
}
DPISTACK_BUNDLE_END
