#!/usr/bin/env bash
# Flat "key=value" step-completion log, rewritten atomically, plus
# render-hash tracking for idempotency (tech.md 5.4).

state_read_value() {
	# state_read_value <key>
	local key="$1"
	local f
	f=$(path_state_file)
	[[ -f "$f" ]] || return 0
	awk -F= -v k="$key" '$1 == k {print substr($0, length(k) + 2); exit}' "$f"
}

state_write_value() {
	# state_write_value <key> <value>
	local key="$1" value="$2"
	local f lock_fd tmp
	f=$(path_state_file)
	mkdir -p "$(dirname "$f")"
	# The installer and the watchdog both rewrite this file; without a
	# lock one of them could overwrite the other's change.
	exec {lock_fd}>"${f}.lock"
	flock -x "$lock_fd"
	tmp=$(mktemp)
	if [[ -f "$f" ]]; then
		# awk compares the key as text; grep would read its dots as regex.
		awk -F= -v k="$key" '$1 != k' "$f" >"$tmp" || true
	fi
	echo "${key}=${value}" >>"$tmp"
	atomic_write "$f" 0600 <"$tmp"
	rm -f "$tmp"
	exec {lock_fd}>&-
}

state_set_step_done() {
	local step="$1"
	state_write_value "step.${step}.status" "done"
	state_write_value "step.${step}.ts" "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
}

# state_install_finished - 0 when an install ran to its end on this host.
# The marker is written at the end of cmd_install; an install of an older
# version has no marker, so a done Suricata or verify step counts too. A
# config that exists next to a failed preflight is NOT an installation.
state_install_finished() {
	[[ "$(state_read_value install.finished)" == "yes" ]] && return 0
	[[ "$(state_read_value step.verify.status)" == "done" ||
	"$(state_read_value step.suricata.status)" == "done" ||
	"$(state_read_value step.panel.status)" == "done" ]]
}

# Render-hash tracking for idempotency and the "manually edited file"
# guard (tech.md 5.4). Added back in slice 2 once step_suricata.sh
# actually renders something; slice 1 removed these as dead code
# because nothing called them yet.

state_file_hash() {
	# state_file_hash <rendered-file-path> -> stored hash or empty
	state_read_value "filehash.$(echo "$1" | tr '/' '_')"
}

state_set_file_hash() {
	local path="$1" hash="$2"
	state_write_value "filehash.$(echo "$path" | tr '/' '_')" "$hash"
}

state_hash_content() {
	# state_hash_content < content-on-stdin -> sha256 hex
	sha256sum | cut -d' ' -f1
}
DPISTACK_BUNDLE_END
put lib/step_access.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Access: binds ntopng/EveBox/panel per ACCESS_MODE, an nginx reverse
# proxy for ACCESS_MODE=nginx, and firewall rules for FIREWALL_MANAGE
# (tech.md slice 7). ntopng/evebox stay on 127.0.0.1 for localhost and
# nginx modes (nginx does the proxying); lan makes them bind 0.0.0.0
# directly - access_effective_bind_host is what their own render
# functions call, so there is exactly one place that decides this.

NGINX_UNIT="nginx.service"

# access_backend_port <public-port> - the port a web service itself listens
# on. Only with ACCESS_MODE=nginx does it differ from the public one: nginx
# takes the public port on every address, so the service moves to
# 127.0.0.1:<public>+10000 (config validation keeps the public port at
# 55535 or below in that mode). Binding two sockets to the same port would
# fail with EADDRINUSE.
access_backend_port() {
	local port="$1"
	if [[ "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]]; then
		echo $((port + 10000))
	else
		echo "$port"
	fi
}

# access_explicit_bind - the address chosen in BIND_ADDR; fails for auto.
access_explicit_bind() {
	local v="${CONF[BIND_ADDR]:-auto}"
	[[ -z "$v" || "$v" == "auto" ]] && return 1
	echo "$v"
}

# access_effective_bind_host - the one place that decides where the web
# services listen. localhost: BIND_ADDR or 127.0.0.1; lan: BIND_ADDR or
# 0.0.0.0; nginx: the services stay on 127.0.0.1 behind nginx.
access_effective_bind_host() {
	local explicit
	explicit=$(access_explicit_bind) || explicit=""
	case "${CONF[ACCESS_MODE]:-localhost}" in
	lan) echo "${explicit:-0.0.0.0}" ;;
	localhost) echo "${explicit:-127.0.0.1}" ;;
	*) echo "127.0.0.1" ;;
	esac
}

# access_connect_host - the address another service of this host uses to reach
# a listener: the bind address, 127.0.0.1 when it listens on every address.
access_connect_host() {
	local host
	host=$(access_effective_bind_host)
	[[ "$host" == "0.0.0.0" ]] && host="127.0.0.1"
	echo "$host"
}

# access_policy - who the panel lets in: localhost, lan or nginx. A
# non-loopback BIND_ADDR with ACCESS_MODE=localhost opens the panels to the
# local network, so it counts as lan.
access_policy() {
	local mode="${CONF[ACCESS_MODE]:-localhost}" host
	if [[ "$mode" == "localhost" ]]; then
		host=$(access_effective_bind_host)
		[[ "$host" == 127.* ]] || mode="lan"
	fi
	echo "$mode"
}

# access_local_addresses - "interface address" lines for the IPv4 addresses
# of this host that could be chosen in BIND_ADDR.
access_local_addresses() {
	ip -o -4 addr show scope global 2>/dev/null | awk '{split($4, a, "/"); print $2, a[1]}'
}

access_detect_lan_cidr() {
	local iface
	iface=$(ip -4 route show default 2>/dev/null | awk '/default/{for(i=1;i<=NF;i++) if($i=="dev") print $(i+1)}' | head -1)
	[[ -n "$iface" ]] || return 1
	local network
	network=$(ip -4 route show dev "$iface" scope link 2>/dev/null | awk '{print $1}' | head -1)
	[[ -n "$network" ]] || return 1
	echo "$network"
}

access_effective_lan_cidr() {
	local v="${CONF[LAN_CIDR]:-auto}"
	if [[ -z "$v" || "$v" == "auto" ]]; then
		access_detect_lan_cidr
	else
		echo "$v"
	fi
}

# access_render_service <name> <public-port> <upstream-port>
access_render_nginx_service() {
	local name="$1" port="$2" upstream="$3" cidr="$4"
	local listen tls_block
	if [[ "${CONF[NGINX_TLS]:-none}" == "none" ]]; then
		listen="${port}"
		tls_block=""
	else
		listen="${port} ssl"
		tls_block="    ssl_certificate $(access_tls_cert_path "$name");
    ssl_certificate_key $(access_tls_key_path "$name");"
	fi
	render_template "$SCRIPT_DIR/templates/nginx.conf.tpl" \
		"NAME=$name" \
		"LISTEN=$listen" \
		"TLS_BLOCK=$tls_block" \
		"ALLOW_BLOCK=    allow ${cidr};" \
		"UPSTREAM_PORT=$upstream"
}

access_tls_dir() { path_nginx_tls_dir; }
access_tls_cert_path() { echo "$(access_tls_dir)/${1}.crt"; }
access_tls_key_path() { echo "$(access_tls_dir)/${1}.key"; }

access_ensure_selfsigned_cert() {
	local name="$1"
	local cert key
	cert=$(access_tls_cert_path "$name")
	key=$(access_tls_key_path "$name")
	[[ -f "$cert" && -f "$key" ]] && return 0
	run mkdir -p "$(access_tls_dir)" || return 1
	run openssl req -x509 -nodes -newkey rsa:2048 -days 3650 \
		-keyout "$key" -out "$cert" -subj "/CN=dpistack-${name}" || return 1
}

# access_services - the web services that are switched on, one per line
# (ntopng, evebox, panel); nginx, certificates, SELinux ports and firewall
# rules cover only these (v0.25.0: a part can be left out).
access_services() {
	local name
	for name in ntopng evebox panel; do
		step_component_enabled "$name" && echo "$name"
	done
	return 0
}

# access_service_port <ntopng|evebox|panel> - the public port of the service.
access_service_port() {
	case "$1" in
	ntopng) echo "${CONF[NTOPNG_PORT]:-3000}" ;;
	evebox) echo "${CONF[EVEBOX_PORT]:-5636}" ;;
	panel) echo "${CONF[PANEL_PORT]:-9800}" ;;
	esac
}

access_render_nginx_full() {
	local cidr
	cidr=$(access_effective_lan_cidr) || cidr="127.0.0.1/32"
	local name port
	for name in $(access_services); do
		port=$(access_service_port "$name")
		access_render_nginx_service "$name" "$port" "$(access_backend_port "$port")" "$cidr"
		echo
	done
}

access_selinux_notice() {
	command -v getenforce >/dev/null 2>&1 || return 0
	local mode
	mode=$(getenforce 2>/dev/null)
	if [[ "$mode" == "Enforcing" ]]; then
		# nginx may not open connections to the local ntopng, EveBox and
		# panel ports until this boolean is on.
		if [[ "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]]; then
			run setsebool -P httpd_can_network_connect 1 ||
				echo "access: SELinux Enforcing, setsebool httpd_can_network_connect failed: nginx cannot proxy to the local ports" >&2
		else
			echo "access: SELinux is in Enforcing mode; for ACCESS_MODE=${CONF[ACCESS_MODE]:-localhost} no changes are needed" >&2
		fi
	fi
}

# access_selinux_ports - in nginx mode nginx itself listens on the public
# ports (3000, 5636, 9800 by default), which SELinux only lets httpd_t use
# when they carry http_port_t.
access_selinux_ports() {
	[[ "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]] || return 0
	local port
	local name
	for name in $(access_services); do
		selinux_port http_port_t "$(access_service_port "$name")"
	done
}

# The firewall rules dpistack added are written down in the state as
# "cidr,port" pairs (state key access.fw.rules), and only those are ever
# taken out again: a rule the administrator had before (or adds later) is
# never touched. A change of ACCESS_MODE, LAN_CIDR or FIREWALL_MANAGE, and
# uninstall, remove what is no longer wanted.
ACCESS_FW_STATE_KEY="access.fw.rules"

# access_fw_tool -> ufw | firewalld | (nothing)
access_fw_tool() {
	if command -v ufw >/dev/null 2>&1; then
		echo ufw
	elif command -v firewall-cmd >/dev/null 2>&1; then
		echo firewalld
	fi
	return 0
}

access_fw_rich_rule() {
	echo "rule family=ipv4 source address=${1} port port=${2} protocol=tcp accept"
}

# access_fw_has <cidr> <port> - the rule is there, whoever added it.
access_fw_has() {
	local cidr="$1" port="$2"
	if [[ "$(access_fw_tool)" == "ufw" ]]; then
		ufw show added 2>/dev/null | grep -qxF "ufw allow from $cidr to any port $port proto tcp"
	else
		firewall-cmd --permanent "--query-rich-rule=$(access_fw_rich_rule "$cidr" "$port")" >/dev/null 2>&1
	fi
}

# access_fw_delete <cidr> <port> - take one of our rules out.
access_fw_delete() {
	local cidr="$1" port="$2"
	if [[ "$(access_fw_tool)" == "ufw" ]]; then
		run ufw --force delete allow from "$cidr" to any port "$port" proto tcp
	else
		run firewall-cmd --permanent "--remove-rich-rule=$(access_fw_rich_rule "$cidr" "$port")"
	fi
}

# access_allow_port <cidr> <port> - one rule in whichever firewall the
# system has: ufw (Debian family) or firewalld (RHEL family). A rule that
# was already there and is not ours is left alone and not written down.
access_allow_port() {
	local cidr="$1" port="$2" rule="$1,$2" mine=1
	if access_fw_has "$cidr" "$port" && [[ " $(state_read_value "$ACCESS_FW_STATE_KEY") " != *" $rule "* ]]; then
		mine=0
	fi
	if [[ "$mine" == 1 ]]; then
		if [[ "$(access_fw_tool)" == "ufw" ]]; then
			run ufw allow from "$cidr" to any port "$port" proto tcp || return 1
		else
			run firewall-cmd --permanent "--add-rich-rule=$(access_fw_rich_rule "$cidr" "$port")" || return 1
		fi
		ACCESS_FW_OWNED+=("$rule")
	fi
	return 0
}

# access_service_ports - the public ports of the services that are switched on.
access_service_ports() {
	local name
	for name in $(access_services); do
		access_service_port "$name"
	done
}

# access_fw_wanted - "cidr,port" for every port that should be open now.
access_fw_wanted() {
	[[ "${CONF[FIREWALL_MANAGE]:-no}" == "auto" ]] || return 0
	local cidr port
	local -a ports=()
	cidr=$(access_effective_lan_cidr) || cidr="127.0.0.1/32"
	case "$(access_policy)" in
	nginx)
		mapfile -t ports < <(access_service_ports)
		;;
	lan)
		mapfile -t ports < <(access_service_ports)
		# The metrics backend binds 0.0.0.0 in lan mode (and nginx does not
		# proxy it), so its own port is opened for LAN_CIDR too.
		[[ "${CONF[METRICS_BACKEND]:-none}" != "none" ]] && ports+=("$(metrics_port "${CONF[METRICS_BACKEND]}")")
		;;
	esac
	for port in "${ports[@]}"; do
		echo "$cidr,$port"
	done
	return 0
}

# access_firewall_sync <wanted rules...> - make the rules we own equal the
# wanted ones: take out what we added earlier and is no longer wanted, add
# what is missing, write the result down. Returns 0 when nothing could be
# done because the firewall is not there (the state stays as it was).
access_firewall_sync() {
	local -a wanted=("$@")
	local tool old rule changed=0
	tool=$(access_fw_tool)
	old=$(state_read_value "$ACCESS_FW_STATE_KEY")
	if [[ -z "$tool" ]]; then
		[[ ${#wanted[@]} -gt 0 ]] && echo "access: FIREWALL_MANAGE=auto, but neither ufw nor firewalld was found - the rules are not applied" >&2
		return 0
	fi
	# firewalld installed but stopped: its permanent rules would be
	# written, but --reload fails and the ports stay closed or open by
	# accident. Say so and leave it to the administrator.
	if [[ "$tool" == "firewalld" ]] && ! firewall-cmd --state >/dev/null 2>&1; then
		if [[ ${#wanted[@]} -gt 0 || -n "$old" ]]; then
			echo "access: firewalld is not running - the rules are not applied (start firewalld and repeat reconfigure)" >&2
		fi
		return 0
	fi
	ACCESS_FW_OWNED=()
	for rule in $old; do
		if [[ " ${wanted[*]} " == *" $rule "* ]]; then
			ACCESS_FW_OWNED+=("$rule")
		else
			access_fw_delete "${rule%,*}" "${rule#*,}" || return 1
			changed=1
		fi
	done
	for rule in "${wanted[@]}"; do
		[[ " ${ACCESS_FW_OWNED[*]} " == *" $rule "* ]] && continue
		access_allow_port "${rule%,*}" "${rule#*,}" || return 1
		changed=1
	done
	# firewalld keeps permanent rules apart from the running ones.
	if [[ "$tool" == "firewalld" && "$changed" == 1 ]]; then
		run firewall-cmd --reload || return 1
	fi
	state_write_value "$ACCESS_FW_STATE_KEY" "${ACCESS_FW_OWNED[*]}"
	return 0
}

access_firewall_apply() {
	local -a wanted=()
	local rule
	while IFS= read -r rule; do
		[[ -n "$rule" ]] && wanted+=("$rule")
	done < <(access_fw_wanted)
	access_firewall_sync "${wanted[@]}"
}

# access_firewall_forget - uninstall: take out every rule we added.
access_firewall_forget() {
	access_firewall_sync
}

step_access_check() {
	local mode="${CONF[ACCESS_MODE]:-localhost}"

	if [[ "$mode" == "nginx" ]]; then
		local rendered
		rendered=$(access_render_nginx_full)
		if [[ "${CONF[NGINX_MANAGE]:-snippet}" == "yes" ]]; then
			[[ -f "$(path_nginx_confd)" ]] || return 1
			[[ "$(state_hash_content <"$(path_nginx_confd)")" == "$(printf '%s\n' "$rendered" | state_hash_content)" ]] || return 1
			systemctl is-active --quiet "$NGINX_UNIT" || return 1
		else
			[[ -f "$(path_nginx_snippet)" ]] || return 1
			[[ "$(state_hash_content <"$(path_nginx_snippet)")" == "$(printf '%s\n' "$rendered" | state_hash_content)" ]] || return 1
		fi
	fi

	[[ "$(state_read_value step.access.status)" == "done" ]] || return 1
	return 0
}

step_access_apply() {
	local mode="${CONF[ACCESS_MODE]:-localhost}" policy
	policy=$(access_policy)

	access_selinux_notice
	access_selinux_ports

	if [[ "$policy" != "localhost" ]]; then
		echo "access: ACCESS_MODE=$mode with bind address $(access_effective_bind_host) opens the web interfaces beyond localhost." >&2
		if [[ "$policy" == "lan" ]]; then
			echo "access: ntopng/EveBox/the panel will listen on $(access_effective_bind_host) and be visible to the whole LAN_CIDR network; passwords go over plain HTTP unless NGINX_TLS is on." >&2
		fi
	fi

	if [[ "$mode" == "nginx" ]]; then
		if [[ "${CONF[NGINX_TLS]:-none}" == "selfsigned" ]]; then
			local name
			for name in $(access_services); do
				access_ensure_selfsigned_cert "$name" || return 1
			done
		fi

		local rendered
		rendered=$(access_render_nginx_full)

		if [[ "${CONF[NGINX_MANAGE]:-snippet}" == "yes" ]]; then
			command -v nginx >/dev/null 2>&1 || pkg_install nginx || return 1
			write_rendered_file "$(path_nginx_confd)" "$rendered"
			if ! access_nginx_test_ok; then
				echo "access: nginx -t failed on the rendered config, the changes are not applied" >&2
				return 1
			fi
			run systemctl enable --now "$NGINX_UNIT" || return 1
			run systemctl reload "$NGINX_UNIT" || return 1
		else
			# snippet: never touches the system nginx.conf or reloads
			# nginx (criterion 3) - just leaves the file for the owner.
			write_rendered_file "$(path_nginx_snippet)" "$rendered"
			echo "access: the nginx config is not applied automatically (NGINX_MANAGE=snippet)." >&2
			echo "access: include it yourself: include $(path_nginx_snippet); - and reload nginx." >&2
		fi
	fi

	access_firewall_apply || return 1

	state_write_value "step.access.status" "done"
	return 0
}

step_access_plan() {
	local mode="${CONF[ACCESS_MODE]:-localhost}"
	echo "access: ACCESS_MODE=$mode, bind $(access_effective_bind_host)"
	if [[ "$mode" == "nginx" ]]; then
		echo "access: nginx (NGINX_MANAGE=${CONF[NGINX_MANAGE]:-snippet}, TLS=${CONF[NGINX_TLS]:-none})"
	fi
	if [[ "${CONF[FIREWALL_MANAGE]:-no}" == "auto" ]]; then
		echo "access: ufw allow from $(access_effective_lan_cidr 2>/dev/null || echo "?")"
	fi
}

# access_nginx_test_ok - real nginx -t in an isolated directory
# (criterion 4), so a bad snippet never reaches the live nginx.conf.
access_nginx_test_ok() {
	local test_dir
	test_dir=$(mktemp -d)
	mkdir -p "$test_dir/logs" "$test_dir/tmp"
	cat >"$test_dir/nginx.conf" <<EOF_CONF
pid ${test_dir}/nginx.pid;
error_log ${test_dir}/logs/error.log;
events {}
http {
    access_log off;
    client_body_temp_path ${test_dir}/tmp/body;
    proxy_temp_path ${test_dir}/tmp/proxy;
    fastcgi_temp_path ${test_dir}/tmp/fcgi;
    uwsgi_temp_path ${test_dir}/tmp/uwsgi;
    scgi_temp_path ${test_dir}/tmp/scgi;
    include $(path_nginx_confd);
}
EOF_CONF
	local ok=0
	nginx -t -c "$test_dir/nginx.conf" -p "$test_dir/" >/dev/null 2>&1 || ok=1
	rm -rf "$test_dir"
	return "$ok"
}
DPISTACK_BUNDLE_END
put lib/step_evebox.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# EveBox: official apt repo (evebox.org/docs/install/debian), package,
# evebox.yaml from templates/evebox.yaml.tpl (tech.md slice 6). Bound to
# Bind address comes from access_effective_bind_host (slice 7). The
# package ships the evebox.service unit and
# EveBox's built-in database.retention.days handles retention (A9,
# SQLite only; 0 disables).

EVEBOX_PACKAGE="evebox"
EVEBOX_UNIT="evebox.service"
EVEBOX_KEY_URL="https://evebox.org/files/evebox.asc"
EVEBOX_REPO_URL="https://evebox.org/files/debian"

evebox_render_es_block() {
	if [[ "${CONF[EVEBOX_DB]:-sqlite}" == "elasticsearch" ]]; then
		echo "  elasticsearch:"
		echo "    url: ${CONF[EVEBOX_ES_URL]:-}"
	fi
}

evebox_render_input_paths() {
	local eve_json
	eve_json=$(path_suricata_eve_json)
	echo "    - \"${eve_json}\""
	echo "    - \"$(dirname "$eve_json")/eve.*.json\""
}

evebox_input_enabled() {
	# The server reads eve.json itself for both databases (SQLite, or
	# shipping into Elasticsearch); without EVE_FILE there is no file.
	if [[ "${CONF[EVE_FILE]:-yes}" == "yes" ]]; then
		echo "true"
	else
		echo "false"
	fi
}

evebox_render_conf() {
	render_template "$SCRIPT_DIR/templates/evebox.yaml.tpl" \
		"EVEBOX_HOST=$(access_effective_bind_host)" \
		"EVEBOX_PORT=$(access_backend_port "${CONF[EVEBOX_PORT]:-5636}")" \
		"EVEBOX_DB_TYPE=${CONF[EVEBOX_DB]:-sqlite}" \
		"EVEBOX_RETENTION_DAYS=${CONF[EVEBOX_RETENTION_DAYS]:-30}" \
		"EVEBOX_INPUT_ENABLED=$(evebox_input_enabled)" \
		"EVEBOX_ES_BLOCK=$(evebox_render_es_block)" \
		"EVEBOX_INPUT_PATHS=$(evebox_render_input_paths)"
}

EVEBOX_RPM_RELEASE_URL="https://evebox.org/files/rpm/stable/evebox-release.noarch.rpm"

evebox_repo_add() {
	if [[ "$OS_FAMILY" == "dnf" ]]; then
		# The stable rpm repository is added by its release package
		# (OISF tracker #3807, evebox.org downloads).
		run dnf install -y "$EVEBOX_RPM_RELEASE_URL" || {
			echo "evebox: could not add the repository $EVEBOX_RPM_RELEASE_URL. Install EveBox from https://evebox.org/#downloads and repeat install --only evebox, or skip the step: --skip evebox" >&2
			return 1
		}
		run dnf -y makecache || return 1
		return 0
	fi
	run mkdir -p "$(dirname "$(path_evebox_keyring)")" || return 1
	run curl -fsSL "$EVEBOX_KEY_URL" -o "$(path_evebox_keyring)" || return 1
	write_rendered_file "$(path_evebox_apt_list)" \
		"deb [signed-by=$(path_evebox_keyring)] ${EVEBOX_REPO_URL} stable main"
	run apt-get update || return 1
}

step_evebox_check() {
	if docker_wanted evebox; then
		[[ -f "$(path_evebox_yaml)" ]] || return 1
		[[ "$(evebox_render_conf | state_hash_content)" == "$(state_hash_content <"$(path_evebox_yaml)")" ]] || return 1
		docker_service_check evebox
		return
	fi
	command -v evebox >/dev/null 2>&1 || return 1

	local conf_path
	conf_path=$(path_evebox_yaml)
	[[ -f "$conf_path" ]] || return 1
	local expected_hash actual_hash
	expected_hash=$(evebox_render_conf | state_hash_content)
	actual_hash=$(state_hash_content <"$conf_path")
	[[ "$expected_hash" == "$actual_hash" ]] || return 1

	systemctl is-active --quiet "$EVEBOX_UNIT" || return 1
	return 0
}

step_evebox_apply() {
	if docker_wanted evebox; then
		runtime_release_native "$EVEBOX_UNIT" || return 1
		write_rendered_file "$(path_evebox_yaml)" "$(evebox_render_conf)" || return 1
		docker_service_apply evebox || return 1
		echo "evebox: in a container, listens on $(access_effective_bind_host):$(access_backend_port "${CONF[EVEBOX_PORT]:-5636}"); the built-in TLS and authentication of EveBox are off, access is limited by the network (ACCESS_MODE/firewall)." >&2
		return 0
	fi
	runtime_release_docker evebox || return 1
	if ! command -v evebox >/dev/null 2>&1; then
		evebox_repo_add || return 1
		pkg_install "$(pkg_spec "$EVEBOX_PACKAGE" "${CONF[EVEBOX_VERSION]:-}")" || return 1
	fi

	write_rendered_file "$(path_evebox_yaml)" "$(evebox_render_conf)"

	# The evebox user must read Suricata's logs (official Debian docs).
	if getent group suricata >/dev/null 2>&1; then
		run usermod -a -G suricata evebox || return 1
	fi

	run systemctl enable --now "$EVEBOX_UNIT" || return 1

	if [[ "${CONF[EVEBOX_DB]:-sqlite}" == "elasticsearch" ]]; then
		echo "evebox: EVEBOX_RETENTION_DAYS works only with SQLite, for Elasticsearch deleting old events is configured on the Elasticsearch side." >&2
	fi
	echo "evebox: listens on $(access_effective_bind_host):$(access_backend_port "${CONF[EVEBOX_PORT]:-5636}"); the built-in TLS and authentication of EveBox are off, access is limited by the network (ACCESS_MODE/firewall)." >&2
	return 0
}

step_evebox_plan() {
	if docker_wanted evebox; then
		docker_service_plan evebox
		echo "evebox: render $(path_evebox_yaml)"
		return 0
	fi
	echo "evebox: repository evebox.org, package $EVEBOX_PACKAGE, database ${CONF[EVEBOX_DB]:-sqlite}, port ${CONF[EVEBOX_PORT]:-5636}, bind $(access_effective_bind_host)"
	echo "evebox: render $(path_evebox_yaml)"
}
