put lib/step_grafana.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Grafana: dashboards over the metrics backend. Optional (GRAFANA_ENABLE),
# native or docker. The native build is the vendor tarball from
# dl.grafana.com; its sha256 comes from the vendor's .sha256 file next to the
# tarball, fetched over TLS at install time (DPISTACK_GRAFANA_SHA256 pins it
# by hand). With a metrics backend selected the backend is provisioned as the
# default data source. Grafana's own first login is admin/admin and asks for
# a new password.

GRAFANA_VERSION="${DPISTACK_GRAFANA_VERSION:-12.2.0}"

grafana_wanted() { [[ "${CONF[GRAFANA_ENABLE]:-no}" == "yes" ]]; }
grafana_runtime() { echo "${CONF[GRAFANA_RUNTIME]:-native}"; }
grafana_port() { echo "${CONF[GRAFANA_PORT]:-3030}"; }

grafana_marker() {
	if [[ "$(grafana_runtime)" == "docker" ]]; then
		echo "docker:grafana"
	else
		echo "native:grafana:${GRAFANA_VERSION}"
	fi
}
grafana_installed() { state_read_value "grafana.installed" 2>/dev/null || true; }

# grafana_datasource_url - host:port of the metrics backend, empty without one.
grafana_datasource_url() {
	local backend="${CONF[METRICS_BACKEND]:-none}"
	[[ "$backend" == "none" ]] && return 0
	echo "$(access_connect_host):$(metrics_port "$backend")"
}

grafana_render_ini() {
	render_template "$SCRIPT_DIR/templates/grafana.ini.tpl" \
		"DATA=$(path_grafana_data_dir)" "PROV=$(path_grafana_prov_dir)" \
		"ADDR=$(access_effective_bind_host)" "PORT=$(grafana_port)"
}

grafana_render_unit() {
	render_template "$SCRIPT_DIR/templates/grafana.service.tpl" \
		"USER=$MONITOR_USER" "HOME=$(path_grafana_home)" "INI=$(path_grafana_ini)"
}

grafana_render_datasource() {
	local url
	url=$(grafana_datasource_url)
	[[ -n "$url" ]] || return 0
	render_template "$SCRIPT_DIR/templates/grafana-datasource.yaml.tpl" "URL=$url"
}

grafana_datasource_path() { echo "$(path_grafana_prov_dir)/datasources/dpistack.yaml"; }

# grafana_files_current - the ini and the data source on disk are what this
# config renders (no data source file when there is no backend).
grafana_files_current() {
	metrics_file_current "$(path_grafana_ini)" "$(grafana_render_ini)" || return 1
	local ds
	ds=$(grafana_render_datasource)
	if [[ -n "$ds" ]]; then
		metrics_file_current "$(grafana_datasource_path)" "$ds" || return 1
	else
		[[ ! -e "$(grafana_datasource_path)" ]] || return 1
	fi
}

grafana_arch() { nodeexp_arch; }

grafana_fetch() {
	local arch url tmp want got
	arch=$(grafana_arch) || {
		echo "grafana: architecture $(uname -m) is not supported (amd64 or arm64 is needed)" >&2
		return 1
	}
	url="https://dl.grafana.com/oss/release/grafana-${GRAFANA_VERSION}.linux-${arch}.tar.gz"
	tmp=$(mktemp -d)
	if ! run curl --proto '=https' --tlsv1.2 -fsSL -o "$tmp/archive.tar.gz" "$url"; then
		echo "grafana: could not download $url" >&2
		rm -rf "$tmp"
		return 1
	fi
	want="${DPISTACK_GRAFANA_SHA256:-}"
	if [[ -z "$want" ]]; then
		if ! want=$(curl --proto '=https' --tlsv1.2 -fsSL "${url}.sha256" 2>/dev/null | awk '{print $1; exit}') || [[ -z "$want" ]]; then
			echo "grafana: could not read the vendor checksum ${url}.sha256, the binary is not installed" >&2
			rm -rf "$tmp"
			return 1
		fi
	fi
	got=$(sha256sum "$tmp/archive.tar.gz" | awk '{print $1}')
	if [[ "$got" != "$want" ]]; then
		echo "grafana: the checksum of $url did not match (expected $want, got $got), the binary is not installed" >&2
		rm -rf "$tmp"
		return 1
	fi
	local home
	home=$(path_grafana_home)
	run rm -rf "$home" || return 1
	run install -d -m 0755 "$home" || return 1
	run tar -xzf "$tmp/archive.tar.gz" -C "$home" --strip-components=1 || {
		rm -rf "$tmp"
		return 1
	}
	rm -rf "$tmp"
}

grafana_stop_installed() {
	local installed runtime
	installed=$(grafana_installed)
	[[ -n "$installed" ]] || return 0
	runtime="${installed%%:*}"
	if [[ "$runtime" == "docker" ]]; then
		if command -v docker >/dev/null 2>&1 && [[ -f "$(path_compose_yaml)" ]]; then
			docker_compose_argv
			run "${DOCKER_COMPOSE_ARGV[@]}" rm -fsv grafana || return 1
		fi
	else
		run systemctl disable --now "dpistack-grafana.service" 2>/dev/null || true
	fi
	return 0
}

# grafana_write_files - the ini, the data source and the directories.
grafana_write_files() {
	local d
	for d in "$(path_grafana_data_dir)" "$(path_grafana_prov_dir)/datasources"; do
		run install -d -m 0750 "$d" || return 1
	done
	run chown -R "$MONITOR_USER:" "$(path_grafana_data_dir)" || return 1
	run chmod o+x "$(dirname "$(path_grafana_ini)")" || return 1
	write_rendered_file "$(path_grafana_ini)" "$(grafana_render_ini)" 0644 || return 1
	local ds
	ds=$(grafana_render_datasource)
	if [[ -n "$ds" ]]; then
		write_rendered_file "$(grafana_datasource_path)" "$ds" 0644 || return 1
		run chmod -R o+rX "$(path_grafana_prov_dir)" || return 1
	else
		run rm -f "$(grafana_datasource_path)" || return 1
	fi
}

step_grafana_check() {
	local installed
	installed=$(grafana_installed)
	if ! grafana_wanted; then
		[[ -z "$installed" ]]
		return
	fi
	[[ "$installed" == "$(grafana_marker)" ]] || return 1
	grafana_files_current || return 1
	if [[ "$(grafana_runtime)" == "docker" ]]; then
		docker_service_check grafana
		return
	fi
	[[ -x "$(path_grafana_home)/bin/grafana" ]] || return 1
	metrics_file_current "$(path_grafana_unit)" "$(grafana_render_unit)" || return 1
	systemctl is-active --quiet "dpistack-grafana.service"
}

step_grafana_apply() {
	local installed refetch=0
	installed=$(grafana_installed)
	if [[ -n "$installed" ]] && { ! grafana_wanted || [[ "$installed" != "$(grafana_marker)" ]]; }; then
		refetch=1
		grafana_stop_installed || return 1
		state_write_value "grafana.installed" "" || return 1
	fi
	grafana_wanted || return 0

	monitor_ensure_user || return 1
	grafana_write_files || return 1
	if [[ "$(grafana_runtime)" == "docker" ]]; then
		docker_service_apply grafana || return 1
	else
		if [[ ! -x "$(path_grafana_home)/bin/grafana" || "$refetch" == "1" ]]; then
			grafana_fetch || return 1
		fi
		write_rendered_file "$(path_grafana_unit)" "$(grafana_render_unit)" || return 1
		run systemctl daemon-reload || return 1
		run systemctl enable --now "dpistack-grafana.service" || return 1
		run systemctl restart "dpistack-grafana.service" || return 1
	fi
	echo "grafana: listens on $(access_effective_bind_host):$(grafana_port); the first login is admin/admin, Grafana asks for a new password at once." >&2
	state_write_value "grafana.installed" "$(grafana_marker)"
}

step_grafana_plan() {
	local installed
	installed=$(grafana_installed)
	if [[ -n "$installed" ]] && { ! grafana_wanted || [[ "$installed" != "$(grafana_marker)" ]]; }; then
		echo "grafana: stop ${installed}"
	fi
	if ! grafana_wanted; then
		[[ -z "$installed" ]] && echo "grafana: no changes (GRAFANA_ENABLE=no)"
		return 0
	fi
	if [[ "$(grafana_runtime)" == "docker" ]]; then
		docker_service_plan grafana
	else
		echo "grafana: Grafana ${GRAFANA_VERSION} from dl.grafana.com with a sha256 check, unit dpistack-grafana.service, listens on $(access_effective_bind_host):$(grafana_port)"
	fi
	local url
	url=$(grafana_datasource_url)
	echo "grafana: data source ${url:-none (no metrics backend)}"
}
DPISTACK_BUNDLE_END
put lib/step_metrics.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Metrics backend (slice 28): VictoriaMetrics single-node or Prometheus,
# native or docker, scraping GET /metrics of the panel. METRICS_BACKEND=none
# means only the endpoint exists and the user brings their own collector
# (README), so the step has nothing to install - and stops a backend this
# installer started earlier, keeping its data (removed only by --purge).
#
# Native binaries come from the projects' GitHub releases: a pinned
# version and the pinned sha256 of the tarball (A10, tech.md). The pins
# below were taken from the release checksum files; DPISTACK_METRICS_*
# overrides exist for tests and for moving to a newer release by hand.

METRICS_USER="dpistack-metrics"
METRICS_VM_VERSION="${DPISTACK_METRICS_VM_VERSION:-v1.153.0}"
METRICS_PROM_VERSION="${DPISTACK_METRICS_PROM_VERSION:-v3.15.0}"
declare -A METRICS_SHA256=(
	[vm_amd64]="1b495bde563825cf83dc7c0425a9d8fa03e7214858e0949f9177efc6bb1f8bfc"
	[vm_arm64]="3d5f965b7a75f713742a7f37195c1d845f47d9dc9d096a2cce29e693f08fd641"
	[prom_amd64]="2a542df32eac02ee17b9d844fb2aa1de00dafa5476579ba8a3ba862e9d572ea0"
	[prom_arm64]="f1f90ec08e849d494ca66c611470afc50192f0355f1a61c33f2cbde02d067823"
)

metrics_backend() { echo "${CONF[METRICS_BACKEND]:-none}"; }

# metrics_kind <backend> - vm|prom, the short name of the pins above.
metrics_kind() {
	case "$1" in
	victoriametrics) echo vm ;;
	prometheus) echo prom ;;
	esac
}

metrics_unit_name() {
	case "$1" in
	victoriametrics) echo "dpistack-vm.service" ;;
	prometheus) echo "prometheus.service" ;;
	esac
}

metrics_port() {
	local p="${CONF[METRICS_BACKEND_PORT]:-}"
	if [[ -n "$p" ]]; then
		echo "$p"
	elif [[ "$1" == "victoriametrics" ]]; then
		echo 8428
	else
		echo 9090
	fi
}

# The backend is not proxied by nginx, so it is reachable only where the
# bind says: 0.0.0.0 in lan mode, 127.0.0.1 otherwise.
metrics_listen() { echo "$(access_effective_bind_host):$(metrics_port "$1")"; }

metrics_version() {
	case "$1" in
	victoriametrics) echo "$METRICS_VM_VERSION" ;;
	prometheus) echo "$METRICS_PROM_VERSION" ;;
	esac
}

metrics_arch() {
	case "${DPISTACK_METRICS_ARCH:-$(uname -m)}" in
	x86_64 | amd64) echo amd64 ;;
	aarch64 | arm64) echo arm64 ;;
	*) return 1 ;;
	esac
}

metrics_runtime() { echo "${CONF[METRICS_BACKEND_RUNTIME]:-native}"; }

# The panel's own listening port: behind nginx it is PORT+10000 over plain
# HTTP, which is what the collector can reach without TLS.
metrics_scrape_target() {
	local host
	host=$(access_effective_bind_host)
	[[ "$host" == "0.0.0.0" ]] && host="127.0.0.1"
	echo "${host}:$(access_backend_port "${CONF[PANEL_PORT]:-9800}")"
}

metrics_render_scrape() {
	render_template "$SCRIPT_DIR/templates/scrape.yaml.tpl" \
		"TOKEN_FILE=$(path_metrics_token)" \
		"TARGET=$(metrics_scrape_target)"
	# node_exporter is scraped by the same backend when it is installed.
	if nodeexp_wanted; then
		printf '  - job_name: node\n    static_configs:\n      - targets: ['"'"'%s'"'"']\n' "$(nodeexp_target)"
	fi
}

metrics_render_unit() {
	local backend="$1" tpl bin
	case "$backend" in
	victoriametrics)
		tpl=dpistack-vm.service.tpl
		bin=$(path_vm_bin)
		;;
	prometheus)
		tpl=prometheus.service.tpl
		bin=$(path_prometheus_bin)
		;;
	esac
	render_template "$SCRIPT_DIR/templates/$tpl" \
		"USER=$METRICS_USER" \
		"BIN=$bin" \
		"DATA_DIR=$(metrics_data_dir "$backend")" \
		"RETENTION=${CONF[METRICS_RETENTION]:-30d}" \
		"LISTEN=$(metrics_listen "$backend")" \
		"SCRAPE=$(path_scrape_yaml)"
}

metrics_data_dir() { echo "$(path_metrics_data_dir)/$1"; }

metrics_unit_path() {
	case "$1" in
	victoriametrics) path_vm_unit ;;
	prometheus) path_prometheus_unit ;;
	esac
}

metrics_bin_path() {
	case "$1" in
	victoriametrics) path_vm_bin ;;
	prometheus) path_prometheus_bin ;;
	esac
}

# What this installer started last: "<runtime>:<backend>[:<version>]".
metrics_installed() { state_read_value "metrics.backend" 2>/dev/null || true; }

metrics_marker() {
	local backend="$1"
	if [[ "$(metrics_runtime)" == "docker" ]]; then
		echo "docker:$backend"
	else
		echo "native:$backend:$(metrics_version "$backend")"
	fi
}

metrics_file_current() {
	local path="$1" content="$2"
	[[ -f "$path" ]] || return 1
	[[ "$(printf '%s\n' "$content" | state_hash_content)" == "$(state_hash_content <"$path")" ]]
}

step_metrics_check() {
	local backend installed
	backend=$(metrics_backend)
	installed=$(metrics_installed)
	if [[ "$backend" == "none" ]]; then
		# A backend started earlier must be stopped.
		[[ -z "$installed" ]]
		return
	fi
	[[ "$installed" == "$(metrics_marker "$backend")" ]] || return 1
	metrics_file_current "$(path_scrape_yaml)" "$(metrics_render_scrape)" || return 1
	if [[ "$(metrics_runtime)" == "docker" ]]; then
		docker_service_check "$backend"
		return
	fi
	[[ -x "$(metrics_bin_path "$backend")" ]] || return 1
	metrics_file_current "$(metrics_unit_path "$backend")" "$(metrics_render_unit "$backend")" || return 1
	systemctl is-active --quiet "$(metrics_unit_name "$backend")"
}

# metrics_stop_installed - stop what the state says was started, whatever
# the backend is now. Data and the token stay.
metrics_stop_installed() {
	local installed runtime backend
	installed=$(metrics_installed)
	[[ -n "$installed" ]] || return 0
	runtime="${installed%%:*}"
	backend="${installed#*:}"
	backend="${backend%%:*}"
	if [[ "$runtime" == "docker" ]]; then
		if command -v docker >/dev/null 2>&1 && [[ -f "$(path_compose_yaml)" ]]; then
			docker_compose_argv
			run "${DOCKER_COMPOSE_ARGV[@]}" rm -fsv "$backend" || return 1
		fi
	else
		run systemctl disable --now "$(metrics_unit_name "$backend")" 2>/dev/null || true
	fi
	return 0
}

# The users and the token file exist before the backend starts: Prometheus
# refuses a config whose credentials_file is missing. The panel step
# writes the same file later with the same owner.
metrics_ensure_users() {
	if ! getent passwd dpistack >/dev/null 2>&1; then
		run useradd --system --no-create-home --shell /usr/sbin/nologin dpistack || return 1
	fi
	if ! getent passwd "$METRICS_USER" >/dev/null 2>&1; then
		run useradd --system --no-create-home --shell /usr/sbin/nologin -G dpistack "$METRICS_USER" || return 1
	fi
	local tfile
	tfile=$(path_metrics_token)
	if panel_token_wanted && [[ ! -s "$tfile" && "${DRY_RUN:-0}" != "1" ]]; then
		printf '%s\n' "${SECRETS[METRICS_TOKEN]}" | atomic_write "$tfile" 0640 || return 1
		run chown "root:dpistack" "$tfile" || return 1
	fi
	return 0
}

# metrics_fetch_binary <backend> - download, verify the sha256, install.
metrics_fetch_binary() {
	local backend="$1" kind arch ver url tmp want got
	kind=$(metrics_kind "$backend")
	arch=$(metrics_arch) || {
		echo "metrics: architecture $(uname -m) is not supported (amd64 or arm64 is needed)" >&2
		return 1
	}
	ver=$(metrics_version "$backend")
	if [[ "$backend" == "victoriametrics" ]]; then
		url="https://github.com/VictoriaMetrics/VictoriaMetrics/releases/download/${ver}/victoria-metrics-linux-${arch}-${ver}.tar.gz"
	else
		url="https://github.com/prometheus/prometheus/releases/download/${ver}/prometheus-${ver#v}.linux-${arch}.tar.gz"
	fi
	local override="DPISTACK_METRICS_SHA256_${kind^^}_${arch^^}"
	want="${!override:-${METRICS_SHA256[${kind}_${arch}]}}"
	tmp=$(mktemp -d)
	if ! run curl --proto '=https' --tlsv1.2 -fsSL -o "$tmp/archive.tar.gz" "$url"; then
		echo "metrics: could not download $url" >&2
		rm -rf "$tmp"
		return 1
	fi
	got=$(sha256sum "$tmp/archive.tar.gz" | awk '{print $1}')
	if [[ "$got" != "$want" ]]; then
		echo "metrics: the checksum of $url did not match (expected $want, got $got), the binary is not installed" >&2
		rm -rf "$tmp"
		return 1
	fi
	run tar -xzf "$tmp/archive.tar.gz" -C "$tmp" || {
		rm -rf "$tmp"
		return 1
	}
	local src
	if [[ "$backend" == "victoriametrics" ]]; then
		src="$tmp/victoria-metrics-prod"
	else
		src="$tmp/prometheus-${ver#v}.linux-${arch}/prometheus"
	fi
	run install -D -m 0755 "$src" "$(metrics_bin_path "$backend")" || {
		rm -rf "$tmp"
		return 1
	}
	rm -rf "$tmp"
	return 0
}

step_metrics_apply() {
	local backend installed marker
	backend=$(metrics_backend)
	installed=$(metrics_installed)
	# A new pinned version (or another runtime) changes the marker: the
	# binary then has to be fetched again, or the state would claim a
	# version the old binary is not.
	local refetch=0
	[[ -n "$installed" && "$installed" != "$(metrics_marker "$backend")" ]] && refetch=1

	# A backend that is no longer wanted (none, or the other one, or the
	# other runtime) is stopped first; its data stays.
	if [[ -n "$installed" && "$installed" != "$(metrics_marker "$backend")" ]]; then
		metrics_stop_installed || return 1
		state_write_value "metrics.backend" "" || return 1
	fi
	[[ "$backend" == "none" ]] && return 0

	metrics_ensure_users || return 1
	local d
	d=$(metrics_data_dir "$backend")
	run install -d -m 0750 "$d" || return 1
	run chown "$METRICS_USER:" "$d" || return 1
	# scrape.yaml holds no secret; the backend user must reach it, and the
	# state directory only has to be traversable, not listable.
	run chmod o+x "$(path_state_dir)" || return 1
	write_rendered_file "$(path_scrape_yaml)" "$(metrics_render_scrape)" 0644 || return 1

	if [[ "$(metrics_runtime)" == "docker" ]]; then
		docker_service_apply "$backend" || return 1
	else
		if [[ ! -x "$(metrics_bin_path "$backend")" || "$refetch" == "1" ]]; then
			metrics_fetch_binary "$backend" || return 1
		fi
		write_rendered_file "$(metrics_unit_path "$backend")" "$(metrics_render_unit "$backend")" || return 1
		run systemctl daemon-reload || return 1
		run systemctl enable --now "$(metrics_unit_name "$backend")" || return 1
		# A changed unit or scrape file is only read after a restart.
		run systemctl restart "$(metrics_unit_name "$backend")" || return 1
	fi
	marker=$(metrics_marker "$backend")
	state_write_value "metrics.backend" "$marker"
}

step_metrics_plan() {
	local backend installed
	backend=$(metrics_backend)
	installed=$(metrics_installed)
	if [[ -n "$installed" && "$installed" != "$(metrics_marker "$backend")" ]]; then
		echo "metrics: stop ${installed} (the data stays)"
	fi
	if [[ "$backend" == "none" ]]; then
		[[ -z "$installed" ]] && echo "metrics: no changes (METRICS_BACKEND=none, only the /metrics endpoint)"
		return 0
	fi
	if [[ "$(metrics_runtime)" == "docker" ]]; then
		docker_service_plan "$backend"
	else
		echo "metrics: $backend $(metrics_version "$backend") from a GitHub release with a sha256 check, unit $(metrics_unit_name "$backend"), listens on $(metrics_listen "$backend"), retention ${CONF[METRICS_RETENTION]:-30d}"
	fi
	echo "metrics: render $(path_scrape_yaml), target $(metrics_scrape_target), token from file $(path_metrics_token)"
}
DPISTACK_BUNDLE_END
put lib/step_ndpi.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# nDPI: NDPI_SOURCE=pkg installs the distro's libndpi-dev, NDPI_SOURCE=source
# clones and builds ntop/nDPI from GitHub (tech.md slice 4).

NDPI_PACKAGE="libndpi-dev"
# The dnf name is set once the family is known (see os_detect).
NDPI_REPO_URL="https://github.com/ntop/nDPI.git"

# Empty NDPI_VERSION means the release the Suricata nDPI plugin builds
# against. Built for real: the plugin in Suricata master compiles with
# nDPI 4.12 and 4.14 only (4.10 and older lack its API, 5.0 and master
# changed it), so master is not a safe default.
NDPI_COMPAT_REF="4.14"

ndpi_target_ref() {
	echo "${CONF[NDPI_VERSION]:-$NDPI_COMPAT_REF}"
}

ndpi_built_ref_state_key() { echo "ndpi.built_ref"; }

ndpi_pkg_installed_version() {
	pkg_installed_version "$NDPI_PACKAGE"
}

ndpi_source_lib_present() {
	[[ -f "$(path_ndpi_lib_dir)/libndpi.so" || -f "$(path_ndpi_lib_dir)/libndpi.a" ]]
}

step_ndpi_check() {
	[[ "${CONF[NDPI_ENABLE]:-no}" == "yes" ]] || return 0

	case "${CONF[NDPI_SOURCE]:-source}" in
	pkg)
		[[ -n "$(ndpi_pkg_installed_version)" ]]
		;;
	source)
		ndpi_source_lib_present || return 1
		local wanted have
		wanted=$(git_ref_commit "$(path_ndpi_src_dir)" "$(ndpi_target_ref)")
		have=$(state_read_value "$(ndpi_built_ref_state_key)")
		[[ -n "$wanted" && "$wanted" == "$have" ]]
		;;
	*)
		return 1
		;;
	esac
}

# ndpi_resolve_source - NDPI_SOURCE=pkg without a libndpi-dev candidate
# switches this run to a source build. Returns 0 when it changed the value.
ndpi_resolve_source() {
	[[ "${CONF[NDPI_ENABLE]:-no}" == "yes" && "${CONF[NDPI_SOURCE]:-source}" == "pkg" ]] || return 1
	[[ -z "$(ndpi_pkg_installed_version)" ]] || return 1
	pkg_available "$NDPI_PACKAGE" && return 1
	echo "ndpi: package $NDPI_PACKAGE is not in the repositories, NDPI_SOURCE=pkg is replaced by source (build from source)" >&2
	CONF[NDPI_SOURCE]=source
}

ndpi_build_from_source() {
	local src_dir ref
	src_dir=$(path_ndpi_src_dir)
	pkg_build_deps ndpi || return 1
	ref=$(ndpi_target_ref)

	if [[ ! -d "$src_dir/.git" ]]; then
		run git clone "$NDPI_REPO_URL" "$src_dir" || return 1
	else
		run git -C "$src_dir" fetch --tags origin || return 1
	fi

	run git -C "$src_dir" checkout "$ref" || return 1

	local resolved_ref
	resolved_ref=$(git -C "$src_dir" rev-parse HEAD 2>/dev/null)

	(
		cd "$src_dir" || exit 1
		run ./autogen.sh &&
			run ./configure --prefix=/usr/local &&
			run make -j"$(nproc)" &&
			run make install
	)
	local rc=$?
	if [[ "$rc" -ne 0 ]]; then
		echo "nDPI: the build from source failed (autogen/configure/make), see the output above" >&2
		return 1
	fi

	[[ "${DRY_RUN:-0}" != "1" ]] && run ldconfig
	[[ -n "$resolved_ref" ]] && state_write_value "$(ndpi_built_ref_state_key)" "$resolved_ref"
	return 0
}

step_ndpi_apply() {
	if [[ "${CONF[NDPI_ENABLE]:-no}" != "yes" ]]; then
		return 0
	fi

	case "${CONF[NDPI_SOURCE]:-source}" in
	pkg)
		pkg_install "$NDPI_PACKAGE" || return 1
		;;
	source)
		ndpi_build_from_source
		;;
	*)
		echo "NDPI_SOURCE=${CONF[NDPI_SOURCE]}: unknown source" >&2
		return 1
		;;
	esac
}

step_ndpi_plan() {
	if [[ "${CONF[NDPI_ENABLE]:-no}" != "yes" ]]; then
		echo "ndpi: NDPI_ENABLE=no, no changes"
		return 0
	fi
	case "${CONF[NDPI_SOURCE]:-source}" in
	pkg) echo "ndpi: installing the package $NDPI_PACKAGE" ;;
	source) echo "ndpi: build from source ($NDPI_REPO_URL, ref=$(ndpi_target_ref | sed 's/^$/HEAD/'))" ;;
	esac
}
DPISTACK_BUNDLE_END
put lib/step_nodeexp.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# node_exporter: host metrics (CPU, memory, disk, network) for the metrics
# backend. Optional (NODE_EXPORTER_ENABLE), native or docker. The native
# binary comes from the project's GitHub release with a pinned sha256
# (DPISTACK_NODEEXP_* override the pins for tests and for moving to a newer
# release by hand).

MONITOR_USER="dpistack-monitor"
NODEEXP_VERSION="${DPISTACK_NODEEXP_VERSION:-v1.12.1}"
declare -A NODEEXP_SHA256=(
	[amd64]="b51d8a76aa2a9156a55d501aca6276fae09e262259a5e4e831d2c2222f084e63"
	[arm64]="ad35b605f9954b9f1ffddf5ba054bdc5a98d790b9eae5291e1eeb83f1ecbd0e7"
)

nodeexp_wanted() { [[ "${CONF[NODE_EXPORTER_ENABLE]:-no}" == "yes" ]]; }
nodeexp_runtime() { echo "${CONF[NODE_EXPORTER_RUNTIME]:-native}"; }
nodeexp_port() { echo "${CONF[NODE_EXPORTER_PORT]:-9100}"; }
nodeexp_listen() { echo "$(access_effective_bind_host):$(nodeexp_port)"; }

# nodeexp_target - where the metrics backend scrapes it (same host).
nodeexp_target() { echo "$(access_connect_host):$(nodeexp_port)"; }

nodeexp_marker() {
	if [[ "$(nodeexp_runtime)" == "docker" ]]; then
		echo "docker:node_exporter"
	else
		echo "native:node_exporter:${NODEEXP_VERSION}"
	fi
}
nodeexp_installed() { state_read_value "nodeexp.installed" 2>/dev/null || true; }

nodeexp_render_unit() {
	render_template "$SCRIPT_DIR/templates/node-exporter.service.tpl" \
		"USER=$MONITOR_USER" "BIN=$(path_nodeexp_bin)" "LISTEN=$(nodeexp_listen)"
}

nodeexp_arch() {
	case "${DPISTACK_METRICS_ARCH:-$(uname -m)}" in
	x86_64 | amd64) echo amd64 ;;
	aarch64 | arm64) echo arm64 ;;
	*) return 1 ;;
	esac
}

# monitor_ensure_user - the system user of node_exporter and Grafana.
monitor_ensure_user() {
	getent passwd "$MONITOR_USER" >/dev/null 2>&1 && return 0
	run useradd --system --no-create-home --shell /usr/sbin/nologin "$MONITOR_USER"
}

nodeexp_fetch_binary() {
	local arch ver url tmp want got
	arch=$(nodeexp_arch) || {
		echo "node_exporter: architecture $(uname -m) is not supported (amd64 or arm64 is needed)" >&2
		return 1
	}
	ver="$NODEEXP_VERSION"
	url="https://github.com/prometheus/node_exporter/releases/download/${ver}/node_exporter-${ver#v}.linux-${arch}.tar.gz"
	local override="DPISTACK_NODEEXP_SHA256_${arch^^}"
	want="${!override:-${NODEEXP_SHA256[$arch]}}"
	tmp=$(mktemp -d)
	if ! run curl --proto '=https' --tlsv1.2 -fsSL -o "$tmp/archive.tar.gz" "$url"; then
		echo "node_exporter: could not download $url" >&2
		rm -rf "$tmp"
		return 1
	fi
	got=$(sha256sum "$tmp/archive.tar.gz" | awk '{print $1}')
	if [[ "$got" != "$want" ]]; then
		echo "node_exporter: the checksum of $url did not match (expected $want, got $got), the binary is not installed" >&2
		rm -rf "$tmp"
		return 1
	fi
	run tar -xzf "$tmp/archive.tar.gz" -C "$tmp" || {
		rm -rf "$tmp"
		return 1
	}
	run install -D -m 0755 "$tmp/node_exporter-${ver#v}.linux-${arch}/node_exporter" "$(path_nodeexp_bin)" || {
		rm -rf "$tmp"
		return 1
	}
	rm -rf "$tmp"
}

nodeexp_stop_installed() {
	local installed runtime
	installed=$(nodeexp_installed)
	[[ -n "$installed" ]] || return 0
	runtime="${installed%%:*}"
	if [[ "$runtime" == "docker" ]]; then
		if command -v docker >/dev/null 2>&1 && [[ -f "$(path_compose_yaml)" ]]; then
			docker_compose_argv
			run "${DOCKER_COMPOSE_ARGV[@]}" rm -fsv node_exporter || return 1
		fi
	else
		run systemctl disable --now "dpistack-node-exporter.service" 2>/dev/null || true
	fi
	return 0
}

step_nodeexp_check() {
	local installed
	installed=$(nodeexp_installed)
	if ! nodeexp_wanted; then
		[[ -z "$installed" ]]
		return
	fi
	[[ "$installed" == "$(nodeexp_marker)" ]] || return 1
	if [[ "$(nodeexp_runtime)" == "docker" ]]; then
		docker_service_check node_exporter
		return
	fi
	[[ -x "$(path_nodeexp_bin)" ]] || return 1
	metrics_file_current "$(path_nodeexp_unit)" "$(nodeexp_render_unit)" || return 1
	systemctl is-active --quiet "dpistack-node-exporter.service"
}

step_nodeexp_apply() {
	local installed refetch=0
	installed=$(nodeexp_installed)
	if [[ -n "$installed" ]] && { ! nodeexp_wanted || [[ "$installed" != "$(nodeexp_marker)" ]]; }; then
		refetch=1
		nodeexp_stop_installed || return 1
		state_write_value "nodeexp.installed" "" || return 1
	fi
	nodeexp_wanted || return 0

	if [[ "$(nodeexp_runtime)" == "docker" ]]; then
		docker_service_apply node_exporter || return 1
	else
		monitor_ensure_user || return 1
		if [[ ! -x "$(path_nodeexp_bin)" || "$refetch" == "1" ]]; then
			nodeexp_fetch_binary || return 1
		fi
		write_rendered_file "$(path_nodeexp_unit)" "$(nodeexp_render_unit)" || return 1
		run systemctl daemon-reload || return 1
		run systemctl enable --now "dpistack-node-exporter.service" || return 1
		run systemctl restart "dpistack-node-exporter.service" || return 1
	fi
	state_write_value "nodeexp.installed" "$(nodeexp_marker)"
}

step_nodeexp_plan() {
	local installed
	installed=$(nodeexp_installed)
	if [[ -n "$installed" ]] && { ! nodeexp_wanted || [[ "$installed" != "$(nodeexp_marker)" ]]; }; then
		echo "nodeexp: stop ${installed}"
	fi
	if ! nodeexp_wanted; then
		[[ -z "$installed" ]] && echo "nodeexp: no changes (NODE_EXPORTER_ENABLE=no)"
		return 0
	fi
	if [[ "$(nodeexp_runtime)" == "docker" ]]; then
		docker_service_plan node_exporter
	else
		echo "nodeexp: node_exporter ${NODEEXP_VERSION} from a GitHub release with a sha256 check, unit dpistack-node-exporter.service, listens on $(nodeexp_listen)"
	fi
}
DPISTACK_BUNDLE_END
put lib/step_ntopng.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# ntopng: ntop.org apt repo, ntopng package, ntopng.conf rendered from
# NTOPNG_IFACES/NTOPNG_PORT. Bind address comes from
# access_effective_bind_host (lib/step_access.sh, slice 7): 127.0.0.1
# for localhost/nginx modes, 0.0.0.0 for lan.

NTOPNG_PACKAGE="ntopng"
NTOPNG_UNIT="ntopng.service"
# The stable channel (apt-stable). "apt" next to it is the development one:
# nightly builds of the master branch, not for a security tool.
NTOP_REPO_DEB_URL_APT="https://packages.ntop.org/apt-stable"
NTOP_REPO_RPM_URL="https://packages.ntop.org/centos-stable/ntop.repo"

ntopng_effective_ifaces() {
	# criterion 2: NTOPNG_IFACES defaults to IFACES, an explicit value
	# (schema.sh default is empty) overrides it.
	local v="${CONF[NTOPNG_IFACES]:-}"
	if [[ -z "$v" ]]; then
		echo "${CONF[IFACES]:-}"
	else
		echo "$v"
	fi
}

ntopng_render_interfaces_block() {
	local ifaces
	ifaces=$(ntopng_effective_ifaces)
	local iface
	local IFS=','
	for iface in $ifaces; do
		[[ -z "$iface" ]] && continue
		echo "-i=${iface}"
	done
}

ntopng_render_conf() {
	render_template "$SCRIPT_DIR/templates/ntopng.conf.tpl" \
		"NTOPNG_INTERFACES=$(ntopng_render_interfaces_block)" \
		"NTOPNG_BIND=$(access_effective_bind_host):$(access_backend_port "${CONF[NTOPNG_PORT]:-3000}")" \
		"NTOPNG_PIDFILE=$(path_ntopng_pidfile)"
}

# ntop.org publishes one rpm repo for the RHEL clones (EPEL comes from
# pkg_enable_extra_repos). Fedora and Amazon Linux are not in its list:
# there ntopng has to come from the distribution itself.
ntopng_repo_add_rpm() {
	case "$OS_ID" in
	rocky | almalinux | centos | rhel | ol)
		run curl -fsSL "$NTOP_REPO_RPM_URL" -o "$(path_ntop_repo_file)" || return 1
		run dnf -y makecache || return 1
		;;
	*)
		pkg_available "$NTOPNG_PACKAGE" || {
			echo "ntopng: ntop.org does not publish a repository for $OS_ID and the distribution has no package; the step can be skipped: --skip ntopng" >&2
			return 1
		}
		;;
	esac
}

ntopng_repo_add() {
	if [[ "$OS_FAMILY" == "dnf" ]]; then
		ntopng_repo_add_rpm
		return
	fi
	# Real, documented ntop.org install sequence (packages.ntop.org):
	# add universe (Ubuntu only), fetch the tiny apt-ntop.deb that
	# registers the repo + imports the GPG key, then apt update.
	# Debian has no universe component, only Ubuntu does.
	if [[ "$OS_ID" == "ubuntu" ]]; then
		run add-apt-repository -y universe || return 1
	else
		# ntop.org: on Debian add "contrib" to every deb and deb-src line.
		apt_enable_component contrib
	fi
	# ntop.org names the Ubuntu repos by version (apt/24.04) and the
	# Debian ones by release name (apt/bookworm); apt/12 does not exist.
	local version_id
	# shellcheck disable=SC1090
	if [[ "$OS_ID" == "ubuntu" ]]; then
		version_id=$(. "$(path_os_release)" && echo "${VERSION_ID:-}")
	else
		version_id=$(. "$(path_os_release)" && echo "${VERSION_CODENAME:-}")
	fi
	if [[ -z "$version_id" ]]; then
		log "ERROR" "ntopng: os-release has no version or release name for the ntop.org repository"
		return 1
	fi
	local deb_tmp
	deb_tmp="$(mktemp --suffix=.deb)"
	if ! run wget -qO "$deb_tmp" "${NTOP_REPO_DEB_URL_APT}/${version_id}/all/apt-ntop-stable.deb" ||
		! run apt-get install -y "$deb_tmp"; then
		rm -f "$deb_tmp"
		return 1
	fi
	rm -f "$deb_tmp"
	run apt-get update || return 1
}

step_ntopng_check() {
	if docker_wanted ntopng; then
		[[ -f "$(path_ntopng_conf)" ]] || return 1
		[[ "$(ntopng_render_conf | state_hash_content)" == "$(state_hash_content <"$(path_ntopng_conf)")" ]] || return 1
		docker_service_check ntopng
		return
	fi
	command -v ntopng >/dev/null 2>&1 || return 1

	local conf_path
	conf_path=$(path_ntopng_conf)
	[[ -f "$conf_path" ]] || return 1
	local expected_hash actual_hash
	expected_hash=$(ntopng_render_conf | state_hash_content)
	actual_hash=$(state_hash_content <"$conf_path")
	[[ "$expected_hash" == "$actual_hash" ]] || return 1

	systemctl is-active --quiet "$NTOPNG_UNIT" || return 1
	return 0
}

step_ntopng_apply() {
	if docker_wanted ntopng; then
		runtime_release_native "$NTOPNG_UNIT" || return 1
		write_rendered_file "$(path_ntopng_conf)" "$(ntopng_render_conf)" || return 1
		docker_service_apply ntopng || return 1
		echo "ntopng: in a container, default login/password admin/admin, listens on $(access_effective_bind_host):$(access_backend_port "${CONF[NTOPNG_PORT]:-3000}") - change the password in the web interface." >&2
		return 0
	fi
	runtime_release_docker ntopng || return 1
	if ! command -v ntopng >/dev/null 2>&1; then
		ntopng_repo_add || return 1
		pkg_install "$(pkg_spec "$NTOPNG_PACKAGE" "${CONF[NTOPNG_VERSION]:-}")" || return 1
	fi

	write_rendered_file "$(path_ntopng_conf)" "$(ntopng_render_conf)"

	# The ntopng policy module only lets ntop_t bind ntop_port_t (3000 and
	# 3001); in nginx mode the service listens on PORT+10000 and a custom
	# NTOPNG_PORT is the same case.
	local ntopng_listen
	ntopng_listen=$(access_backend_port "${CONF[NTOPNG_PORT]:-3000}")
	[[ "$ntopng_listen" == "3000" || "$ntopng_listen" == "3001" ]] || selinux_port ntop_port_t "$ntopng_listen"

	run systemctl enable --now "$NTOPNG_UNIT" || return 1

	# A4: there is no dpistack.conf key to set a real ntopng password
	# from here, so the default admin/admin credential is only ever
	# safe when access_effective_bind_host keeps this on 127.0.0.1;
	# step_access.sh prints its own louder warning for lan/nginx modes.
	echo "ntopng: default login/password admin/admin, listens on $(access_effective_bind_host):$(access_backend_port "${CONF[NTOPNG_PORT]:-3000}") - change the password in the web interface." >&2

	return 0
}

step_ntopng_plan() {
	if docker_wanted ntopng; then
		docker_service_plan ntopng
		echo "ntopng: render $(path_ntopng_conf), port ${CONF[NTOPNG_PORT]:-3000} (service on $(access_backend_port "${CONF[NTOPNG_PORT]:-3000}")), bind $(access_effective_bind_host)"
		return 0
	fi
	echo "ntopng: interfaces $(ntopng_effective_ifaces), port ${CONF[NTOPNG_PORT]:-3000} (service on $(access_backend_port "${CONF[NTOPNG_PORT]:-3000}")), bind $(access_effective_bind_host)"
	echo "ntopng: render $(path_ntopng_conf)"
}
DPISTACK_BUNDLE_END
put lib/step_panel.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# "panel" step: the system user `dpistack`, the sudoers rule that lets it
# run only dpistack (tech.md 4.2, 4.5), the panel binary (PANEL_SOURCE:
# built from panel/ with Go, or a ready dpistack-panel next to install.sh)
# and the systemd unit (tech.md 9). PANEL_EDITION picks the panel: full, or
# lite with the same features and a plain, light page.

PANEL_USER="dpistack"
PANEL_SERVICE="dpistack-panel.service"
PANEL_SRC_HASH_KEY="panel.src_hash"

# panel_prebuilt_path - the ready binary next to install.sh: the one for
# this CPU (dpistack-panel-linux-amd64 or -arm64, as the release archive
# ships them), else a plain dpistack-panel. When neither exists it names
# the file a release archive would have, for messages.
panel_prebuilt_path() {
	local arch f
	case "$(uname -m)" in
	x86_64) arch=amd64 ;;
	aarch64 | arm64) arch=arm64 ;;
	*) arch=$(uname -m) ;;
	esac
	for f in "$ORIGIN_DIR/dpistack-panel-linux-$arch" "$ORIGIN_DIR/dpistack-panel"; do
		if [[ -f "$f" ]]; then
			echo "$f"
			return 0
		fi
	done
	echo "$ORIGIN_DIR/dpistack-panel-linux-$arch"
}

# panel_source_mode - build or prebuilt. auto (the default) takes the ready
# binary when one lies next to install.sh, as in a release archive, and
# builds from panel/ otherwise, as in a git checkout.
panel_source_mode() {
	case "${CONF[PANEL_SOURCE]:-auto}" in
	auto)
		if [[ -f "$(panel_prebuilt_path)" ]]; then
			echo prebuilt
		else
			echo build
		fi
		;;
	*) echo "${CONF[PANEL_SOURCE]}" ;;
	esac
}

# panel_src_hash - one hash over everything the binary is built from, so
# a changed source or web file rebuilds it and an unchanged one does not.
panel_src_hash() {
	[[ -d "$ORIGIN_DIR/panel" ]] || return 1
	(cd "$ORIGIN_DIR/panel" &&
		find . -type f \( -name '*.go' -o -name go.mod -o -name go.sum -o -path './web/*' \) -print0 |
		sort -z | xargs -0 sha256sum | sha256sum | cut -d' ' -f1)
}

# panel_token_wanted - 0 when GET /metrics is on and there is a token to guard
# it. The token reaches the panel through a file: a flag would show in ps
# and in the unit.
panel_token_wanted() {
	[[ "${CONF[METRICS_EXPORT]:-yes}" == "yes" && -n "${SECRETS[METRICS_TOKEN]:-}" ]]
}

# panel_token_matches - the token file holds the current token when /metrics
# is on, and does not exist when it is off.
panel_token_matches() {
	local file
	file=$(path_metrics_token)
	if panel_token_wanted; then
		[[ -f "$file" && "$(<"$file")" == "${SECRETS[METRICS_TOKEN]}" ]]
	else
		[[ ! -e "$file" ]]
	fi
}

# panel_is_lite - 0 when PANEL_EDITION=lite.
panel_is_lite() {
	[[ "${CONF[PANEL_EDITION]:-full}" == "lite" ]]
}

# panel_args - the flags of the panel (tech.md 9). The panel does not read
# dpistack.conf, so LAN_CIDR=auto is resolved here.
panel_args() {
	local mode port
	mode=$(access_policy)
	port=$(access_backend_port "${CONF[PANEL_PORT]:-9800}")
	local host args cidr=""
	host=$(access_effective_bind_host)
	if [[ "$mode" != "localhost" ]]; then
		cidr=$(access_effective_lan_cidr) || cidr=""
		if [[ "$mode" == "lan" && -z "$cidr" ]]; then
			# The same closed fallback as the access step: nobody but the
			# host itself gets in until LAN_CIDR is set by hand.
			echo "panel: LAN_CIDR cannot be determined, the panel is open for 127.0.0.1 only (set LAN_CIDR)" >&2
			cidr="127.0.0.1/32"
		fi
	fi
	args="-addr ${host}:${port} -access ${mode}"
	[[ -n "$cidr" ]] && args+=" -lan-cidr ${cidr}"
	args+=" -auth-file $(path_panel_auth) -health-file $(path_health_json) -ctl $(path_ctl_bin) -metrics-file $(path_metrics_json)"
	args+=" -version ${DPISTACK_VERSION}"
	panel_is_lite && args+=" -lite"
	# Without the flag the panel shows that viewing events is off.
	[[ "${CONF[EVE_FILE]:-yes}" == "yes" ]] && args+=" -eve-file $(path_suricata_eve_json)"
	# The Tests and Alerts screens read these two files whatever /metrics does.
	args+=" -tests-file $(path_tests_last_json) -events-file $(path_events_jsonl)"
	# Without a token file /metrics does not exist (404).
	if panel_token_wanted; then
		local disks
		disks=$(dirname "$(path_suricata_eve_json)")
		[[ "${CONF[EVEBOX_DB]:-sqlite}" == "sqlite" ]] && disks+=",$(path_evebox_data_dir)"
		args+=" -metrics-token-file $(path_metrics_token) -rules-file $(path_suricata_ruleset) -disk-paths ${disks}"
	fi
	echo "$args"
}

panel_render_service() {
	local args
	args=$(panel_args) || return 1
	render_template "$SCRIPT_DIR/templates/dpistack-panel.service.tpl" \
		"USER=$PANEL_USER" \
		"PANEL_BIN=$(path_panel_bin)" \
		"ARGS=$args"
}

panel_unit_matches() {
	local path expected
	path=$(path_panel_service_unit)
	[[ -f "$path" ]] || return 1
	expected=$(panel_render_service) || return 1
	[[ "$(printf '%s\n' "$expected" | state_hash_content)" == "$(state_hash_content <"$path")" ]]
}

# panel_bin_current - the installed binary is the one this run would install.
panel_bin_current() {
	local bin src
	bin=$(path_panel_bin)
	[[ -x "$bin" ]] || return 1
	if [[ "$(panel_source_mode)" == "prebuilt" ]]; then
		# Run from the installed copy (dpistack reconfigure) there is no
		# ready binary next to the script any more: what is installed stays.
		[[ -f "$(panel_prebuilt_path)" ]] || return 0
		cmp -s "$(panel_prebuilt_path)" "$bin"
		return
	fi
	# Without the sources (an installer copy) there is nothing to rebuild from.
	src=$(panel_src_hash) || return 0
	[[ "$(state_read_value "$PANEL_SRC_HASH_KEY")" == "$src" ]]
}

# panel_go_required - the Go version panel/go.mod asks for (empty without sources).
panel_go_required() {
	awk '/^go /{print $2; exit}' "$ORIGIN_DIR/panel/go.mod" 2>/dev/null
}

# panel_host_go_ok - 0 when the host has a Go that is not older than go.mod asks.
panel_host_go_ok() {
	command -v go >/dev/null 2>&1 || return 1
	local need have
	need=$(panel_go_required)
	have=$(go version 2>/dev/null | sed -n 's/^go version go\([0-9][0-9.]*\).*/\1/p')
	[[ -n "$have" ]] || return 1
	[[ -z "$need" ]] && return 0
	[[ "$(printf '%s\n%s\n' "$need" "$have" | sort -V | head -1)" == "$need" ]]
}

# panel_go_image - the Go image that builds the panel in a container when the
# host has no suitable Go (golang:1.26 for go 1.26.0). DPISTACK_GO_IMAGE
# overrides it.
panel_go_image() {
	local need
	need=$(panel_go_required)
	echo "${DPISTACK_GO_IMAGE:-golang:${need%.*}}"
}

# panel_can_build_in_container - Docker is there and its daemon answers, so
# Go on the host is not needed.
panel_can_build_in_container() {
	command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1
}

# panel_build_in_container <out-file> - the same go build, inside the Go
# image: the sources are mounted read-only, the caches and the result live in
# one scratch directory (the installer runs as root, so is the container).
panel_build_in_container() {
	local out="$1" dir
	dir=$(mktemp -d) || return 1
	if ! run docker run --rm -v "$ORIGIN_DIR/panel:/src:ro" -v "$dir:/out" -w /src \
		-e CGO_ENABLED=0 -e GOCACHE=/out/gocache -e GOMODCACHE=/out/gomod -e GOFLAGS=-buildvcs=false \
		"$(panel_go_image)" go build -trimpath -ldflags "-s -w" -o /out/dpistack-panel ./cmd/panel; then
		rm -rf "$dir"
		return 1
	fi
	if [[ "${DRY_RUN:-0}" != "1" ]]; then
		install -m 0755 "$dir/dpistack-panel" "$out" || {
			rm -rf "$dir"
			return 1
		}
	fi
	rm -rf "$dir"
	return 0
}

panel_bin_install() {
	local bin tmp
	bin=$(path_panel_bin)
	if [[ "$(panel_source_mode)" == "prebuilt" ]]; then
		run install -D -m 0755 "$(panel_prebuilt_path)" "$bin" || return 1
		return 0
	fi
	tmp=$(mktemp) || return 1
	if panel_host_go_ok; then
		if ! (cd "$ORIGIN_DIR/panel" &&
			run env CGO_ENABLED=0 go build -trimpath -ldflags "-s -w" -o "$tmp" ./cmd/panel); then
			rm -f "$tmp"
			log "ERROR" "panel: the build failed (see the Go output above; a ready binary: PANEL_SOURCE=prebuilt)"
			return 1
		fi
	elif panel_can_build_in_container; then
		# The host Go is missing or too old: build in the Go image.
		log "INFO" "panel: no suitable Go on the host, building in the container $(panel_go_image)"
		if ! panel_build_in_container "$tmp"; then
			rm -f "$tmp"
			log "ERROR" "panel: the build in the container $(panel_go_image) failed (see the output above; a ready binary: PANEL_SOURCE=prebuilt)"
			return 1
		fi
	else
		rm -f "$tmp"
		log "ERROR" "panel: no Go $(panel_go_required) on the host and no Docker to build in (install either, or use a ready binary: PANEL_SOURCE=prebuilt)"
		return 1
	fi
	run install -D -m 0755 "$tmp" "$bin" || {
		rm -f "$tmp"
		return 1
	}
	rm -f "$tmp"
	[[ "${DRY_RUN:-0}" == "1" ]] || state_write_value "$PANEL_SRC_HASH_KEY" "$(panel_src_hash)"
	return 0
}

panel_render_sudoers() {
	render_template "$SCRIPT_DIR/templates/sudoers.tpl" \
		"PANEL_USER=$PANEL_USER" \
		"CTL_BIN=$(path_ctl_bin)"
}

step_panel_check() {
	getent passwd "$PANEL_USER" >/dev/null 2>&1 || return 1

	local path
	path=$(path_sudoers)
	[[ -f "$path" ]] || return 1
	local expected actual
	expected=$(panel_render_sudoers | state_hash_content)
	actual=$(state_hash_content <"$path")
	[[ "$expected" == "$actual" ]] || return 1
	[[ "$(stat -c %a "$path")" == "440" ]] || return 1

	[[ -f "$(path_metrics_json)" ]] || return 1
	panel_token_matches || return 1
	panel_bin_current || return 1
	if docker_wanted panel; then
		docker_service_check panel || return 1
		# the native unit must be gone, or it would hold the port
		[[ "$(systemctl is-active "$PANEL_SERVICE" 2>/dev/null)" != "active" ]] || return 1
	else
		panel_unit_matches || return 1
		# a container left from PANEL_RUNTIME=docker would hold the port
		if [[ -f "$(path_compose_yaml)" ]] && docker_service_running panel 2>/dev/null; then
			return 1
		fi
	fi
	return 0
}

step_panel_apply() {
	if ! getent passwd "$PANEL_USER" >/dev/null 2>&1; then
		run useradd --system --no-create-home --shell /usr/sbin/nologin "$PANEL_USER" || return 1
	fi
	# eve.json belongs to the suricata group (4.2: the user reads it).
	if getent group suricata >/dev/null 2>&1; then
		run usermod -a -G suricata "$PANEL_USER" || return 1
	fi

	# panel.auth is written before this step, when the group is missing.
	if [[ -f "$(path_panel_auth)" ]]; then
		run chown root:dpistack "$(path_panel_auth)" || return 1
	fi

	# The panel keeps its graph history in metrics.json and may write nothing
	# else in the state directory (health.json, state and the backups stay
	# root's), so only this one file is its own. An existing history is kept.
	local mfile
	mfile=$(path_metrics_json)
	if [[ ! -e "$mfile" ]]; then
		run install -D -m 0640 /dev/null "$mfile" || return 1
	fi
	run chown "$PANEL_USER:$PANEL_USER" "$mfile" || return 1

	# The bearer token of /metrics: readable by the panel, nobody else. In a
	# dry run only the fact is printed, never the value.
	local tfile
	tfile=$(path_metrics_token)
	if panel_token_wanted; then
		if [[ "${DRY_RUN:-0}" == "1" ]]; then
			echo "+ write $tfile (0640 root:$PANEL_USER)"
		else
			printf '%s\n' "${SECRETS[METRICS_TOKEN]}" | atomic_write "$tfile" 0640 || return 1
			run chown "root:$PANEL_USER" "$tfile" || return 1
		fi
	else
		run rm -f "$tfile" || return 1
	fi

	# A broken sudoers file locks sudo out, so visudo checks a temp copy
	# before anything lands in /etc/sudoers.d.
	local content tmp
	content=$(panel_render_sudoers) || return 1
	if [[ "${DRY_RUN:-0}" != "1" ]]; then
		tmp=$(mktemp)
		printf '%s\n' "$content" >"$tmp"
		if ! visudo -cf "$tmp" >&2; then
			rm -f "$tmp"
			log "ERROR" "panel: visudo rejected the sudoers rule"
			return 1
		fi
		rm -f "$tmp"
	fi
	write_rendered_file "$(path_sudoers)" "$content" 0440
	run chmod 0440 "$(path_sudoers)" || return 1

	# A changed binary or unit needs a restart; a first install only a start.
	local restart=0
	panel_bin_current || {
		panel_bin_install || return 1
		restart=1
	}
	# PANEL_RUNTIME=docker: the panel is a compose service. The native unit
	# goes first (it would hold the port), the image is built from the binary
	# that was just installed, and compose recreates the container when the
	# image or the flags changed.
	if docker_wanted panel; then
		runtime_release_native "$PANEL_SERVICE" || return 1
		run rm -f "$(path_panel_service_unit)" || return 1
		run systemctl daemon-reload || return 1
		docker_service_apply panel || return 1
		return 0
	fi
	runtime_release_docker panel || return 1
	panel_unit_matches || restart=1
	local unit
	unit=$(panel_render_service) || return 1
	write_rendered_file "$(path_panel_service_unit)" "$unit"
	run systemctl daemon-reload || return 1
	run systemctl enable --now "$PANEL_SERVICE" || return 1
	if [[ "$restart" == "1" ]]; then
		run systemctl restart "$PANEL_SERVICE" || return 1
	fi
	return 0
}

step_panel_plan() {
	if docker_wanted panel; then
		echo "panel: user $PANEL_USER, sudoers $(path_sudoers) (dpistack only), binary $(path_panel_bin) (PANEL_SOURCE=$(panel_source_mode)), $(docker_service_plan panel)"
		return 0
	fi
	echo "panel: user $PANEL_USER, sudoers $(path_sudoers) (dpistack only), binary $(path_panel_bin) (PANEL_SOURCE=$(panel_source_mode)), unit $PANEL_SERVICE"
}

# panel_report_metrics - the token of /metrics and a scrape_config entry
# ready to paste, printed once when the token has just been made. Never in a
# dry run: the token does not exist then.
panel_report_metrics() {
	[[ "${METRICS_TOKEN_JUST_GENERATED:-0}" == "1" && "${DRY_RUN:-0}" != "1" ]] || return 0
	panel_token_wanted || return 0
	local mode="${CONF[ACCESS_MODE]:-localhost}" port="${CONF[PANEL_PORT]:-9800}" scheme="http" host
	host=$(access_effective_bind_host)
	if [[ "$mode" == "lan" && "$host" == "0.0.0.0" ]] || [[ "$mode" == "nginx" ]]; then
		host="<server-address>"
	fi
	[[ "$mode" == "nginx" && "${CONF[NGINX_TLS]:-none}" != "none" ]] && scheme="https"
	echo "METRICS_TOKEN created for GET /metrics (save it: it is shown nowhere else): ${SECRETS[METRICS_TOKEN]}"
	echo "Line for scrape_configs (Prometheus and VictoriaMetrics):"
	cat <<EOF
  - job_name: dpistack
    metrics_path: /metrics
    scheme: ${scheme}
    authorization:
      type: Bearer
      credentials: ${SECRETS[METRICS_TOKEN]}
    static_configs:
      - targets: ['${host}:${port}']
EOF
}
DPISTACK_BUNDLE_END
put lib/step_preflight.sh 644 <<'DPISTACK_BUNDLE_END'
#!/usr/bin/env bash
# Real preflight (tech.md 5.5). Runs once, before any package gets
# installed; collects every failure reason instead of stopping at the
# first one (install.sh's cmd_install dies with all of them, code 3).

# preflight_step_wanted <step> - the step is part of this run (--skip and
# --only are honoured when the installer has parsed them).
preflight_step_wanted() {
	if declare -F step_selected >/dev/null 2>&1; then
		step_selected "$1"
	else
		return 0
	fi
}

# preflight_port_busy <port> - something already listens on the port.
preflight_port_busy() {
	ss -ltn 2>/dev/null | awk '{print $4}' | grep -q ":${1}\$"
}

# preflight_port_owner <port> - the name of the process that listens on the
# port, empty when it cannot be seen (ss shows other users' sockets only to
# root, and the installer is root).
preflight_port_owner() {
	ss -ltnp 2>/dev/null | awk -v p=":${1}$" '$4 ~ p {print $NF}' |
		sed -n 's/.*users:(("\([^"]*\)".*/\1/p' | head -n 1
}

# PREFLIGHT_PORT_KEYS - every port key of dpistack.conf, with the step that
# owns it (the owner's check says whether the port is dpistack's own).
PREFLIGHT_PORT_KEYS=(NTOPNG_PORT:ntopng EVEBOX_PORT:evebox PANEL_PORT:panel METRICS_BACKEND_PORT:metrics)

# preflight_port_taken_by_conf <port> <skip-key> - another key of the
# configuration already uses this port, as a public port or, with nginx, as
# the port behind it.
preflight_port_taken_by_conf() {
	local port="$1" skip="$2" pair key value
	for pair in "${PREFLIGHT_PORT_KEYS[@]}"; do
		key="${pair%%:*}"
		[[ "$key" == "$skip" ]] && continue
		value="${CONF[$key]:-}"
		[[ -z "$value" ]] && continue
		[[ "$value" == "$port" ]] && return 0
		if [[ "$key" != "METRICS_BACKEND_PORT" && "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]] &&
			[[ "$(access_backend_port "$value")" == "$port" ]]; then
			return 0
		fi
	done
	return 1
}

# preflight_free_port <key> <from> - the first port from <from> upward that
# nothing listens on and no other key of the configuration uses. With nginx
# the port behind nginx (PORT+10000) has to be free too. Empty when none.
preflight_free_port() {
	local key="$1" candidate="$2" backend
	while ((candidate <= 65535)); do
		if ! preflight_port_busy "$candidate" && ! preflight_port_taken_by_conf "$candidate" "$key"; then
			if [[ "$key" != "METRICS_BACKEND_PORT" && "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]]; then
				backend=$(access_backend_port "$candidate")
				if ((backend <= 65535)) && ! preflight_port_busy "$backend" && ! preflight_port_taken_by_conf "$backend" "$key"; then
					echo "$candidate"
					return 0
				fi
			else
				echo "$candidate"
				return 0
			fi
		fi
		candidate=$((candidate + 1))
	done
	return 1
}

# preflight_port_conflicts - one line per busy port: KEY|port|who|suggestion.
# A port held by a service dpistack already installed is not a conflict on a
# repeat run, so ports whose step is already applied are skipped. With
# ACCESS_MODE=nginx both ports matter: nginx takes the public one (the
# access step owns it), the service takes public+10000.
preflight_port_conflicts() {
	local pair port_key owner_step public port who
	for pair in "${PREFLIGHT_PORT_KEYS[@]}"; do
		port_key="${pair%%:*}"
		owner_step="${pair#*:}"
		step_component_enabled "$owner_step" || continue
		public="${CONF[$port_key]:-}"
		[[ -z "$public" ]] && continue
		if [[ "$port_key" != "METRICS_BACKEND_PORT" && "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]]; then
			if ! step_access_check && preflight_port_busy "$public"; then
				who=$(preflight_port_owner "$public")
				echo "$port_key|$public|${who:-unknown process}|$(preflight_free_port "$port_key" "$((public + 1))")|nginx"
			fi
			port=$(access_backend_port "$public")
		else
			port="$public"
		fi
		if "step_${owner_step}_check"; then
			continue
		fi
		if preflight_port_busy "$port"; then
			who=$(preflight_port_owner "$port")
			echo "$port_key|$port|${who:-unknown process}|$(preflight_free_port "$port_key" "$((public + 1))")|service"
		fi
	done
}

# preflight_resolve_ports_interactive - for every busy port: a warning with
# the name of the process that holds it and the question which port to use
# instead (Enter takes the suggested free one, "q" leaves the port as it is
# and the preflight will stop on it). Reads through the menu's input, so it
# runs inside the menu. Returns 0 when no conflicts remain unanswered.
preflight_resolve_ports_interactive() {
	local line key port who suggestion kind answer rc=0
	while IFS= read -r line; do
		[[ -z "$line" ]] && continue
		IFS='|' read -r key port who suggestion kind <<<"$line"
		echo >&2
		echo "  WARNING: port $port ($key) is already busy: $who" >&2
		while true; do
			menu_read answer "  Another port for $key [${suggestion:-none free}] (q: keep): "
			menu_die_on_eof
			[[ -z "$answer" ]] && answer="$suggestion"
			if [[ "$answer" == "q" || "$answer" == "Q" ]]; then
				rc=1
				break
			fi
			if [[ ! "$answer" =~ ^[0-9]+$ ]] || ((10#$answer < 1 || 10#$answer > 65535)); then
				echo "  a number from 1 to 65535 is needed" >&2
				continue
			fi
			answer=$((10#$answer))
			if preflight_port_busy "$answer" || preflight_port_taken_by_conf "$answer" "$key"; then
				echo "  port $answer is busy too, choose another" >&2
				continue
			fi
			if [[ "$kind" == "nginx" || "${CONF[ACCESS_MODE]:-localhost}" == "nginx" ]] && [[ "$key" != "METRICS_BACKEND_PORT" ]]; then
				local behind
				behind=$(access_backend_port "$answer")
				if ((behind > 65535)) || preflight_port_busy "$behind" || preflight_port_taken_by_conf "$behind" "$key"; then
					echo "  with nginx in front it also needs port $behind, which is unavailable; choose another" >&2
					continue
				fi
			fi
			CONF["$key"]="$answer"
			echo "  $key = $answer" >&2
			# shellcheck disable=SC2034 # read by lib/menu.sh
			MENU_DIRTY=1
			break
		done
	done < <(preflight_port_conflicts)
	return "$rc"
}

# preflight_panel_reasons - the panel binary has to be obtainable before
# the install starts: a ready file for prebuilt, Go (at least the version
# panel/go.mod asks for) for build. A binary that is already installed and
# current needs neither, so a repeat run on a host without Go still passes.
preflight_panel_reasons() {
	panel_bin_current && return 0
	if [[ "$(panel_source_mode)" == "prebuilt" ]]; then
		if [[ ! -f "$(panel_prebuilt_path)" ]]; then
			reasons+=("PANEL_SOURCE=prebuilt, but there is no ready dpistack-panel binary next to install.sh (in the release archive it is called $(basename "$(panel_prebuilt_path)"))")
		fi
		return 0
	fi
	if [[ ! -d "$ORIGIN_DIR/panel" ]]; then
		reasons+=("cannot get the panel: next to install.sh there is neither a ready binary ($(basename "$(panel_prebuilt_path)")), nor a panel/ directory with the sources")
		return 0
	fi
	local need
	need=$(panel_go_required)
	# A Go that is not on the host is no reason to stop when Docker can build
	# the panel in a Go image (step_panel.sh, panel_build_in_container).
	panel_host_go_ok && return 0
	panel_can_build_in_container && return 0
	if ! command -v go >/dev/null 2>&1; then
		reasons+=("cannot get the panel: there is no Go (Go ${need:-newer} is needed), no Docker to build it in a container, and no ready binary next to install.sh ($(basename "$(panel_prebuilt_path)"))")
	else
		reasons+=("cannot get the panel: Go $(go version | sed -n 's/^go version go\([0-9][0-9.]*\).*/\1/p') is older than the required $need, there is no Docker to build it in a container and no ready binary next to install.sh ($(basename "$(panel_prebuilt_path)"))")
	fi
}

step_preflight_reasons() {
	local reasons=()

	if [[ "${EUID:-$(id -u)}" -ne 0 ]]; then
		reasons+=("root rights are needed")
	fi

	if ((BASH_VERSINFO[0] < 4 || (BASH_VERSINFO[0] == 4 && BASH_VERSINFO[1] < 4))); then
		reasons+=("Bash 4.4+ is needed, now ${BASH_VERSINFO[0]}.${BASH_VERSINFO[1]}")
	fi

	if ! command -v systemctl >/dev/null 2>&1; then
		reasons+=("systemd (systemctl) not found, needed for the native runtime")
	fi

	if preflight_step_wanted panel; then
		preflight_panel_reasons
	fi

	local key
	for key in SURICATA_RUNTIME EVEBOX_RUNTIME NTOPNG_RUNTIME METRICS_BACKEND_RUNTIME PANEL_RUNTIME; do
		if [[ "${CONF[$key]:-}" == "docker" ]] && ! command -v docker >/dev/null 2>&1; then
			reasons+=("$key=docker, but docker was not found")
		fi
	done

	# Outside apt and dnf there are no packages of the project's components:
	# they run in Docker, and the reason says which keys to set.
	if [[ "$OS_FAMILY" != "apt" && "$OS_FAMILY" != "dnf" ]]; then
		local nkey
		for nkey in SURICATA_RUNTIME EVEBOX_RUNTIME NTOPNG_RUNTIME; do
			if [[ "${CONF[$nkey]:-native}" == "native" ]]; then
				reasons+=("$nkey=native: on $OS_ID the installer does not install the component packages, set --set $nkey=docker")
			fi
		done
		if [[ "${CONF[METRICS_BACKEND]:-none}" != "none" && "${CONF[METRICS_BACKEND_RUNTIME]:-native}" == "native" ]]; then
			reasons+=("METRICS_BACKEND_RUNTIME=native: on $OS_ID set --set METRICS_BACKEND_RUNTIME=docker")
		fi
		if [[ "${CONF[NDPI_ENABLE]:-no}" == "yes" ]]; then
			reasons+=("NDPI_ENABLE=yes: the nDPI plugin needs a Suricata built on the host; on $OS_ID set --set NDPI_ENABLE=no")
		fi
	fi
	if [[ "${CONF[SURICATA_MODE]:-ids}" == "ips" && "${CONF[IPS_METHOD]:-nfq}" == "nfq" ]] && [[ -z "$(ips_backend)" ]]; then
		reasons+=("SURICATA_MODE=ips with IPS_METHOD=nfq: neither iptables nor nft found (needed for the NFQUEUE queue)")
	fi
	if [[ "${CONF[SURICATA_RUNTIME]:-native}" == "docker" && "${CONF[NDPI_ENABLE]:-no}" == "yes" ]]; then
		reasons+=("SURICATA_RUNTIME=docker: the nDPI plugin is not installed into the image, set NDPI_ENABLE=no")
	fi
	if command -v docker >/dev/null 2>&1; then
		local dkey
		for dkey in SURICATA_RUNTIME EVEBOX_RUNTIME NTOPNG_RUNTIME PANEL_RUNTIME; do
			if [[ "${CONF[$dkey]:-}" == "docker" ]] && ! docker compose version >/dev/null 2>&1; then
				reasons+=("$dkey=docker, but docker has no compose plugin (docker compose version does not answer)")
				break
			fi
		done
	fi

	case "$(os_support_level)" in
	unsupported)
		if [[ "${DPISTACK_ALLOW_UNSUPPORTED:-0}" != "1" ]]; then
			reasons+=("$OS_ID ${OS_VERSION_ID:-} is not supported (supported: Ubuntu LTS from 22.04, Debian from 12, Rocky Linux and AlmaLinux from 8); to go on at your own risk: DPISTACK_ALLOW_UNSUPPORTED=1")
		fi
		;;
	unverified)
		log "WARN" "$OS_ID ${OS_VERSION_ID:-} is not in the list of tested platforms (tech.md 11), the installation goes on"
		;;
	esac

	local iface _preflight_ifaces
	IFS=',' read -ra _preflight_ifaces <<<"${CONF[IFACES]:-}"
	for iface in "${_preflight_ifaces[@]}"; do
		[[ -z "$iface" ]] && continue
		if ! net_iface_exists "$iface"; then
			reasons+=("interface $iface from IFACES does not exist")
		fi
	done

	local bind_addr="${CONF[BIND_ADDR]:-auto}"
	if [[ "$bind_addr" != "auto" && "${CONF[ACCESS_MODE]:-localhost}" != "nginx" ]] && [[ "$bind_addr" != 127.* ]]; then
		if ! access_local_addresses | awk -v a="$bind_addr" '$2 == a {found = 1} END {exit !found}'; then
			reasons+=("BIND_ADDR=$bind_addr is not an address of this host")
		fi
	fi

	local need_gb=1
	[[ "${CONF[SURICATA_SOURCE]:-}" == "source" ]] && need_gb=4
	local avail_kb
	avail_kb=$(df --output=avail -k / 2>/dev/null | tail -n1 | tr -d ' ')
	if [[ "$avail_kb" =~ ^[0-9]+$ ]]; then
		local need_kb=$((need_gb * 1024 * 1024))
		if ((avail_kb < need_kb)); then
			reasons+=("at least ${need_gb} GB of free space is needed, there is less")
		fi
	fi

	# The repositories the selected steps are going to use must answer now,
	# not in the middle of the install.
	local probe
	local -a probes=()
	if [[ "${CONF[SURICATA_SOURCE]:-}" == "oisf" ]]; then
		if [[ "$OS_FAMILY" == "dnf" ]]; then
			# The repo file exists only for chroots the project builds for:
			# a missing one (a new Rocky release, say) must stop here with
			# code 3, not in the middle of `dnf copr enable`.
			local chroot
			chroot=$(copr_chroot)
			if [[ -n "$chroot" ]]; then
				probes+=("OISF COPR for $chroot|${OISF_COPR_REPO_URL:-https://copr.fedorainfracloud.org/coprs/g/oisf/suricata-8.0/repo/${chroot}/group_oisf-suricata-8.0-${chroot}.repo}")
			else
				probes+=("OISF COPR|https://copr.fedorainfracloud.org/coprs/g/oisf/suricata-8.0/")
			fi
		else
			probes+=("OISF PPA|https://ppa.launchpadcontent.net/oisf/suricata-stable/ubuntu/")
		fi
	fi
	if preflight_step_wanted ntopng; then
		if [[ "$OS_FAMILY" == "dnf" ]]; then
			probes+=("ntop.org|${NTOP_REPO_RPM_URL:-https://packages.ntop.org/centos-stable/ntop.repo}")
		else
			probes+=("ntop.org|${NTOP_REPO_DEB_URL_APT:-https://packages.ntop.org/apt-stable}/")
		fi
	fi
	if preflight_step_wanted evebox; then
		if [[ "$OS_FAMILY" == "dnf" ]]; then
			probes+=("EveBox|${EVEBOX_RPM_RELEASE_URL:-https://evebox.org/files/rpm/stable/evebox-release.noarch.rpm}")
		else
			probes+=("EveBox|${EVEBOX_REPO_URL:-https://evebox.org/files/debian}/")
		fi
	fi
	for probe in "${probes[@]}"; do
		if ! curl -fsS --max-time 5 -o /dev/null -- "${probe#*|}"; then
			reasons+=("repository ${probe%%|*} is unavailable (${probe#*|})")
		fi
	done

	if [[ "${CONF[EVEBOX_DB]:-sqlite}" == "elasticsearch" ]]; then
		if ! curl -fsS --max-time 5 -o /dev/null -- "${CONF[EVEBOX_ES_URL]:-}"; then
			reasons+=("Elasticsearch from EVEBOX_ES_URL (${CONF[EVEBOX_ES_URL]:-}) is unavailable")
		fi
	fi

	# A busy port stops a run without a terminal; the menu asks for another
	# one instead (preflight_resolve_ports_interactive). The reason names the
	# holder and a free port to pass with --set.
	local pline pkey pport pwho psuggest pkind
	while IFS= read -r pline; do
		[[ -z "$pline" ]] && continue
		IFS='|' read -r pkey pport pwho psuggest pkind <<<"$pline"
		if [[ "$pkind" == "nginx" ]]; then
			reasons+=("port $pport ($pkey) is already busy, and nginx must listen on it (held by: $pwho)${psuggest:+; free: --set $pkey=$psuggest}")
		else
			reasons+=("port $pport ($pkey) is already busy (held by: $pwho)${psuggest:+; free: --set $pkey=$psuggest}")
		fi
	done < <(preflight_port_conflicts)

	if command -v getenforce >/dev/null 2>&1; then
		log "INFO" "SELinux: $(getenforce 2>/dev/null || echo unknown)"
	fi

	printf '%s\n' "${reasons[@]}"
}

step_preflight_check() {
	local reasons
	reasons=$(step_preflight_reasons)
	if [[ -n "$reasons" ]]; then
		echo "preflight: problems found:" >&2
		echo "  - ${reasons//$'\n'/$'\n  - '}" >&2
		return 1
	fi
	return 0
}

step_preflight_apply() {
	# The real gate already ran via step_preflight_check before
	# run_plan/run_apply started; nothing left to change here.
	return 0
}

step_preflight_plan() {
	echo "preflight: no changes"
}
DPISTACK_BUNDLE_END
